import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, Milestone, Lookup, MilestoneStatus, Language, PaymentStatus, User } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';
import ProjectDetailModal from './ProjectDetailModal';
import PaymentStatusWidget from './PaymentStatusWidget';
import TeamProjectsModal from './TeamProjectsModal';

// --- Widget Component Definitions ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, showPadding?: boolean }> = ({ title, children, maxHeight = '400px', showPadding = true }) => (
    <div className={`bg-white dark:bg-gray-800/50 ${showPadding ? 'p-6' : 'pt-6'} rounded-2xl shadow-sm dark:shadow-none h-full flex flex-col`}>
        <h2 className={`text-xl font-semibold text-gray-900 dark:text-white mb-4 ${showPadding ? '' : 'px-6'}`}>{title}</h2>
        <div className="flex-grow overflow-y-auto" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, language }) => {
    const t = translations[language];
    const totalProjects = projects.length;
    const completedMilestonesCount = milestones.filter(a => a.status === MilestoneStatus.Completed).length;
    const inProgressMilestonesCount = milestones.filter(a => a.status === MilestoneStatus.InProgress).length;
    const totalMilestones = milestones.length;

    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title={t.totalProjects} value={totalProjects.toString()} icon="projects" />
            <StatCard title={t.totalMilestones} value={totalMilestones.toString()} icon="completed" />
            <StatCard title={t.inProgressMilestones} value={inProgressMilestonesCount.toString()} icon="inProgress" />
            <StatCard title={t.completedMilestones} value={completedMilestonesCount.toString()} icon="hours" />
        </div>
    );
};

const ProjectsWeightWidget: React.FC<AnalyticsDashboardProps> = ({ projects, language }) => {
    const t = translations[language];
    const [searchTerm, setSearchTerm] = useState('');
    const [minScore, setMinScore] = useState<string>('');
    const [maxScore, setMaxScore] = useState<string>('');

    const projectsWithScores = useMemo(() => {
        return projects.map(p => {
            const score = (
                (p.revenueImpact || 1) + 
                (p.strategicValue || 1) + 
                (p.deliveryRisk || 1) + 
                (p.customerPressure || 1)
            ) - (p.resourceLoad || 1);
            return { name: p.name, score, code: p.projectCode };
        }).filter(p => {
            const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                                 p.code.toLowerCase().includes(searchTerm.toLowerCase());

            const min = minScore === '' ? -Infinity : Number(minScore);
            const max = maxScore === '' ? Infinity : Number(maxScore);
            const matchesScore = p.score >= min && p.score <= max;

            return matchesSearch && matchesScore;
        }).sort((a, b) => b.score - a.score);
    }, [projects, searchTerm, minScore, maxScore]);

    // Max score in theory with this formula is (5+5+5+5) - 1 = 19
    const maxPossibleScore = 19;

    const inputClasses = "p-1.5 bg-slate-100 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-[11px]";

    return (
