const ProjectStatusChartWidget: React.FC<AnalyticsDashboardProps> = ({ projects, language }) => {
    const t = translations[language];
    const statusCounts = useMemo(() => {
        const counts = new Map<string, { count: number, color: string }>();
        const colors = ['bg-green-500', 'bg-blue-500', 'bg-yellow-500', 'bg-red-500', 'bg-indigo-500', 'bg-pink-500'];
        let colorIndex = 0;
        projects.forEach(p => {
            const statusName = p.status?.name || t.unknownStatus;
            if (!counts.has(statusName)) {
                counts.set(statusName, { count: 0, color: colors[colorIndex % colors.length] });
                colorIndex++;
            }
            counts.get(statusName)!.count++;
        });
        return Array.from(counts.entries());
    }, [projects, t.unknownStatus]);

    const maxCount = Math.max(...statusCounts.map(([, {count}]) => count), 1);

    return (
        <WidgetWrapper title={t.projectStatuses} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {statusCounts.length > 0 ? statusCounts.map(([status, {count, color}]) => (
                    <div key={status} className="flex items-center gap-4">
                        <span className="w-1/3 text-sm text-gray-600 dark:text-gray-300 truncate">{status}</span>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4">
                                <div className={`${color} h-4 rounded-full transition-all duration-500`} style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm">{count}</span>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm">{t.noProjects}</p>}
            </div>
        </WidgetWrapper>
    );
};

interface TeamWorkloadChartWidgetProps extends AnalyticsDashboardProps {
    onTeamClick: (team: Lookup, teamProjects: Project[]) => void;
}

const TeamWorkloadChartWidget: React.FC<TeamWorkloadChartWidgetProps> = ({ projects, teams, language, onTeamClick }) => {
    const t = translations[language];
    const teamProjectCounts = useMemo(() => {
        const counts = new Map<string, { projects: Project[] }>();
        teams.forEach(t => counts.set(t.id, { projects: [] }));
        projects.forEach(p => {
            if (p.teamId && counts.has(p.teamId)) {
                counts.get(p.teamId)!.projects.push(p);
            }
        });
        return Array.from(counts.entries())
            .map(([teamId, data]) => ({ team: teams.find(t => t.id === teamId), count: data.projects.length, teamProjects: data.projects }))
            .filter(item => item.team)
            .sort((a,b) => b.count - a.count);
    }, [projects, teams]);

    const maxCount = Math.max(...teamProjectCounts.map(({ count }) => count), 1);

    return (
         <WidgetWrapper title={t.teamWorkload} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {teamProjectCounts.length > 0 ? teamProjectCounts.map(({ team, count, teamProjects }) => (
                    <div 
                        key={team!.id} 
                        className="flex items-center gap-4 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/30 p-2 rounded-xl transition-all group"
                        onClick={() => onTeamClick(team!, teamProjects)}
                    >
                        <div className="w-1/3 flex items-center gap-2">
                           <span className="text-sm text-gray-600 dark:text-gray-300 truncate group-hover:text-violet-600 dark:group-hover:text-violet-400 font-medium">{team!.name}</span>
                        </div>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 overflow-hidden">
                                <div className="bg-gradient-to-r from-violet-500 to-indigo-500 h-4 rounded-full transition-all duration-500 group-hover:brightness-110" style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm min-w-[1.5rem]">{count}</span>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm">{t.noTeams}</p>}
            </div>
        </WidgetWrapper>
    );
};

