                                                    <th className="pb-2 text-end">{t.amount}</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                                                {p.items.map((item, iIdx) => (
                                                    <tr key={iIdx} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                                        <td className="py-2 text-slate-700 dark:text-slate-200">{item.title}</td>
                                                        <td className="py-2 text-center">
                                                            <span className={`px-2 py-0.5 rounded-full font-bold text-[9px] ${item.status === MilestoneStatus.Completed ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'}`}>
                                                                {item.status}
                                                            </span>
                                                        </td>
                                                        <td className="py-2 text-end font-mono text-slate-500 dark:text-slate-400">
                                                            {item.hasPayment ? item.amount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }) : '--'}
                                                        </td>
                                                    </tr>
