interface AnalyticsDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    customers: Lookup[];
    projectManagers: User[];
    language: Language;
    currentUser?: User;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = (props) => {
    const { language } = props;
    const t = translations[language];

    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [layout, setLayout] = useState<string[]>([]);
    const [viewingProject, setViewingProject] = useState<Project | null>(null);
    const [viewingTeamProjects, setViewingTeamProjects] = useState<{ team: Lookup; projects: Project[] } | null>(null);

    useEffect(() => {
        try {
            const savedLayout = localStorage.getItem('dashboardLayout');
            if (savedLayout) {
                const parsedLayout = JSON.parse(savedLayout);
                const validWidgetIds = new Set(WIDGETS_CONFIG.map(w => w.id));
                const filteredLayout = parsedLayout.filter((id: string) => validWidgetIds.has(id));
                setLayout(filteredLayout);
            } else {
                setLayout(WIDGETS_CONFIG.filter(w => w.default).map(w => w.id));
            }
        } catch (error) {
            console.error("Failed to load dashboard layout", error);
            setLayout(WIDGETS_CONFIG.filter(w => w.default).map(w => w.id));
        }
    }, []);

    const handleSaveLayout = (newLayout: string[]) => {
        setLayout(newLayout);
        localStorage.setItem('dashboardLayout', JSON.stringify(newLayout));
        setIsCustomizeModalOpen(false);
    };

    const renderedWidgets = useMemo(() => {
        return layout.map(widgetId => {
            const widget = WIDGETS_CONFIG.find(w => w.id === widgetId);
            if (!widget) return null;
            const Component = widget.component as React.FC<any>; // Cast to allow custom callbacks
            const colSpan = widget.colSpan;
            const colSpanClass = `lg:col-span-${colSpan}`;

            return (
                <div key={widget.id} className={colSpanClass}>
                  <Component 
                    {...props} 
                    onViewProjectDetails={(p: any) => setViewingProject(p)} 
                    onTeamClick={(team: Lookup, teamProjects: Project[]) => setViewingTeamProjects({ team, projects: teamProjects })} 
                  />
                </div>
            );
        });
    }, [layout, props]);

    return (
        <div className="space-y-8">
             {isCustomizeModalOpen && (
                <CustomizeDashboardModal
                    isOpen={isCustomizeModalOpen}
                    onClose={() => setIsCustomizeModalOpen(false)}
                    currentLayout={layout}
                    onSaveLayout={handleSaveLayout}
                    language={language}
                />
            )}
            {viewingProject && (
                <ProjectDetailModal
                    projectWithMilestones={{
                        ...viewingProject,
                        milestones: props.milestones.filter(m => m.projectId === viewingProject.id)
                    }}
                    onClose={() => setViewingProject(null)}
                    language={language}
                />
            )}
            {viewingTeamProjects && (
                <TeamProjectsModal
                    team={viewingTeamProjects.team}
                    projects={viewingTeamProjects.projects}
                    onClose={() => setViewingTeamProjects(null)}
                    language={language}
                    onViewProject={(p) => {
                        setViewingTeamProjects(null);
                        setViewingProject(p);
                    }}
                />
            )}
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{t.dashboard}</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">{t.overview}</p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-slate-200 dark:bg-slate-700/50 hover:bg-slate-300 dark:hover:bg-slate-600/50 text-slate-800 dark:text-white font-bold py-2 px-4 rounded-full flex items-center gap-2 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 000 3.464V16a1 1 0 102 0V8.732a2 2 0 00-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" /></svg>
                    <span>{t.customize}</span>
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                {renderedWidgets}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, Milestone, Lookup, MilestoneStatus, Language, PaymentStatus, User } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';
import ProjectDetailModal from './ProjectDetailModal';
import PaymentStatusWidget from './PaymentStatusWidget';
import TeamProjectsModal from './TeamProjectsModal';

// --- Widget Component Definitions ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, showPadding?: boolean }> = ({ title, children, maxHeight = '400px', showPadding = true }) => (
    <div className={`bg-white dark:bg-gray-800/50 ${showPadding ? 'p-6' : 'pt-6'} rounded-2xl shadow-sm dark:shadow-none h-full flex flex-col`}>
        <h2 className={`text-xl font-semibold text-gray-900 dark:text-white mb-4 ${showPadding ? '' : 'px-6'}`}>{title}</h2>
        <div className="flex-grow overflow-y-auto" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, language }) => {
    const t = translations[language];
    const totalProjects = projects.length;
    const completedMilestonesCount = milestones.filter(a => a.status === MilestoneStatus.Completed).length;
    const inProgressMilestonesCount = milestones.filter(a => a.status === MilestoneStatus.InProgress).length;
    const totalMilestones = milestones.length;

    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title={t.totalProjects} value={totalProjects.toString()} icon="projects" />
            <StatCard title={t.totalMilestones} value={totalMilestones.toString()} icon="completed" />
            <StatCard title={t.inProgressMilestones} value={inProgressMilestonesCount.toString()} icon="inProgress" />
            <StatCard title={t.completedMilestones} value={completedMilestonesCount.toString()} icon="hours" />
        </div>
    );
};

const AggregatedSummaryWidget: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, language }) => {
    const t = translations[language];

    // Filter states
    const [searchMilestone, setSearchMilestone] = useState('');
    const [filterProjectId, setFilterProjectId] = useState('all');
    const [filterStatus, setFilterStatus] = useState('all');
    const [filterMonthYear, setFilterMonthYear] = useState('all');

    // Sort states
    const [sortKey, setSortKey] = useState<'date' | 'name' | 'amount' | 'progress'>('date');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

    const projectOptions = useMemo(() => [
        { value: 'all', label: t.allProjects },
        ...projects.map(p => ({ value: p.id, label: p.name }))
    ], [projects, t.allProjects]);

    const statusOptions = useMemo(() => [
        { value: 'all', label: t.allStatuses },
        ...Object.values(MilestoneStatus).map(s => ({ value: s, label: s }))
    ], [t.allStatuses]);

    const monthYearOptions = useMemo(() => {
        const unique = new Set<string>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const key = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                unique.add(key);
            }
        });
        return [{ value: 'all', label: t.allMonths }, ...Array.from(unique).map(v => ({ value: v, label: v }))];
    }, [milestones, language, t.allMonths]);

    const sortOptions = [
        { value: 'date', label: t.sortByDate },
        { value: 'name', label: t.sortByName },
        { value: 'amount', label: t.sortByAmount },
        { value: 'progress', label: t.sortByProgress },
    ];

    const aggregatedData = useMemo(() => {
        const groups = new Map<string, {
            monthYear: string;
            sortKey: number;
            projects: Map<string, {
                projectName: string;
                projectCode: string;
                managerName: string;
                items: { title: string; status: string; amount: number; hasPayment: boolean }[];
                totalAmount: number;
                completedCount: number;
            }>
        }>();

        milestones.forEach(m => {
            if (!m.dueDate) return;
            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const key = `${monthName} ${year}`;
            const groupSortKey = year * 100 + date.getMonth();

            // Apply Filters
            if (filterMonthYear !== 'all' && key !== filterMonthYear) return;
            if (filterProjectId !== 'all' && m.projectId !== filterProjectId) return;
            if (filterStatus !== 'all' && m.status !== filterStatus) return;
            if (searchMilestone && !m.title.toLowerCase().includes(searchMilestone.toLowerCase())) return;

            if (!groups.has(key)) {
                groups.set(key, { monthYear: key, sortKey: groupSortKey, projects: new Map() });
            }

            const project = projects.find(p => p.id === m.projectId);
            const projectName = project ? project.name : t.unknownProject;
            const projectId = m.projectId;

            const group = groups.get(key)!;
            if (!group.projects.has(projectId)) {
                group.projects.set(projectId, {
                    projectName,
                    projectCode: project?.projectCode || '',
                    managerName: project?.projectManager?.name || t.unassigned,
                    items: [],
                    totalAmount: 0,
                    completedCount: 0
                });
            }

            const pData = group.projects.get(projectId)!;
            pData.items.push({
                title: m.title,
                status: m.status,
                amount: m.paymentAmount || 0,
                hasPayment: m.hasPayment
            });
            if (m.hasPayment) pData.totalAmount += (m.paymentAmount || 0);
            if (m.status === MilestoneStatus.Completed) pData.completedCount += 1;
        });

        // 1. Sort the Months (Groups)
        let sortedGroups = Array.from(groups.values());
        if (sortKey === 'date') {
            sortedGroups.sort((a, b) => sortOrder === 'desc' ? b.sortKey - a.sortKey : a.sortKey - b.sortKey);
        }

        return sortedGroups.map(group => {
            // 2. Sort projects within each month
            let projectsInGroup = Array.from(group.projects.values());

            projectsInGroup.sort((a, b) => {
                let result = 0;
                if (sortKey === 'name') result = a.projectName.localeCompare(b.projectName);
                if (sortKey === 'amount') result = b.totalAmount - a.totalAmount;
                if (sortKey === 'progress') result = (b.completedCount / (b.items.length || 1)) - (a.completedCount / (a.items.length || 1));

                return sortOrder === 'desc' ? result : -result;
            });

            return {
                monthYear: group.monthYear,
                projects: projectsInGroup
            };
        });
    }, [milestones, projects, language, t.unknownProject, t.unassigned, filterProjectId, filterStatus, filterMonthYear, searchMilestone, sortKey, sortOrder]);

    const inputClasses = "p-2 bg-slate-100 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-[12px] w-full";

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="700px">
            {/* Filters & Sort Toolbar */}
            <div className="bg-slate-50 dark:bg-slate-900/20 p-4 rounded-xl border border-slate-100 dark:border-slate-800 mb-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 mb-4">
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">{t.searchMilestones}</label>
                        <input 
                            type="text" 
                            value={searchMilestone} 
                            onChange={(e) => setSearchMilestone(e.target.value)} 
                            placeholder={t.searchPlaceholder}
                            className={inputClasses}
                        />
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">{t.project}</label>
                        <SearchableSelect 
                            options={projectOptions} 
                            value={filterProjectId} 
                            onChange={setFilterProjectId} 
                            placeholder={t.allProjects} 
                            language={language}
                        />
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">{t.status}</label>
                        <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className={inputClasses}>
                            {statusOptions.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                        </select>
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">{t.monthYear}</label>
                        <select value={filterMonthYear} onChange={(e) => setFilterMonthYear(e.target.value)} className={inputClasses}>
                            {monthYearOptions.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                        </select>
                    </div>
                </div>

                {/* Sorting Controls Row */}
                <div className="flex flex-wrap items-center gap-4 pt-3 border-t border-slate-200 dark:border-slate-800">
                    <div className="flex items-center gap-2">
                        <span className="text-[10px] font-bold text-slate-400 uppercase">{t.sortBy}:</span>
                        <div className="flex bg-slate-200 dark:bg-slate-800 p-1 rounded-lg">
                            {sortOptions.map(opt => (
                                <button 
                                    key={opt.value}
                                    onClick={() => setSortKey(opt.value as any)}
                                    className={`px-3 py-1 text-[11px] font-bold rounded-md transition-all ${sortKey === opt.value ? 'bg-white dark:bg-slate-700 text-violet-600 dark:text-violet-400 shadow-sm' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                                >
                                    {opt.label}
                                </button>
                            ))}
                        </div>
                    </div>
                    <button 
                        onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
                        className="p-2 bg-slate-200 dark:bg-slate-800 rounded-lg text-slate-600 dark:text-slate-400 hover:text-violet-600 transition-colors"
                        title={sortOrder === 'asc' ? t.ascending : t.descending}
                    >
                        {sortOrder === 'asc' ? (
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4h13M3 8h9m-9 4h6m4 0l4-4m0 0l4 4m-4-4v12" /></svg>
                        ) : (
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4h13M3 8h9m-9 4h9m5-1v12m0 0l-4-4m4 4l4-4" /></svg>
                        )}
                    </button>
                </div>
            </div>

            <div className="space-y-8">
                {aggregatedData.length > 0 ? aggregatedData.map((group, idx) => (
                    <div key={idx} className="border-b border-slate-100 dark:border-slate-700/50 last:border-0 pb-6">
                        <h3 className="text-md font-black text-violet-600 dark:text-violet-400 mb-4 flex items-center gap-2 bg-violet-50 dark:bg-violet-900/20 px-3 py-2 rounded-lg w-max">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M6 2a1 1 0 00-1 1v1H4a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V6a2 2 0 00-2-2h-1V3a1 1 0 10-2 0v1H7V3a1 1 0 00-1-1zm0 5a1 1 0 000 2h8a1 1 0 100-2H6z" clipRule="evenodd" /></svg>
                            {group.monthYear}
                        </h3>

                        <div className="space-y-4">
                            {group.projects.map((p, pIdx) => (
                                <div key={pIdx} className="bg-white dark:bg-slate-800/40 rounded-xl border border-slate-100 dark:border-slate-700 p-4">
                                    <div className="flex justify-between items-center mb-3">
                                        <div className="min-w-0">
                                            <h4 className="font-bold text-slate-800 dark:text-white text-sm flex items-center flex-wrap gap-2">
                                                <span>{p.projectName}</span>
                                                <span className="text-[10px] font-bold text-violet-600 dark:text-violet-400 bg-violet-100 dark:bg-violet-900/40 px-2 py-0.5 rounded">
                                                    {p.managerName}
                                                </span>
                                            </h4>
                                            <p className="text-[10px] font-mono text-slate-400 mt-1">{p.projectCode}</p>
                                        </div>
                                        <div className="text-right shrink-0 flex items-center gap-6">
                                            <div>
                                                <p className="text-[9px] text-slate-400 uppercase font-bold">{t.completed}</p>
                                                <p className="text-xs font-bold text-violet-600 dark:text-violet-400">{Math.round((p.completedCount / p.items.length) * 100)}%</p>
                                            </div>
                                            {p.totalAmount > 0 && (
                                                <div>
                                                    <p className="text-[9px] text-slate-400 uppercase font-bold">{t.totalAmount}</p>
                                                    <p className="text-sm font-black text-green-600 dark:text-green-400">{p.totalAmount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                    <div className="overflow-x-auto">
                                        <table className="w-full text-xs text-left rtl:text-right">
                                            <thead className="text-slate-400 font-medium border-b border-slate-50 dark:border-slate-800">
                                                <tr>
                                                    <th className="pb-2 font-semibold">{t.milestone}</th>
                                                    <th className="pb-2 text-center">{t.status}</th>
                                                    <th className="pb-2 text-end">{t.amount}</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                                                {p.items.map((item, iIdx) => (
                                                    <tr key={iIdx} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
