    const [filterProjectId, setFilterProjectId] = useState('all');
    const [filterStatus, setFilterStatus] = useState('all');
    const [filterMonthYear, setFilterMonthYear] = useState('all');

    // Sort states
    const [sortKey, setSortKey] = useState<'name' | 'amount' | 'progress'>('name');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');

    // Collapsible state
    const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});

    const projectOptions = useMemo(() => [
        { value: 'all', label: t.allProjects },
        ...projects.map(p => ({ value: p.id, label: p.name }))
    ], [projects, t.allProjects]);

    const statusOptions = useMemo(() => [
        { value: 'all', label: t.allStatuses },
        ...Object.values(MilestoneStatus).map(s => ({ value: s, label: s }))
    ], [t.allStatuses]);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!unique.has(label)) {
                    unique.set(label, { label, sortKey });
                }
            }
        });

        const sortedOptions = Array.from(unique.values())
            .sort((a, b) => b.sortKey - a.sortKey) // Latest months first at the top
            .map(v => ({ value: v.label, label: v.label }));

        return [{ value: 'all', label: t.allMonths }, ...sortedOptions];
    }, [milestones, language, t.allMonths]);

    const sortOptions = [
        { value: 'name', label: t.sortByName },
        { value: 'amount', label: t.sortByAmount },
        { value: 'progress', label: t.sortByProgress },
    ];

    const aggregatedData = useMemo(() => {
        const groups = new Map<string, {
            monthYear: string;
            sortKey: number;
            projects: Map<string, {
                projectName: string;
                projectCode: string;
                managerName: string;
                items: { title: string; status: string; amount: number; hasPayment: boolean }[];
                totalAmount: number;
                completedCount: number;
            }>
        }>();

        milestones.forEach(m => {
            if (!m.dueDate) return;
            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const groupSortKey = year * 100 + date.getMonth();

            // Apply Filters
            if (filterMonthYear !== 'all' && labelKey !== filterMonthYear) return;
            if (filterProjectId !== 'all' && m.projectId !== filterProjectId) return;
            if (filterStatus !== 'all' && m.status !== filterStatus) return;

            if (!groups.has(labelKey)) {
                groups.set(labelKey, { monthYear: labelKey, sortKey: groupSortKey, projects: new Map() });
            }

            const project = projects.find(p => p.id === m.projectId);
            const projectName = project ? project.name : t.unknownProject;
            const projectId = m.projectId;

            const group = groups.get(labelKey)!;
            if (!group.projects.has(projectId)) {
                group.projects.set(projectId, {
                    projectName,
                    projectCode: project?.projectCode || '',
                    managerName: project?.projectManager?.name || t.unassigned,
                    items: [],
                    totalAmount: 0,
                    completedCount: 0
                });
            }

            const pData = group.projects.get(projectId)!;
            pData.items.push({
                title: m.title,
                status: m.status,
                amount: m.paymentAmount || 0,
                hasPayment: m.hasPayment
            });
            if (m.hasPayment) pData.totalAmount += (m.paymentAmount || 0);
            if (m.status === MilestoneStatus.Completed) pData.completedCount += 1;
        });

        // 1. Sort the Months (Groups) ALWAYS chronologically (descending: newest first)
        let sortedGroups = Array.from(groups.values()).sort((a, b) => b.sortKey - a.sortKey);

        return sortedGroups.map(group => {
            // 2. Sort projects within each month based on UI Sort Buttons
            let projectsInGroup = Array.from(group.projects.values());

            projectsInGroup.sort((a, b) => {
                let result = 0;
                if (sortKey === 'name') result = a.projectName.localeCompare(b.projectName);
                if (sortKey === 'amount') result = b.totalAmount - a.totalAmount;
                if (sortKey === 'progress') result = (b.completedCount / (b.items.length || 1)) - (a.completedCount / (a.items.length || 1));

                return sortOrder === 'desc' ? result : -result;
            });

            return {
                monthYear: group.monthYear,
                projects: projectsInGroup
            };
        });
    }, [milestones, projects, language, t.unknownProject, t.unassigned, filterProjectId, filterStatus, filterMonthYear, sortKey, sortOrder]);

    const toggleGroup = (key: string) => {
        setExpandedGroups(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const expandAll = () => {
        const all: Record<string, boolean> = {};
        aggregatedData.forEach(g => all[g.monthYear] = true);
        setExpandedGroups(all);
    };

    const collapseAll = () => {
        setExpandedGroups({});
    };

    const inputClasses = "p-1.5 bg-slate-100 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-[11px] w-full";

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="500px">
            {/* Filters & Sort Toolbar - More Compact */}
            <div className="bg-slate-50 dark:bg-slate-900/20 p-3 rounded-xl border border-slate-100 dark:border-slate-800 mb-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2 mb-3">
                    <div className="space-y-0.5">
                        <label className="text-[9px] font-bold text-slate-400 uppercase">{t.project}</label>
                        <SearchableSelect 
                            options={projectOptions} 
                            value={filterProjectId} 
                            onChange={setFilterProjectId} 
                            placeholder={t.allProjects} 
                            language={language}
                        />
                    </div>
                    <div className="space-y-0.5">
                        <label className="text-[9px] font-bold text-slate-400 uppercase">{t.status}</label>
                        <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className={inputClasses}>
                            {statusOptions.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                        </select>
                    </div>
                    <div className="space-y-0.5">
                        <label className="text-[9px] font-bold text-slate-400 uppercase">{t.monthYear}</label>
                        <SearchableSelect 
                            options={monthYearOptions} 
                            value={filterMonthYear} 
                            onChange={setFilterMonthYear} 
                            placeholder={t.allMonths} 
                            searchPlaceholder={t.searchMonths}
                            language={language}
                        />
                    </div>
                </div>

                {/* Sorting & Expand/Collapse Controls */}
                <div className="flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-slate-200 dark:border-slate-800">
                    <div className="flex items-center gap-3">
                        <div className="flex items-center gap-1.5">
                            <span className="text-[9px] font-bold text-slate-400 uppercase">{t.sortBy}:</span>
                            <div className="flex bg-slate-200 dark:bg-slate-800 p-0.5 rounded-lg">
                                {sortOptions.map(opt => (
                                    <button 
                                        key={opt.value}
                                        onClick={() => setSortKey(opt.value as any)}
                                        className={`px-2 py-0.5 text-[10px] font-bold rounded-md transition-all ${sortKey === opt.value ? 'bg-white dark:bg-slate-700 text-violet-600 dark:text-violet-400 shadow-sm' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                                    >
                                        {opt.label}
                                    </button>
                                ))}
                            </div>
                        </div>
                        <button 
                            onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
                            className="p-1 bg-slate-200 dark:bg-slate-800 rounded text-slate-600 dark:text-slate-400 hover:text-violet-600 transition-colors"
                            title={sortOrder === 'asc' ? t.ascending : t.descending}
                        >
                            {sortOrder === 'asc' ? (
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4h13M3 8h9m-9 4h6m4 0l4-4m0 0l4 4m-4-4v12" /></svg>
                            ) : (
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4h13M3 8h9m-9 4h9m5-1v12m0 0l-4-4m4 4l4-4" /></svg>
                            )}
                        </button>
                    </div>

                    <div className="flex items-center gap-2">
                        <button onClick={expandAll} className="text-[9px] font-bold text-violet-600 hover:underline uppercase">{t.expandAll}</button>
                        <span className="text-slate-300">|</span>
                        <button onClick={collapseAll} className="text-[9px] font-bold text-slate-500 hover:underline uppercase">{t.collapseAll}</button>
                    </div>
                </div>
            </div>

            <div className="space-y-2 pb-2">
                {aggregatedData.length > 0 ? aggregatedData.map((group, idx) => {
                    const isExpanded = !!expandedGroups[group.monthYear];
                    return (
                        <div key={idx} className="bg-slate-50/50 dark:bg-slate-900/10 rounded-xl border border-slate-100 dark:border-slate-800 overflow-hidden">
                            <button 
                                onClick={() => toggleGroup(group.monthYear)}
                                className="w-full flex items-center justify-between p-3 hover:bg-slate-100 dark:hover:bg-slate-800/40 transition-colors"
                            >
                                <div className="flex items-center gap-2.5">
                                    <div className={`p-1 rounded-md transition-colors ${isExpanded ? 'bg-violet-600 text-white' : 'bg-slate-200 dark:bg-slate-800 text-slate-500'}`}>
                                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                                    </div>
                                    <h3 className="text-xs font-black text-slate-800 dark:text-white flex items-center gap-2">
                                        {group.monthYear}
                                        <span className="text-[9px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-500 px-1.5 py-0.5 rounded-full">
                                            {group.projects.length} {t.projectsCount}
                                        </span>
                                    </h3>
                                </div>
                                {!isExpanded && (
                                    <div className="flex gap-4 text-[9px] font-bold text-slate-400 uppercase">
                                        <span>{t.total}: {group.projects.reduce((acc, p) => acc + p.totalAmount, 0).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}</span>
                                    </div>
                                )}
                            </button>

                            {isExpanded && (
                                <div className="p-3 pt-0 space-y-3 animate-in fade-in slide-in-from-top-1 duration-200">
                                    {group.projects.map((p, pIdx) => (
                                        <div key={pIdx} className="bg-white dark:bg-slate-800/60 rounded-lg border border-slate-100 dark:border-slate-700 p-3 shadow-sm">
                                            <div className="flex justify-between items-center mb-2">
                                                <div className="min-w-0">
                                                    <h4 className="font-bold text-slate-800 dark:text-white text-[12px] flex items-center flex-wrap gap-1.5">
                                                        <span>{p.projectName}</span>
                                                        <span className="text-[9px] font-bold text-violet-600 dark:text-violet-400 bg-violet-100 dark:bg-violet-900/40 px-1.5 py-0.2 rounded">
                                                            {p.managerName}
                                                        </span>
                                                    </h4>
                                                    <p className="text-[9px] font-mono text-slate-400 mt-0.5">{p.projectCode}</p>
                                                </div>
                                                <div className="text-right shrink-0 flex items-center gap-4">
                                                    <div>
                                                        <p className="text-[8px] text-slate-400 uppercase font-bold">{t.completed}</p>
                                                        <p className="text-[10px] font-bold text-violet-600 dark:text-violet-400">{Math.round((p.completedCount / p.items.length) * 100)}%</p>
                                                    </div>
                                                    {p.totalAmount > 0 && (
                                                        <div>
                                                            <p className="text-[8px] text-slate-400 uppercase font-bold">{t.totalAmount}</p>
                                                            <p className="text-[11px] font-black text-green-600 dark:text-green-400">{p.totalAmount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}</p>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                            <div className="overflow-x-auto">
                                                <table className="w-full text-[11px] text-left rtl:text-right">
                                                    <thead className="text-slate-400 font-medium border-b border-slate-50 dark:border-slate-800">
                                                        <tr>
                                                            <th className="pb-1 font-semibold">{t.milestone}</th>
                                                            <th className="pb-1 text-center">{t.status}</th>
                                                            <th className="pb-1 text-end">{t.amount}</th>
                                                        </tr>
                                                    </thead>
                                                    <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                                                        {p.items.map((item, iIdx) => (
                                                            <tr key={iIdx} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                                                <td className="py-1.5 text-slate-700 dark:text-slate-200">{item.title}</td>
                                                                <td className="py-1.5 text-center">
                                                                    <span className={`px-1.5 py-0.2 rounded-full font-bold text-[8px] ${item.status === MilestoneStatus.Completed ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'}`}>
                                                                        {item.status}
                                                                    </span>
                                                                </td>
                                                                <td className="py-1.5 text-end font-mono text-slate-500 dark:text-slate-400">
                                                                    {item.hasPayment ? item.amount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }) : '--'}
                                                                </td>
                                                            </tr>
                                                        ))}
                                                    </tbody>
                                                </table>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                }) : (
                    <div className="text-center py-10 text-slate-400 text-xs italic bg-slate-50 dark:bg-slate-900/20 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-800">
                        {t.noMilestonesMatch}
                    </div>
                )}
            </div>
        </WidgetWrapper>
    );
};

const ProjectsWeightWidget: React.FC<AnalyticsDashboardProps> = ({ projects, language }) => {
    const t = translations[language];
    const [searchTerm, setSearchTerm] = useState('');
    const [minScore, setMinScore] = useState<string>('');
    const [maxScore, setMaxScore] = useState<string>('');

    const projectsWithScores = useMemo(() => {
        return projects.map(p => {
            const score = (
                (p.revenueImpact || 1) + 
                (p.strategicValue || 1) + 
                (p.deliveryRisk || 1) + 
                (p.customerPressure || 1)
            ) - (p.resourceLoad || 1);
            return { name: p.name, score, code: p.projectCode };
        }).filter(p => {
            const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                                 p.code.toLowerCase().includes(searchTerm.toLowerCase());

            const min = minScore === '' ? -Infinity : Number(minScore);
            const max = maxScore === '' ? Infinity : Number(maxScore);
            const matchesScore = p.score >= min && p.score <= max;

            return matchesSearch && matchesScore;
        }).sort((a, b) => b.score - a.score);
    }, [projects, searchTerm, minScore, maxScore]);

    // Max score in theory with this formula is (5+5+5+5) - 1 = 19
    const maxPossibleScore = 19;

    const inputClasses = "p-1.5 bg-slate-100 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-[11px]";

    return (
        <WidgetWrapper title={t.projectsWeight} maxHeight="400px">
            <div className="flex flex-col gap-2 mb-4 px-1">
                <input 
                    type="text" 
                    placeholder={t.searchProjects} 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className={inputClasses + " w-full"}
                />
                <div className="flex items-center gap-2">
                    <span className="text-[10px] text-slate-400 font-bold uppercase shrink-0">{t.weightRange}:</span>
                    <input 
                        type="number" 
                        placeholder={t.from} 
                        value={minScore}
                        onChange={(e) => setMinScore(e.target.value)}
                        className={inputClasses + " w-full"}
                    />
                    <input 
                        type="number" 
                        placeholder={t.to} 
                        value={maxScore}
                        onChange={(e) => setMaxScore(e.target.value)}
                        className={inputClasses + " w-full"}
                    />
                </div>
            </div>
            <div className="space-y-4 pt-2">
                {projectsWithScores.length > 0 ? projectsWithScores.map((p, idx) => (
                    <div key={idx} className="group">
                        <div className="flex justify-between items-center mb-1">
                            <div className="flex flex-col">
                                <span className="text-sm font-bold text-slate-700 dark:text-slate-200 truncate max-w-[200px]">{p.name}</span>
                                <span className="text-[10px] font-mono text-slate-400">{p.code}</span>
                            </div>
                            <span className="text-sm font-black text-violet-600 dark:text-violet-400 bg-violet-50 dark:bg-violet-900/30 px-2 py-0.5 rounded-md">{p.score}</span>
                        </div>
                        <div className="w-full bg-slate-100 dark:bg-slate-700 rounded-full h-2 overflow-hidden">
                            <div 
                                className="bg-gradient-to-r from-violet-500 to-indigo-500 h-full rounded-full transition-all duration-1000 ease-out group-hover:brightness-110" 
                                style={{ width: `${Math.max(5, (p.score / maxPossibleScore) * 100)}%` }}
                            ></div>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm text-center py-4">{t.noProjects}</p>}
            </div>
        </WidgetWrapper>
    );
};

const ProjectStatusChartWidget: React.FC<AnalyticsDashboardProps> = ({ projects, language }) => {
    const t = translations[language];
    const statusCounts = useMemo(() => {
        const counts = new Map<string, { count: number, color: string }>();
        const colors = ['bg-green-500', 'bg-blue-500', 'bg-yellow-500', 'bg-red-500', 'bg-indigo-500', 'bg-pink-500'];
        let colorIndex = 0;
        projects.forEach(p => {
            const statusName = p.status?.name || t.unknownStatus;
            if (!counts.has(statusName)) {
                counts.set(statusName, { count: 0, color: colors[colorIndex % colors.length] });
                colorIndex++;
            }
            counts.get(statusName)!.count++;
        });
        return Array.from(counts.entries());
    }, [projects, t.unknownStatus]);

    const maxCount = Math.max(...statusCounts.map(([, {count}]) => count), 1);

    return (
        <WidgetWrapper title={t.projectStatuses} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {statusCounts.length > 0 ? statusCounts.map(([status, {count, color}]) => (
                    <div key={status} className="flex items-center gap-4">
                        <span className="w-1/3 text-sm text-gray-600 dark:text-gray-300 truncate">{status}</span>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4">
                                <div className={`${color} h-4 rounded-full transition-all duration-500`} style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm">{count}</span>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm">{t.noProjects}</p>}
            </div>
        </WidgetWrapper>
    );
};

interface TeamWorkloadChartWidgetProps extends AnalyticsDashboardProps {
    onTeamClick: (team: Lookup, teamProjects: Project[]) => void;
}

const TeamWorkloadChartWidget: React.FC<TeamWorkloadChartWidgetProps> = ({ projects, teams, language, onTeamClick }) => {
    const t = translations[language];
    const teamProjectCounts = useMemo(() => {
        const counts = new Map<string, { projects: Project[] }>();
        teams.forEach(t => counts.set(t.id, { projects: [] }));
        projects.forEach(p => {
            if (p.teamId && counts.has(p.teamId)) {
                counts.get(p.teamId)!.projects.push(p);
            }
        });
        return Array.from(counts.entries())
            .map(([teamId, data]) => ({ team: teams.find(t => t.id === teamId), count: data.projects.length, teamProjects: data.projects }))
            .filter(item => item.team)
            .sort((a,b) => b.count - a.count);
    }, [projects, teams]);

    const maxCount = Math.max(...teamProjectCounts.map(({ count }) => count), 1);

    return (
         <WidgetWrapper title={t.teamWorkload} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {teamProjectCounts.length > 0 ? teamProjectCounts.map(({ team, count, teamProjects }) => (
                    <div 
                        key={team!.id} 
                        className="flex items-center gap-4 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/30 p-2 rounded-xl transition-all group"
                        onClick={() => onTeamClick(team!, teamProjects)}
                    >
                        <div className="w-1/3 flex items-center gap-2">
                           <span className="text-sm text-gray-600 dark:text-gray-300 truncate group-hover:text-violet-600 dark:group-hover:text-violet-400 font-medium">{team!.name}</span>
                        </div>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 overflow-hidden">
                                <div className="bg-gradient-to-r from-violet-500 to-indigo-500 h-4 rounded-full transition-all duration-500 group-hover:brightness-110" style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm min-w-[1.5rem]">{count}</span>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm">{t.noTeams}</p>}
            </div>
        </WidgetWrapper>
    );
};

const ProjectsByLaunchYearWidget: React.FC<AnalyticsDashboardProps> = ({ projects, language }) => {
    const t = translations[language];
    const yearlyData = useMemo(() => {
        const counts = new Map<string, number>();
        projects.forEach(p => {
            const year = p.launchDate ? new Date(p.launchDate).getFullYear().toString() : t.noLaunchDate;
            counts.set(year, (counts.get(year) || 0) + 1);
        });
        return Array.from(counts.entries())
            .map(([year, count]) => ({ year, count }))
            .sort((a, b) => a.year.localeCompare(b.year));
    }, [projects, t.noLaunchDate]);

    const maxCount = Math.max(...yearlyData.map(({ count }) => count), 1);

    return (
        <WidgetWrapper title={t.projectsByYear} maxHeight="400px">
            <div className="space-y-3 pt-2 pr-2 rtl:pl-2">
                {yearlyData.length > 0 ? yearlyData.map(({ year, count }) => (
                    <div key={year} className="flex items-center gap-4">
                        <span className="w-1/4 text-sm text-gray-600 dark:text-gray-300 truncate">{year}</span>
