const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = (props) => {
    const { language } = props;
    const t = translations[language];

    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [layout, setLayout] = useState<string[]>([]);
    const [viewingProject, setViewingProject] = useState<Project | null>(null);
    const [viewingTeamProjects, setViewingTeamProjects] = useState<{ team: Lookup; projects: Project[] } | null>(null);

    useEffect(() => {
        try {
            const savedLayout = localStorage.getItem('dashboardLayout');
            if (savedLayout) {
                const parsedLayout = JSON.parse(savedLayout);
                const validWidgetIds = new Set(WIDGETS_CONFIG.map(w => w.id));
                const filteredLayout = parsedLayout.filter((id: string) => validWidgetIds.has(id));
                setLayout(filteredLayout);
            } else {
                setLayout(WIDGETS_CONFIG.filter(w => w.default).map(w => w.id));
            }
        } catch (error) {
            console.error("Failed to load dashboard layout", error);
            setLayout(WIDGETS_CONFIG.filter(w => w.default).map(w => w.id));
        }
    }, []);

    const handleSaveLayout = (newLayout: string[]) => {
        setLayout(newLayout);
        localStorage.setItem('dashboardLayout', JSON.stringify(newLayout));
        setIsCustomizeModalOpen(false);
    };

    const renderedWidgets = useMemo(() => {
        return layout.map(widgetId => {
            const widget = WIDGETS_CONFIG.find(w => w.id === widgetId);
            if (!widget) return null;
            const Component = widget.component as React.FC<any>; // Cast to allow custom callbacks
            const colSpan = widget.colSpan;
            const colSpanClass = `lg:col-span-${colSpan}`;

            return (
                <div key={widget.id} className={colSpanClass}>
                  <Component 
                    {...props} 
                    onViewProjectDetails={(p: any) => setViewingProject(p)} 
                    onTeamClick={(team: Lookup, teamProjects: Project[]) => setViewingTeamProjects({ team, projects: teamProjects })} 
                  />
                </div>
            );
        });
    }, [layout, props]);

    return (
        <div className="space-y-8">
             {isCustomizeModalOpen && (
                <CustomizeDashboardModal
                    isOpen={isCustomizeModalOpen}
                    onClose={() => setIsCustomizeModalOpen(false)}
                    currentLayout={layout}
                    onSaveLayout={handleSaveLayout}
                    language={language}
                />
            )}
            {viewingProject && (
                <ProjectDetailModal
                    projectWithMilestones={{
                        ...viewingProject,
                        milestones: props.milestones.filter(m => m.projectId === viewingProject.id)
                    }}
                    onClose={() => setViewingProject(null)}
                    language={language}
                />
            )}
            {viewingTeamProjects && (
                <TeamProjectsModal
                    team={viewingTeamProjects.team}
                    projects={viewingTeamProjects.projects}
                    onClose={() => setViewingTeamProjects(null)}
                    language={language}
                    onViewProject={(p) => {
                        setViewingTeamProjects(null);
                        setViewingProject(p);
                    }}
                />
            )}
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{t.dashboard}</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">{t.overview}</p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-slate-200 dark:bg-slate-700/50 hover:bg-slate-300 dark:hover:bg-slate-600/50 text-slate-800 dark:text-white font-bold py-2 px-4 rounded-full flex items-center gap-2 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 000 3.464V16a1 1 0 102 0V8.732a2 2 0 00-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" /></svg>
                    <span>{t.customize}</span>
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                {renderedWidgets}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, Milestone, Lookup, MilestoneStatus, Language, PaymentStatus, User } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';
import ProjectDetailModal from './ProjectDetailModal';
import TeamProjectsModal from './TeamProjectsModal';

// --- Widget Component Definitions ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, showPadding?: boolean }> = ({ title, children, maxHeight = '400px', showPadding = true }) => (
    <div className={`bg-white dark:bg-gray-800/50 ${showPadding ? 'p-6' : 'pt-6'} rounded-2xl shadow-sm dark:shadow-none h-full flex flex-col`}>
        <h2 className={`text-xl font-semibold text-gray-900 dark:text-white mb-4 ${showPadding ? '' : 'px-6'}`}>{title}</h2>
        <div className="flex-grow overflow-y-auto custom-scrollbar" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, language }) => {
    const t = translations[language];
    const totalProjects = projects.length;
    const completedMilestonesCount = milestones.filter(a => a.status === MilestoneStatus.Completed).length;
    const inProgressMilestonesCount = milestones.filter(a => a.status === MilestoneStatus.InProgress).length;
    const totalMilestones = milestones.length;

    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title={t.totalProjects} value={totalProjects.toString()} icon="projects" />
            <StatCard title={t.totalMilestones} value={totalMilestones.toString()} icon="completed" />
            <StatCard title={t.inProgressMilestones} value={inProgressMilestonesCount.toString()} icon="inProgress" />
            <StatCard title={t.completedMilestones} value={completedMilestonesCount.toString()} icon="hours" />
        </div>
    );
};

const AggregatedSummaryWidget: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, projectManagers, language }) => {
    const t = translations[language];

    // Filter states
    const [filterProjectId, setFilterProjectId] = useState('all');
    const [filterManagerId, setFilterManagerId] = useState('all');
    const [filterStatus, setFilterStatus] = useState('all');
    const [filterMonthYear, setFilterMonthYear] = useState('all');

    // Sort states
    const [sortKey, setSortKey] = useState<'date' | 'name' | 'amount' | 'progress'>('date');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

    // Collapsible state
    const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});

    const projectOptions = useMemo(() => [
        { value: 'all', label: t.allProjects },
        ...projects.map(p => ({ value: p.id, label: p.name }))
    ], [projects, t.allProjects]);

    const managerOptions = useMemo(() => [
        { value: 'all', label: t.allManagers },
        ...projectManagers.map(m => ({ value: m.id, label: m.name }))
    ], [projectManagers, t.allManagers]);

    const statusOptions = useMemo(() => [
        { value: 'all', label: t.allStatuses },
        ...Object.values(MilestoneStatus).map(s => ({ value: s, label: s }))
    ], [t.allStatuses]);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!unique.has(label)) {
                    unique.set(label, { label, sortKey });
                }
            }
        });

        const sortedOptions = Array.from(unique.values())
            .sort((a, b) => a.sortKey - b.sortKey)
            .map(v => ({ value: v.label, label: v.label }));

        return [{ value: 'all', label: t.allMonths }, ...sortedOptions];
    }, [milestones, language, t.allMonths]);

    const sortOptions = [
        { value: 'date', label: t.sortByDate },
        { value: 'name', label: t.sortByName },
        { value: 'amount', label: t.sortByAmount },
        { value: 'progress', label: t.sortByProgress },
    ];

    const aggregatedData = useMemo(() => {
        const groups = new Map<string, {
            monthYear: string;
            sortKey: number;
            projects: Map<string, {
                projectName: string;
                projectCode: string;
                managerName: string;
                items: { title: string; status: string; amount: number; hasPayment: boolean }[];
                totalAmount: number;
                completedCount: number;
            }>
        }>();

        milestones.forEach(m => {
            if (!m.dueDate) return;
            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const groupSortKey = year * 100 + date.getMonth();

            const project = projects.find(p => p.id === m.projectId);

            if (filterMonthYear !== 'all' && labelKey !== filterMonthYear) return;
            if (filterProjectId !== 'all' && m.projectId !== filterProjectId) return;
            if (filterStatus !== 'all' && m.status !== filterStatus) return;
            if (filterManagerId !== 'all' && project?.projectManagerId !== filterManagerId) return;

            if (!groups.has(labelKey)) {
                groups.set(labelKey, { monthYear: labelKey, sortKey: groupSortKey, projects: new Map() });
            }

            const projectName = project ? project.name : t.unknownProject;
            const projectId = m.projectId;

            const group = groups.get(labelKey)!;
            if (!group.projects.has(projectId)) {
                group.projects.set(projectId, {
                    projectName,
                    projectCode: project?.projectCode || '',
                    managerName: project?.projectManager?.name || t.unassigned,
                    items: [],
                    totalAmount: 0,
                    completedCount: 0
                });
            }

            const pData = group.projects.get(projectId)!;
            pData.items.push({
                title: m.title,
                status: m.status,
                amount: m.paymentAmount || 0,
                hasPayment: m.hasPayment
            });
            if (m.hasPayment) pData.totalAmount += (m.paymentAmount || 0);
            if (m.status === MilestoneStatus.Completed) pData.completedCount += 1;
        });

        let sortedGroups = Array.from(groups.values());

        if (sortKey === 'date') {
            sortedGroups.sort((a, b) => sortOrder === 'desc' ? b.sortKey - a.sortKey : a.sortKey - b.sortKey);
        } else {
            sortedGroups.sort((a, b) => b.sortKey - a.sortKey);
        }

        return sortedGroups.map(group => {
            let projectsInGroup = Array.from(group.projects.values());

            if (sortKey !== 'date') {
                projectsInGroup.sort((a, b) => {
                    let result = 0;
                    if (sortKey === 'name') result = a.projectName.localeCompare(b.projectName);
                    if (sortKey === 'amount') result = b.totalAmount - a.totalAmount;
                    if (sortKey === 'progress') result = (b.completedCount / (b.items.length || 1)) - (a.completedCount / (a.items.length || 1));
                    return sortOrder === 'desc' ? result : -result;
                });
            }

            return {
                monthYear: group.monthYear,
                projects: projectsInGroup,
                totalAmount: projectsInGroup.reduce((sum, p) => sum + p.totalAmount, 0)
            };
        });
    }, [milestones, projects, language, t.unknownProject, t.unassigned, filterProjectId, filterManagerId, filterStatus, filterMonthYear, sortKey, sortOrder]);

    // --- Graph Calculation logic ---
    const graphData = useMemo(() => {
        return [...aggregatedData].sort((a, b) => {
            const getSortVal = (my: string) => {
                const [m, y] = my.split(' ');
                const monthsEn = { January: 0, February: 1, March: 2, April: 3, May: 4, June: 5, July: 6, August: 7, September: 8, October: 9, November: 10, December: 11 };
                const monthsAr = { "يناير": 0, "فبراير": 1, "مارس": 2, "أبريل": 3, "مايو": 4, "يونيو": 5, "يوليو": 6, "أغسطس": 7, "سبتمبر": 8, "أكتوبر": 9, "نوفمبر": 10, "ديسمبر": 11 };
                const monthNum = (language === 'ar' ? (monthsAr as any)[m] : (monthsEn as any)[m]) || 0;
                return parseInt(y) * 100 + monthNum;
            };
            return getSortVal(a.monthYear) - getSortVal(b.monthYear);
        });
    }, [aggregatedData, language]);

    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 50000);
    const yAxisMarks = useMemo(() => {
        // Find a nice rounded max for the scale (e.g. increments of 50K)
        const roundedMax = Math.ceil(maxAmount / 50000) * 50000;
        return [roundedMax, roundedMax * 0.66, roundedMax * 0.33, 0];
    }, [maxAmount]);

    const formatShortCurrency = (val: number) => {
        if (val >= 1000) return `$${(val / 1000).toFixed(2)}K`;
        return `$${val.toFixed(0)}`;
    };

    const getShortMonthYear = (my: string) => {
        const [m, y] = my.split(' ');
        const monthsEn = { January: '1', February: '2', March: '3', April: '4', May: '5', June: '6', July: '7', August: '8', September: '9', October: '10', November: '11', December: '12' };
        const monthsAr = { "يناير": '1', "فبراير": '2', "مارس": '3', "أبريل": '4', "مايو": '5', "يونيو": '6', "يوليو": '7', "أغسطس": '8', "سبتمبر": '9', "أكتوبر": '10', "نوفمبر": '11', "ديسمبر": '12' };
        const monthNum = (language === 'ar' ? (monthsAr as any)[m] : (monthsEn as any)[m]) || '?';
        return `${monthNum}/${y}`;
    };

    const toggleGroup = (key: string) => {
        setExpandedGroups(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const expandAll = () => {
        const all: Record<string, boolean> = {};
        aggregatedData.forEach(g => all[g.monthYear] = true);
        setExpandedGroups(all);
    };

    const collapseAll = () => {
        setExpandedGroups({});
    };

    const inputClasses = "p-1.5 bg-slate-100 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-[11px] w-full";

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="none" showPadding={true}>
            {/* 1. Filters & Sort Toolbar */}
            <div className="bg-slate-50 dark:bg-slate-900/20 p-2 rounded-xl border border-slate-100 dark:border-slate-800 mb-3">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-1.5 mb-2">
                    <div className="space-y-0.5">
                        <label className="text-[9px] font-bold text-slate-400 uppercase">{t.project}</label>
                        <SearchableSelect 
                            options={projectOptions} 
                            value={filterProjectId} 
                            onChange={setFilterProjectId} 
                            placeholder={t.allProjects} 
                            language={language}
                        />
                    </div>
                    <div className="space-y-0.5">
                        <label className="text-[9px] font-bold text-slate-400 uppercase">{t.manager}</label>
                        <SearchableSelect 
                            options={managerOptions} 
                            value={filterManagerId} 
                            onChange={setFilterManagerId} 
                            placeholder={t.allManagers} 
                            searchPlaceholder={t.searchManagers}
                            language={language}
                        />
                    </div>
                    <div className="space-y-0.5">
                        <label className="text-[9px] font-bold text-slate-400 uppercase">{t.status}</label>
                        <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className={inputClasses}>
                            {statusOptions.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                        </select>
                    </div>
                    <div className="space-y-0.5">
                        <label className="text-[9px] font-bold text-slate-400 uppercase">{t.monthYear}</label>
                        <SearchableSelect 
                            options={monthYearOptions} 
                            value={filterMonthYear} 
                            onChange={setFilterMonthYear} 
                            placeholder={t.allMonths} 
                            searchPlaceholder={t.searchMonths}
                            language={language}
                        />
                    </div>
                </div>

                <div className="flex flex-wrap items-center justify-between gap-2 pt-1.5 border-t border-slate-200 dark:border-slate-800">
                    <div className="flex items-center gap-3">
                        <div className="flex items-center gap-1.5">
                            <span className="text-[9px] font-bold text-slate-400 uppercase">{t.sortBy}:</span>
                            <div className="flex bg-slate-200 dark:bg-slate-800 p-0.5 rounded-lg">
                                {sortOptions.map(opt => (
                                    <button 
                                        key={opt.value}
                                        onClick={() => setSortKey(opt.value as any)}
                                        className={`px-2 py-0.5 text-[9px] font-bold rounded-md transition-all ${sortKey === opt.value ? 'bg-white dark:bg-slate-700 text-violet-600 dark:text-violet-400 shadow-sm' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                                    >
                                        {opt.label}
                                    </button>
                                ))}
                            </div>
                        </div>
                        <button 
                            onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
                            className="p-1 bg-slate-200 dark:bg-slate-800 rounded text-slate-600 dark:text-slate-400 hover:text-violet-600 transition-colors"
                            title={sortOrder === 'asc' ? t.ascending : t.descending}
                        >
                            {sortOrder === 'asc' ? (
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4h13M3 8h9m-9 4h6m4 0l4-4m0 0l4 4m-4-4v12" /></svg>
                            ) : (
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4h13M3 8h9m-9 4h9m5-1v12m0 0l-4-4m4 4l4-4" /></svg>
                            )}
                        </button>
                    </div>

                    <div className="flex items-center gap-2">
                        <button onClick={expandAll} className="text-[9px] font-bold text-violet-600 hover:underline uppercase">{t.expandAll}</button>
                        <span className="text-slate-300 text-[9px]">|</span>
                        <button onClick={collapseAll} className="text-[9px] font-bold text-slate-500 hover:underline uppercase">{t.collapseAll}</button>
                    </div>
                </div>
            </div>

            {/* 2. CUSTOM BAR CHART (Mirroring User Image exactly) */}
            <div className="mb-8 px-4 py-8 bg-white dark:bg-slate-900/40 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm">
                <div className="flex h-56 relative group">
                    {/* Y-Axis Labels */}
                    <div className="w-14 flex flex-col justify-between text-[11px] font-bold text-slate-400 pb-8 pr-2 text-right">
                        {yAxisMarks.map((val, idx) => (
                            <span key={idx}>${(val / 1000).toFixed(0)}K</span>
                        ))}
                    </div>

                    {/* Chart Container */}
                    <div className="flex-1 overflow-x-auto no-scrollbar flex items-end gap-3 pb-8 relative border-l border-slate-100 dark:border-slate-800/50">
                        {/* Horizontal Grid Lines */}
                        <div className="absolute inset-0 flex flex-col justify-between pointer-events-none pb-8">
                             {[1, 2, 3, 4].map(i => (
                                <div key={i} className="w-full border-t border-slate-100 dark:border-slate-800 border-dashed"></div>
                             ))}
                        </div>

                        {/* Bars */}
                        {graphData.length > 0 ? graphData.map((d, i) => (
                            <div key={i} className="flex-1 min-w-[65px] flex flex-col items-center justify-end h-full group/bar relative">
                                {/* Value Text Top - BOLD and DARK as per image */}
                                <span className="absolute -top-7 text-[11px] font-black text-slate-700 dark:text-slate-200 transition-transform group-hover/bar:scale-110">
                                    {d.totalAmount > 0 ? formatShortCurrency(d.totalAmount) : ''}
                                </span>

                                {/* The Bar - ROSE RED solid */}
                                <div 
                                    style={{ height: `${Math.max(4, (d.totalAmount / (yAxisMarks[0] || 1)) * 100)}%` }}
                                    className="w-full max-w-[48px] bg-[#d64545] rounded-t-sm shadow-sm transition-all duration-500 hover:brightness-110 cursor-pointer"
                                    title={`${d.monthYear}: ${formatShortCurrency(d.totalAmount)}`}
                                ></div>

                                {/* Label Bottom */}
                                <span className="absolute top-full mt-2 text-[11px] font-bold text-slate-500 whitespace-nowrap">
                                    {getShortMonthYear(d.monthYear)}
                                </span>
                            </div>
                        )) : (
                            <div className="absolute inset-0 flex items-center justify-center text-slate-300 text-xs italic">{t.noData}</div>
                        )}
                    </div>
                </div>
            </div>

            {/* 3. Aggregated List View (Max Height 350px) */}
            <div className="space-y-1.5 pb-2 overflow-y-auto custom-scrollbar" style={{ maxHeight: '350px' }}>
                {aggregatedData.length > 0 ? aggregatedData.map((group, idx) => {
                    const isExpanded = !!expandedGroups[group.monthYear];
                    return (
                        <div key={idx} className="bg-slate-50/50 dark:bg-slate-900/10 rounded-xl border border-slate-100 dark:border-slate-800 overflow-hidden">
                            <button 
                                onClick={() => toggleGroup(group.monthYear)}
                                className="w-full flex items-center justify-between p-2 hover:bg-slate-100 dark:hover:bg-slate-800/40 transition-colors"
                            >
                                <div className="flex items-center gap-2">
                                    <div className={`p-0.5 rounded transition-colors ${isExpanded ? 'bg-violet-600 text-white' : 'bg-slate-200 dark:bg-slate-800 text-slate-500'}`}>
                                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                                    </div>
                                    <h3 className="text-xs font-black text-slate-800 dark:text-white flex items-center gap-1.5">
                                        {group.monthYear}
                                        <span className="text-[8px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-500 px-1.5 py-0.2 rounded-full">
                                            {group.projects.length} {t.projectsCount}
                                        </span>
                                    </h3>
                                </div>
                                {!isExpanded && (
                                    <div className="flex gap-4 text-[9px] font-bold text-slate-400 uppercase">
                                        <span>{t.total}: {group.totalAmount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}</span>
                                    </div>
                                )}
                            </button>

                            {isExpanded && (
                                <div className="p-2 pt-0 space-y-1.5 animate-in fade-in slide-in-from-top-1 duration-200">
                                    {group.projects.map((p, pIdx) => (
                                        <div key={pIdx} className="bg-white dark:bg-slate-800/60 rounded-lg border border-slate-100 dark:border-slate-700 p-2 shadow-sm">
                                            <div className="flex justify-between items-center mb-1.5">
                                                <div className="min-w-0">
                                                    <h4 className="font-bold text-slate-800 dark:text-white text-[11px] flex items-center flex-wrap gap-1">
                                                        <span>{p.projectName}</span>
                                                        <span className="text-[8px] font-bold text-violet-600 dark:text-violet-400 bg-violet-100 dark:bg-violet-900/40 px-1 py-0.1 rounded">
                                                            {p.managerName}
                                                        </span>
                                                    </h4>
                                                    <p className="text-[8px] font-mono text-slate-400 mt-0.2">{p.projectCode}</p>
                                                </div>
                                                <div className="text-right shrink-0 flex items-center gap-3">
                                                    <div>
                                                        <p className="text-[7px] text-slate-400 uppercase font-bold">{t.completed}</p>
                                                        <p className="text-[9px] font-bold text-violet-600 dark:text-violet-400">{Math.round((p.completedCount / p.items.length) * 100)}%</p>
                                                    </div>
                                                    {p.totalAmount > 0 && (
                                                        <div>
