const ProjectsWeightWidget: React.FC<AnalyticsDashboardProps> = ({ projects, language }) => {
    const t = translations[language];
    const [searchTerm, setSearchTerm] = useState('');
    const [minScore, setMinScore] = useState<string>('');
    const [maxScore, setMaxScore] = useState<string>('');

    const projectsWithScores = useMemo(() => {
        return projects.map(p => {
            const score = (
                (p.revenueImpact || 1) + 
                (p.strategicValue || 1) + 
                (p.deliveryRisk || 1) + 
                (p.customerPressure || 1)
            ) - (p.resourceLoad || 1);
            return { name: p.name, score, code: p.projectCode };
        }).filter(p => {
            const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                                 p.code.toLowerCase().includes(searchTerm.toLowerCase());

            const min = minScore === '' ? -Infinity : Number(minScore);
            const max = maxScore === '' ? Infinity : Number(maxScore);
            const matchesScore = p.score >= min && p.score <= max;

            return matchesSearch && matchesScore;
        }).sort((a, b) => b.score - a.score);
    }, [projects, searchTerm, minScore, maxScore]);

    const maxPossibleScore = 19;

    const inputClasses = "p-1.5 bg-slate-100 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-[11px]";

    return (
        <WidgetWrapper title={t.projectsWeight} maxHeight="400px">
            <div className="flex flex-col gap-2 mb-4 px-1">
                <input 
                    type="text" 
                    placeholder={t.searchProjects} 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className={inputClasses + " w-full"}
                />
                <div className="flex items-center gap-2">
                    <span className="text-[10px] text-slate-400 font-bold uppercase shrink-0">{t.weightRange}:</span>
                    <input 
                        type="number" 
                        placeholder={t.from} 
                        value={minScore}
                        onChange={(e) => setMinScore(e.target.value)}
                        className={inputClasses + " w-full"}
                    />
                    <input 
                        type="number" 
                        placeholder={t.to} 
                        value={maxScore}
                        onChange={(e) => setMaxScore(e.target.value)}
                        className={inputClasses + " w-full"}
                    />
                </div>
            </div>
            <div className="space-y-4 pt-2">
                {projectsWithScores.length > 0 ? projectsWithScores.map((p, idx) => (
                    <div key={idx} className="group">
                        <div className="flex justify-between items-center mb-1">
                            <div className="flex flex-col">
                                <span className="text-sm font-bold text-slate-700 dark:text-slate-200 truncate max-w-[200px]">{p.name}</span>
                                <span className="text-[10px] font-mono text-slate-400">{p.code}</span>
                            </div>
                            <span className="text-sm font-black text-violet-600 dark:text-violet-400 bg-violet-50 dark:bg-violet-900/30 px-2 py-0.5 rounded-md">{p.score}</span>
                        </div>
                        <div className="w-full bg-slate-100 dark:bg-slate-700 rounded-full h-2 overflow-hidden">
                            <div 
                                className="bg-gradient-to-r from-violet-500 to-indigo-500 h-full rounded-full transition-all duration-1000 ease-out group-hover:brightness-110" 
                                style={{ width: `${Math.max(5, (p.score / maxPossibleScore) * 100)}%` }}
                            ></div>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm text-center py-4">{t.noProjects}</p>}
            </div>
        </WidgetWrapper>
    );
};

const ProjectStatusChartWidget: React.FC<AnalyticsDashboardProps> = ({ projects, language }) => {
    const t = translations[language];
    const statusCounts = useMemo(() => {
        const counts = new Map<string, { count: number, color: string }>();
        const colors = ['bg-green-500', 'bg-blue-500', 'bg-yellow-500', 'bg-red-500', 'bg-indigo-500', 'bg-pink-500'];
        let colorIndex = 0;
        projects.forEach(p => {
            const statusName = p.status?.name || t.unknownStatus;
            if (!counts.has(statusName)) {
                counts.set(statusName, { count: 0, color: colors[colorIndex % colors.length] });
                colorIndex++;
            }
            counts.get(statusName)!.count++;
        });
        return Array.from(counts.entries());
    }, [projects, t.unknownStatus]);

    const maxCount = Math.max(...statusCounts.map(([, {count}]) => count), 1);

    return (
        <WidgetWrapper title={t.projectStatuses} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {statusCounts.length > 0 ? statusCounts.map(([status, {count, color}]) => (
                    <div key={status} className="flex items-center gap-4">
                        <span className="w-1/3 text-sm text-gray-600 dark:text-gray-300 truncate">{status}</span>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4">
                                <div className={`${color} h-4 rounded-full transition-all duration-500`} style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm">{count}</span>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm">{t.noProjects}</p>}
            </div>
        </WidgetWrapper>
    );
};

interface TeamWorkloadChartWidgetProps extends AnalyticsDashboardProps {
    onTeamClick: (team: Lookup, teamProjects: Project[]) => void;
}

const TeamWorkloadChartWidget: React.FC<TeamWorkloadChartWidgetProps> = ({ projects, teams, language, onTeamClick }) => {
    const t = translations[language];
    const teamProjectCounts = useMemo(() => {
        const counts = new Map<string, { projects: Project[] }>();
        teams.forEach(t => counts.set(t.id, { projects: [] }));
        projects.forEach(p => {
            if (p.teamId && counts.has(p.teamId)) {
                counts.get(p.teamId)!.projects.push(p);
            }
        });
        return Array.from(counts.entries())
            .map(([teamId, data]) => ({ team: teams.find(t => t.id === teamId), count: data.projects.length, teamProjects: data.projects }))
            .filter(item => item.team)
            .sort((a,b) => b.count - a.count);
    }, [projects, teams]);

    const maxCount = Math.max(...teamProjectCounts.map(({ count }) => count), 1);

    return (
         <WidgetWrapper title={t.teamWorkload} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {teamProjectCounts.length > 0 ? teamProjectCounts.map(({ team, count, teamProjects }) => (
                    <div 
                        key={team!.id} 
                        className="flex items-center gap-4 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/30 p-2 rounded-xl transition-all group"
                        onClick={() => onTeamClick(team!, teamProjects)}
                    >
                        <div className="w-1/3 flex items-center gap-2">
                           <span className="text-sm text-gray-600 dark:text-gray-300 truncate group-hover:text-violet-600 dark:group-hover:text-violet-400 font-medium">{team!.name}</span>
                        </div>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 overflow-hidden">
                                <div className="bg-gradient-to-r from-violet-500 to-indigo-500 h-4 rounded-full transition-all duration-500 group-hover:brightness-110" style={{ width: `${(count / maxCount) * 100}%` }}></div>
