interface AnalyticsDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    customers: Lookup[];
    projectManagers: User[];
    language: Language;
    currentUser?: User;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = (props) => {
    const { language } = props;
    const t = translations[language];

    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [layout, setLayout] = useState<string[]>([]);
    const [viewingProject, setViewingProject] = useState<Project | null>(null);
    const [viewingTeamProjects, setViewingTeamProjects] = useState<{ team: Lookup; projects: Project[] } | null>(null);

    useEffect(() => {
        try {
            const savedLayout = localStorage.getItem('dashboardLayout');
            if (savedLayout) {
                const parsedLayout = JSON.parse(savedLayout);
                const validWidgetIds = new Set(WIDGETS_CONFIG.map(w => w.id));
                const filteredLayout = parsedLayout.filter((id: string) => validWidgetIds.has(id));
                setLayout(filteredLayout);
            } else {
                setLayout(WIDGETS_CONFIG.filter(w => w.default).map(w => w.id));
            }
        } catch (error) {
            console.error("Failed to load dashboard layout", error);
            setLayout(WIDGETS_CONFIG.filter(w => w.default).map(w => w.id));
        }
    }, []);

    const handleSaveLayout = (newLayout: string[]) => {
        setLayout(newLayout);
        localStorage.setItem('dashboardLayout', JSON.stringify(newLayout));
        setIsCustomizeModalOpen(false);
    };

    const renderedWidgets = useMemo(() => {
        return layout.map(widgetId => {
            const widget = WIDGETS_CONFIG.find(w => w.id === widgetId);
            if (!widget) return null;
            const Component = widget.component as React.FC<any>; // Cast to allow custom callbacks
            const colSpan = widget.colSpan;
            const colSpanClass = `lg:col-span-${colSpan}`;

            return (
                <div key={widget.id} className={colSpanClass}>
                  <Component 
                    {...props} 
                    onViewProjectDetails={(p: any) => setViewingProject(p)} 
                    onTeamClick={(team: Lookup, teamProjects: Project[]) => setViewingTeamProjects({ team, projects: teamProjects })} 
                  />
                </div>
            );
        });
    }, [layout, props]);

    return (
        <div className="space-y-8">
             {isCustomizeModalOpen && (
                <CustomizeDashboardModal
                    isOpen={isCustomizeModalOpen}
                    onClose={() => setIsCustomizeModalOpen(false)}
                    currentLayout={layout}
                    onSaveLayout={handleSaveLayout}
                    language={language}
                />
            )}
            {viewingProject && (
                <ProjectDetailModal
                    projectWithMilestones={{
                        ...viewingProject,
                        milestones: props.milestones.filter(m => m.projectId === viewingProject.id)
                    }}
                    onClose={() => setViewingProject(null)}
                    language={language}
                />
            )}
            {viewingTeamProjects && (
                <TeamProjectsModal
                    team={viewingTeamProjects.team}
                    projects={viewingTeamProjects.projects}
                    onClose={() => setViewingTeamProjects(null)}
                    language={language}
                    onViewProject={(p) => {
                        setViewingTeamProjects(null);
                        setViewingProject(p);
                    }}
                />
            )}
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{t.dashboard}</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">{t.overview}</p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-slate-200 dark:bg-slate-700/50 hover:bg-slate-300 dark:hover:bg-slate-600/50 text-slate-800 dark:text-white font-bold py-2 px-4 rounded-full flex items-center gap-2 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 000 3.464V16a1 1 0 102 0V8.732a2 2 0 00-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" /></svg>
                    <span>{t.customize}</span>
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                {renderedWidgets}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Language } from '../types';

interface SearchableSelectProps {
    options: { value: string; label: string; }[];
    value: string | string[];
    onChange: (value: any) => void;
    placeholder: string;
    searchPlaceholder?: string;
    language: Language;
    isMulti?: boolean;
}

const SearchableSelect: React.FC<SearchableSelectProps> = ({ options, value, onChange, placeholder, searchPlaceholder, language, isMulti = false }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const wrapperRef = useRef<HTMLDivElement>(null);

    const translations = {
        ar: { noResults: "لا توجد نتائج", selected: "مختارة" },
        en: { noResults: "No results found", selected: "selected" }
    };
    const t = translations[language];

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const selectedOptions = useMemo(() => {
        if (isMulti && Array.isArray(value)) {
            return options.filter(opt => value.includes(opt.value));
        }
        return options.find(opt => opt.value === value) ? [options.find(opt => opt.value === value)!] : [];
    }, [options, value, isMulti]);

    const filteredOptions = useMemo(() => {
        const baseOptions = isMulti ? options.filter(o => o.value !== 'all') : options;
        if (!searchTerm) return baseOptions;
        return baseOptions.filter(opt =>
            opt.label.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [options, searchTerm, isMulti]);

    const handleSelect = (optionValue: string) => {
        if (isMulti) {
            const currentValue = Array.isArray(value) ? value : [];
            let newValue;
            if (currentValue.includes(optionValue)) {
                newValue = currentValue.filter(v => v !== optionValue);
            } else {
                newValue = [...currentValue, optionValue];
            }
            onChange(newValue);
        } else {
            onChange(optionValue);
            setIsOpen(false);
            setSearchTerm('');
        }
    };

    const toggleOpen = () => {
        setIsOpen(prev => !prev);
        if (isOpen) {
            setSearchTerm('');
        }
    };

    const displayLabel = useMemo(() => {
        if (isMulti && Array.isArray(value)) {
            if (value.length === 0) return placeholder;
            if (value.length === 1) return selectedOptions[0]?.label;
            return `${value.length} ${t.selected}`;
        }
        return selectedOptions[0]?.label || placeholder;
    }, [selectedOptions, value, isMulti, placeholder, t.selected]);

    const buttonClasses = "w-full p-2 bg-slate-200 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-sm";

    return (
        <div className="relative w-full" ref={wrapperRef}>
            <button
                type="button"
                onClick={toggleOpen}
                className={`${buttonClasses} flex justify-between items-center text-left rtl:text-right`}
            >
                <span className="truncate">{displayLabel}</span>
                <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
            </button>

            {isOpen && (
                <div className="absolute top-full mt-1 w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md shadow-lg z-50">
                    <div className="p-2 border-b border-slate-100 dark:border-slate-700">
                        <input
                            type="text"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            placeholder={searchPlaceholder || placeholder}
                            autoFocus
                            className="w-full p-2 bg-slate-100 dark:bg-slate-900/50 rounded-md border border-slate-300 dark:border-slate-700 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-sm"
                        />
                    </div>
                    <ul className="max-h-60 overflow-y-auto p-1 custom-scrollbar">
                        {filteredOptions.length > 0 ? (
                            filteredOptions.map(option => {
                                const isSelected = isMulti 
                                    ? (Array.isArray(value) && value.includes(option.value))
                                    : value === option.value;

                                return (
                                    <li key={option.value}>
                                        <button
                                            type="button"
                                            onClick={() => handleSelect(option.value)}
                                            className={`w-full text-left rtl:text-right p-2 text-sm rounded-md transition-colors flex items-center gap-2 ${isSelected ? 'bg-violet-50 dark:bg-violet-900/30 text-violet-600 dark:text-violet-300 font-bold' : 'text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                                        >
                                            {isMulti && (
                                                <div className={`w-4 h-4 rounded border flex items-center justify-center flex-shrink-0 transition-colors ${isSelected ? 'bg-violet-600 border-violet-600 text-white' : 'bg-transparent border-slate-300 dark:border-slate-600'}`}>
                                                    {isSelected && <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" /></svg>}
                                                </div>
                                            )}
                                            <span className="truncate">{option.label}</span>
                                        </button>
                                    </li>
                                );
                            })
                        ) : (
                            <li className="p-4 text-sm text-center text-slate-500 dark:text-slate-400">
                                {t.noResults}
                            </li>
                        )}
                    </ul>
                </div>
            )}
        </div>
    );
};

export default SearchableSelect;

