                <button onClick={onClose} className="text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-white">&times;</button>
            </div>

            {error && <div className="p-3 mb-4 text-sm text-red-800 dark:text-red-200 bg-red-100 dark:bg-red-500/20 rounded-lg" role="alert">{error}</div>}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Master & Form Section */}
                <div className="lg:col-span-5 space-y-6">
                    {/* Master: Project Selection */}
                    <div className="bg-slate-50 dark:bg-slate-800/20 p-4 rounded-xl border border-slate-100 dark:border-slate-800">
                        <label className="block text-xs font-black text-violet-600 dark:text-violet-400 uppercase tracking-widest mb-2">{t.masterSection}</label>
                        <SearchableSelect
                            options={projectOptions}
                            value={selectedProjectId}
                            onChange={handleProjectChange}
                            placeholder={t.selectHere}
                            searchPlaceholder={t.searchProject}
                            language={language}
                        />
                    </div>

