const ExecutionPerformanceChartWidget: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, projectManagers, language }) => {
    const t = translations[language];

    const [filterProjectId, setFilterProjectId] = useState('all');
    const [filterManagerId, setFilterManagerId] = useState('all');
    const [filterStatus, setFilterStatus] = useState('all');
    // Set default to current Month Year in an array for multi-select
    const [filterMonthYear, setFilterMonthYear] = useState<string[]>(() => [getCurrentMonthYearLabel(language)]);

    // Sync filter label if language changes and it was at default
    const prevLanguageRef = useRef(language);
    useEffect(() => {
        if (prevLanguageRef.current !== language) {
            const oldDefault = getCurrentMonthYearLabel(prevLanguageRef.current);
            if (filterMonthYear.length === 1 && filterMonthYear[0] === oldDefault) {
                setFilterMonthYear([getCurrentMonthYearLabel(language)]);
            }
            prevLanguageRef.current = language;
        }
    }, [language, filterMonthYear]);

    const projectOptions = useMemo(() => [
        { value: 'all', label: t.allProjects },
        ...projects.map(p => ({ value: p.id, label: p.name }))
    ], [projects, t.allProjects]);

    const managerOptions = useMemo(() => [
        { value: 'all', label: t.allManagers },
        ...projectManagers.map(m => ({ value: m.id, label: m.name }))
    ], [projectManagers, t.allManagers]);

    const statusOptions = useMemo(() => [
        { value: 'all', label: t.allStatuses },
        ...Object.values(MilestoneStatus).map(s => ({ value: s, label: t[s] || s }))
    ], [t]);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!unique.has(label)) {
                    unique.set(label, { label, sortKey });
                }
            }
        });

        return Array.from(unique.values())
            .sort((a, b) => a.sortKey - b.sortKey)
            .map(v => ({ value: v.label, label: v.label }));
    }, [milestones, language]);

    // Calculate current filtered counts and data
    const { graphData, filteredStats } = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();
        let pending = 0;
        let sent = 0;
        let paid = 0;

        milestones.forEach(m => {
            if (!m.dueDate) return;

            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();

            const project = projects.find(p => p.id === m.projectId);

            // Filter Application
            if (filterMonthYear.length > 0 && !filterMonthYear.includes(labelKey)) return;
            if (filterProjectId !== 'all' && m.projectId !== filterProjectId) return;
            if (filterStatus !== 'all' && m.status !== filterStatus) return;
            if (filterManagerId !== 'all' && project?.projectManagerId !== filterManagerId) return;

            // Counts for the specific cards linked to the filters
            if (m.status === MilestoneStatus.Pending) pending++;
            else if (m.status === MilestoneStatus.Sent) sent++;
            else if (m.status === MilestoneStatus.Paid) paid++;

            // Accumulate for graph if it has payment
            if (m.hasPayment) {
                if (!groups.has(labelKey)) {
                    groups.set(labelKey, { totalAmount: 0, sortKey });
                }
                groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
            }
        });

        const sortedGraph = Array.from(groups.entries())
            .map(([monthYear, data]) => ({ monthYear, ...data }))
            .sort((a, b) => a.sortKey - b.sortKey);

        return { 
            graphData: sortedGraph, 
            filteredStats: { pending, sent, paid } 
        };
    }, [milestones, projects, language, filterProjectId, filterManagerId, filterStatus, filterMonthYear]);

    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 50000);
    const yAxisMax = Math.ceil(maxAmount / 50000) * 50000;
    const yAxisMarks = [yAxisMax, yAxisMax * 0.66, yAxisMax * 0.33, 0];

    const formatLabelValue = (val: number) => {
        return `$${(val / 1000).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}K`;
    };

    const getShortMonthYear = (my: string) => {
        const [m, y] = my.split(' ');
        const monthsEn = { January: '1', February: '2', March: '3', April: '4', May: '5', June: '6', July: '7', August: '8', September: '9', October: '10', November: '11', December: '12' };
        const monthsAr = { "يناير": '1', "فبراير": '2', "مارس": '3', "أبريل": '4', "مايو": '5', "يونيو": '6', "يوليو": '7', "أغسطس": '8', "سبتمبر": '9', "أكتوبر": '10', "نوفمبر": '11', "ديسمبر": '12' };
        const monthNum = (language === 'ar' ? (monthsAr as any)[m] : (monthsEn as any)[m]) || '?';
        return `${monthNum}/${y}`;
    };

    const inputClasses = "p-1.5 bg-slate-100 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-[11px] w-full h-[34px]";

    return (
        <WidgetWrapper title={t.executionChartTitle} maxHeight="none">
            {/* Filters Row */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">{t.project}</label>
                    <SearchableSelect options={projectOptions} value={filterProjectId} onChange={setFilterProjectId} placeholder={t.allProjects} language={language} />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">{t.manager}</label>
                    <SearchableSelect options={managerOptions} value={filterManagerId} onChange={setFilterManagerId} placeholder={t.allManagers} language={language} />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">{t.status}</label>
                    <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className={inputClasses}>
                        {statusOptions.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                    </select>
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">{t.monthYear}</label>
                    <SearchableSelect isMulti options={monthYearOptions} value={filterMonthYear} onChange={setFilterMonthYear} placeholder={t.allMonths} searchPlaceholder={t.searchMonths} language={language} />
                </div>
            </div>

            {/* Filtered Mini Stats Cards - Reacts to filters above */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">
                <div className="bg-yellow-50 dark:bg-yellow-900/10 p-4 rounded-xl border border-yellow-100 dark:border-yellow-800/30 flex items-center justify-between shadow-sm">
                    <div>
                        <p className="text-[10px] font-black text-yellow-500 dark:text-yellow-500 uppercase tracking-widest mb-1">{t.totalPending}</p>
                        <p className="text-2xl font-black text-yellow-700 dark:text-yellow-300">{filteredStats.pending}</p>
                    </div>
                    <div className="p-2.5 bg-yellow-100 dark:bg-yellow-900/40 rounded-xl text-yellow-600 dark:text-yellow-400">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd" /></svg>
                    </div>
                </div>
                <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-xl border border-blue-100 dark:border-blue-800/30 flex items-center justify-between shadow-sm">
                    <div>
                        <p className="text-[10px] font-black text-blue-400 dark:text-blue-500 uppercase tracking-widest mb-1">{t.totalSent}</p>
                        <p className="text-2xl font-black text-blue-700 dark:text-blue-300">{filteredStats.sent}</p>
                    </div>
                    <div className="p-2.5 bg-blue-100 dark:bg-blue-900/40 rounded-xl text-blue-600 dark:text-blue-400">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 110 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" /></svg>
                    </div>
                </div>
                <div className="bg-green-50 dark:bg-green-900/10 p-4 rounded-xl border border-green-100 dark:border-green-800/30 flex items-center justify-between shadow-sm">
                    <div>
                        <p className="text-[10px] font-black text-green-400 dark:text-green-500 uppercase tracking-widest mb-1">{t.totalPaid}</p>
                        <p className="text-2xl font-black text-green-700 dark:text-green-300">{filteredStats.paid}</p>
                    </div>
                    <div className="p-2.5 bg-green-100 dark:bg-green-900/40 rounded-xl text-green-600 dark:text-green-400">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                    </div>
                </div>
            </div>

            {/* CHART AREA */}
            <div className="relative mt-4 mb-8 px-2 overflow-visible">
                <div className="flex h-64 relative overflow-visible">
                    {/* Y-Axis scale */}
                    <div className="w-14 flex flex-col justify-between text-[11px] font-bold text-slate-400 pb-8 pr-3 text-right">
                        {yAxisMarks.map((val, idx) => (
                            <span key={idx}>${(val / 1000).toFixed(0)}K</span>
                        ))}
                    </div>

                    {/* Bars Container */}
                    <div className="flex-1 flex items-end gap-3 pb-8 relative border-l border-slate-200 dark:border-slate-800/50 overflow-visible">
                        {/* Horizontal Grid Lines */}
                        <div className="absolute inset-0 flex flex-col justify-between pointer-events-none pb-8">
                             {[0, 1, 2, 3].map(i => (
                                <div key={i} className="w-full border-t border-slate-100 dark:border-slate-800 border-dashed"></div>
                             ))}
                        </div>

                        {graphData.map((d, i) => (
                            <div key={i} className="flex-1 min-w-[75px] flex flex-col items-center justify-end h-full group relative overflow-visible">

                                {/* DYNAMIC BAR WRAPPER */}
                                <div 
                                    style={{ height: `${Math.max(4, (d.totalAmount / yAxisMax) * 100)}%` }}
                                    className="w-full max-w-[54px] relative group/bar"
                                >
                                    {/* VALUE LABEL */}
                                    <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-1 z-20 text-[12px] font-black text-slate-900 dark:text-slate-100 whitespace-nowrap transition-transform group-hover/bar:scale-110">
                                        {d.totalAmount > 0 ? formatLabelValue(d.totalAmount) : ''}
                                    </span>

                                    {/* THE BAR */}
                                    <div 
                                        className="w-full h-full bg-[#d64545] rounded-t-[2px] shadow-sm transition-all duration-500 hover:brightness-110 cursor-pointer"
                                        title={`${d.monthYear}: ${formatLabelValue(d.totalAmount)}`}
                                    />
                                </div>

                                {/* DATE LABEL */}
                                <span className="absolute top-full mt-2 text-[11px] font-bold text-slate-500 whitespace-nowrap">
                                    {getShortMonthYear(d.monthYear)}
                                </span>
                            </div>
                        ))}

                        {graphData.length === 0 && (
                            <div className="absolute inset-0 flex items-center justify-center text-slate-400 text-xs italic">{t.noData}</div>
                        )}
                    </div>
                </div>
            </div>
        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, projectManagers, language }) => {
    const t = translations[language];

    // Filter states
    const [filterProjectId, setFilterProjectId] = useState('all');
    const [filterManagerId, setFilterManagerId] = useState('all');
    const [filterStatus, setFilterStatus] = useState('all');
    // Default to current month/year label in an array
    const [filterMonthYear, setFilterMonthYear] = useState<string[]>(() => [getCurrentMonthYearLabel(language)]);

    // Sync filter label if language changes and it was at default
    const prevLanguageRef = useRef(language);
    useEffect(() => {
        if (prevLanguageRef.current !== language) {
            const oldDefault = getCurrentMonthYearLabel(prevLanguageRef.current);
            if (filterMonthYear.length === 1 && filterMonthYear[0] === oldDefault) {
                setFilterMonthYear([getCurrentMonthYearLabel(language)]);
            }
            prevLanguageRef.current = language;
        }
    }, [language, filterMonthYear]);

    // Sort states
    const [sortKey, setSortKey] = useState<'date' | 'name' | 'amount' | 'progress' | 'manager'>('date');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

    // Collapsible state
    const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});

    const projectOptions = useMemo(() => [
        { value: 'all', label: t.allProjects },
        ...projects.map(p => ({ value: p.id, label: p.name }))
    ], [projects, t.allProjects]);

    const managerOptions = useMemo(() => [
        { value: 'all', label: t.allManagers },
        ...projectManagers.map(m => ({ value: m.id, label: m.name }))
    ], [projectManagers, t.allManagers]);

    const statusOptions = useMemo(() => [
        { value: 'all', label: t.allStatuses },
        ...Object.values(MilestoneStatus).map(s => ({ value: s, label: t[s] || s }))
    ], [t]);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!unique.has(label)) {
                    unique.set(label, { label, sortKey });
                }
            }
        });

        return Array.from(unique.values())
            .sort((a, b) => a.sortKey - b.sortKey)
            .map(v => ({ value: v.label, label: v.label }));
    }, [milestones, language]);

    const sortOptions = [
        { value: 'date', label: t.sortByDate },
        { value: 'name', label: t.sortByName },
        { value: 'manager', label: t.sortByManager },
        { value: 'amount', label: t.sortByAmount },
        { value: 'progress', label: t.sortByProgress },
    ];

    const aggregatedData = useMemo(() => {
        const groups = new Map<string, {
            monthYear: string;
            sortKey: number;
            projects: Map<string, {
                projectName: string;
                projectCode: string;
                managerName: string;
                items: { title: string; status: string; amount: number; hasPayment: boolean }[];
                totalAmount: number;
                completedCount: number;
            }>
        }>();

        milestones.forEach(m => {
            if (!m.dueDate) return;
            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const groupSortKey = year * 100 + date.getMonth();

            const project = projects.find(p => p.id === m.projectId);

            if (filterMonthYear.length > 0 && !filterMonthYear.includes(labelKey)) return;
            if (filterProjectId !== 'all' && m.projectId !== filterProjectId) return;
            if (filterStatus !== 'all' && m.status !== filterStatus) return;
            if (filterManagerId !== 'all' && project?.projectManagerId !== filterManagerId) return;

            if (!groups.has(labelKey)) {
                groups.set(labelKey, { monthYear: labelKey, sortKey: groupSortKey, projects: new Map() });
            }

            const projectName = project ? project.name : t.unknownProject;
            const projectId = m.projectId;

            const group = groups.get(labelKey)!;
            if (!group.projects.has(projectId)) {
                group.projects.set(projectId, {
                    projectName,
                    projectCode: project?.projectCode || '',
                    managerName: project?.projectManager?.name || t.unassigned,
                    items: [],
                    totalAmount: 0,
                    completedCount: 0
                });
            }

            const pData = group.projects.get(projectId)!;
            pData.items.push({
                title: m.title,
                status: m.status,
                amount: m.paymentAmount || 0,
                hasPayment: m.hasPayment
            });
            if (m.hasPayment) pData.totalAmount += (m.paymentAmount || 0);
            if (m.status === MilestoneStatus.Paid) pData.completedCount += 1;
        });

        let sortedGroups = Array.from(groups.values());

        if (sortKey === 'date') {
            sortedGroups.sort((a, b) => sortOrder === 'desc' ? b.sortKey - a.sortKey : a.sortKey - b.sortKey);
        } else {
            sortedGroups.sort((a, b) => b.sortKey - a.sortKey);
        }

        return sortedGroups.map(group => {
            let projectsInGroup = Array.from(group.projects.values());

            if (sortKey !== 'date') {
                projectsInGroup.sort((a, b) => {
                    let result = 0;
                    if (sortKey === 'name') result = a.projectName.localeCompare(b.projectName);
                    if (sortKey === 'manager') result = a.managerName.localeCompare(b.managerName);
                    if (sortKey === 'amount') result = b.totalAmount - a.totalAmount;
                    if (sortKey === 'progress') result = (b.completedCount / (b.items.length || 1)) - (a.completedCount / (a.items.length || 1));
                    return sortOrder === 'desc' ? result : -result;
                });
            }

            return {
                monthYear: group.monthYear,
                projects: projectsInGroup,
                totalAmount: projectsInGroup.reduce((sum, p) => sum + p.totalAmount, 0)
            };
        });
    }, [milestones, projects, language, t.unknownProject, t.unassigned, filterProjectId, filterManagerId, filterStatus, filterMonthYear, sortKey, sortOrder]);

    const toggleGroup = (key: string) => {
        setExpandedGroups(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const expandAll = () => {
        const all: Record<string, boolean> = {};
        aggregatedData.forEach(g => all[g.monthYear] = true);
        setExpandedGroups(all);
    };

    const collapseAll = () => {
        setExpandedGroups({});
    };

    const inputClasses = "p-1.5 bg-slate-100 dark:bg-slate-700/50 rounded-md border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-slate-800 dark:text-white text-[11px] w-full h-[34px]";

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="500px">
            {/* Filters Toolbar */}
            <div className="mb-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-4">
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">{t.project}</label>
                        <SearchableSelect options={projectOptions} value={filterProjectId} onChange={setFilterProjectId} placeholder={t.allProjects} language={language} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">{t.manager}</label>
                        <SearchableSelect options={managerOptions} value={filterManagerId} onChange={setFilterManagerId} placeholder={t.allManagers} language={language} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">{t.status}</label>
                        <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className={inputClasses}>
                            {statusOptions.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                        </select>
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">{t.monthYear}</label>
                        <SearchableSelect isMulti options={monthYearOptions} value={filterMonthYear} onChange={setFilterMonthYear} placeholder={t.allMonths} language={language} />
                    </div>
                </div>

                {/* Secondary Controls - Sort and View */}
                <div className="flex flex-wrap items-center justify-between gap-4 pt-4 border-t border-slate-100 dark:border-slate-800/50">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-bold text-slate-400 uppercase">{t.sortBy}:</span>
                            <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-lg">
                                {sortOptions.map(opt => (
                                    <button 
                                        key={opt.value}
                                        onClick={() => setSortKey(opt.value as any)}
                                        className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all ${sortKey === opt.value ? 'bg-white dark:bg-slate-700 text-violet-600 dark:text-violet-400 shadow-sm' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                                    >
                                        {opt.label}
                                    </button>
                                ))}
                            </div>
                        </div>
                        <button 
                            onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
                            className="p-1.5 bg-slate-100 dark:bg-slate-800/50 rounded-lg text-slate-600 dark:text-slate-400 hover:text-violet-600 transition-colors border border-slate-200 dark:border-slate-700"
                        >
                            {sortOrder === 'asc' ? '↑' : '↓'}
                        </button>
                    </div>

                    <div className="flex items-center gap-3">
                        <button onClick={expandAll} className="text-[10px] font-bold text-violet-600 dark:text-violet-400 hover:underline uppercase">{t.expandAll}</button>
                        <span className="text-slate-300 dark:text-slate-700 text-[10px]">|</span>
                        <button onClick={collapseAll} className="text-[10px] font-bold text-slate-500 hover:underline uppercase">{t.collapseAll}</button>
                    </div>
                </div>
            </div>

            <div className="space-y-3 pb-2">
                {aggregatedData.length > 0 ? aggregatedData.map((group, idx) => {
                    const isExpanded = !!expandedGroups[group.monthYear];
                    return (
                        <div key={idx} className="bg-slate-50/50 dark:bg-slate-900/10 rounded-xl border border-slate-100 dark:border-slate-800 overflow-hidden">
                            <button 
                                onClick={() => toggleGroup(group.monthYear)}
                                className="w-full flex items-center justify-between p-3 hover:bg-slate-100 dark:hover:bg-slate-800/40 transition-colors"
                            >
                                <div className="flex items-center gap-3">
                                    <div className={`p-1 rounded transition-colors ${isExpanded ? 'bg-violet-600 text-white' : 'bg-slate-200 dark:bg-slate-800 text-slate-500'}`}>
                                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                                    </div>
                                    <h3 className="text-sm font-black text-slate-800 dark:text-white flex items-center gap-2">
                                        {group.monthYear}
                                        <span className="text-[9px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-500 px-2 py-0.5 rounded-full">
                                            {group.projects.length} {t.projectsCount}
                                        </span>
                                    </h3>
                                </div>
                                {!isExpanded && (
                                    <div className="flex gap-4 text-[10px] font-bold text-slate-400 uppercase">
                                        <span>{t.total}: {group.totalAmount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}</span>
                                    </div>
                                )}
                            </button>

                            {isExpanded && (
                                <div className="p-3 pt-0 space-y-3 animate-in fade-in slide-in-from-top-1 duration-200">
                                    {group.projects.map((p, pIdx) => (
                                        <div key={pIdx} className="bg-white dark:bg-slate-800/60 rounded-lg border border-slate-100 dark:border-slate-700 p-3 shadow-sm">
                                            <div className="flex justify-between items-center mb-3">
                                                <div className="min-w-0">
                                                    <h4 className="font-bold text-slate-800 dark:text-white text-[12px] flex items-center flex-wrap gap-2">
                                                        <span>{p.projectName}</span>
                                                        <span className="text-[9px] font-bold text-violet-600 dark:text-violet-400 bg-violet-100 dark:bg-violet-900/40 px-2 py-0.5 rounded">
                                                            {p.managerName}
                                                        </span>
                                                    </h4>
                                                    <p className="text-[9px] font-mono text-slate-400 mt-0.5">{p.projectCode}</p>
                                                </div>
                                                <div className="text-right shrink-0 flex items-center gap-4">
                                                    <div>
                                                        <p className="text-[8px] text-slate-400 uppercase font-bold">{t.completed}</p>
                                                        <p className="text-[10px] font-bold text-violet-600 dark:text-violet-400">{Math.round((p.completedCount / p.items.length) * 100)}%</p>
                                                    </div>
                                                    {p.totalAmount > 0 && (
                                                        <div>
                                                            <p className="text-[8px] text-slate-400 uppercase font-bold">{t.totalAmount}</p>
                                                            <p className="text-[11px] font-black text-green-600 dark:text-green-400">{p.totalAmount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}</p>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                            <div className="overflow-x-auto">
                                                <table className="w-full text-[11px] text-left rtl:text-right">
                                                    <thead className="text-slate-400 font-medium border-b border-slate-50 dark:border-slate-800">
                                                        <tr>
                                                            <th className="pb-1 font-semibold">{t.milestone}</th>
                                                            <th className="pb-1 text-center">{t.status}</th>
                                                            <th className="pb-1 text-end">{t.amount}</th>
                                                        </tr>
                                                    </thead>
                                                    <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                                                        {p.items.map((item, iIdx) => (
                                                            <tr key={iIdx} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                                                <td className="py-1 text-slate-700 dark:text-slate-200">{item.title}</td>
                                                                <td className="py-1 text-center">
                                                                    <span className={`px-2 py-0.5 rounded-full font-bold text-[8px] ${item.status === MilestoneStatus.Paid ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' : (item.status === MilestoneStatus.Sent ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' : 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400')}`}>
                                                                        {item.status}
                                                                    </span>
                                                                </td>
                                                                <td className="py-1 text-end font-mono text-slate-500 dark:text-slate-400">
                                                                    {item.hasPayment ? item.amount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }) : '--'}
                                                                </td>
                                                            </tr>
                                                        ))}
                                                    </tbody>
                                                </table>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                }) : (
                    <div className="text-center py-10 text-slate-400 text-[11px] italic bg-slate-50 dark:bg-slate-900/20 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-800">
                        {t.noMilestonesMatch}
                    </div>
                )}
            </div>
        </WidgetWrapper>
    );
};

const ProjectStatusChartWidget: React.FC<AnalyticsDashboardProps> = ({ projects, language }) => {
    const t = translations[language];
    const statusCounts = useMemo(() => {
        const counts = new Map<string, { count: number, color: string }>();
        const colors = ['bg-green-500', 'bg-blue-500', 'bg-yellow-500', 'bg-red-500', 'bg-indigo-500', 'bg-pink-500'];
        let colorIndex = 0;
        projects.forEach(p => {
            const statusName = p.status?.name || t.unknownStatus;
            if (!counts.has(statusName)) {
                counts.set(statusName, { count: 0, color: colors[colorIndex % colors.length] });
                colorIndex++;
            }
            counts.get(statusName)!.count++;
        });
        return Array.from(counts.entries());
    }, [projects, t.unknownStatus]);

    const maxCount = Math.max(...statusCounts.map(([, {count}]) => count), 1);

    return (
        <WidgetWrapper title={t.projectStatuses} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {statusCounts.length > 0 ? statusCounts.map(([status, {count, color}]) => (
                    <div key={status} className="flex items-center gap-4">
                        <span className="w-1/3 text-sm text-gray-600 dark:text-gray-300 truncate">{status}</span>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4">
                                <div className={`${color} h-4 rounded-full transition-all duration-500`} style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm">{count}</span>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm">{t.noProjects}</p>}
            </div>
        </WidgetWrapper>
    );
};

interface TeamWorkloadChartWidgetProps extends AnalyticsDashboardProps {
    onTeamClick: (team: Lookup, teamProjects: Project[]) => void;
}

const TeamWorkloadChartWidget: React.FC<TeamWorkloadChartWidgetProps> = ({ projects, teams, language, onTeamClick }) => {
    const t = translations[language];
    const teamProjectCounts = useMemo(() => {
        const counts = new Map<string, { projects: Project[] }>();
        teams.forEach(t => counts.set(t.id, { projects: [] }));
        projects.forEach(p => {
            if (p.teamId && counts.has(p.teamId)) {
                counts.get(p.teamId)!.projects.push(p);
            }
        });
        return Array.from(counts.entries())
            .map(([teamId, data]) => ({ team: teams.find(t => t.id === teamId), count: data.projects.length, teamProjects: data.projects }))
            .filter(item => item.team)
            .sort((a,b) => b.count - a.count);
    }, [projects, teams]);

    const maxCount = Math.max(...teamProjectCounts.map(({ count }) => count), 1);

    return (
         <WidgetWrapper title={t.teamWorkload} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {teamProjectCounts.length > 0 ? teamProjectCounts.map(({ team, count, teamProjects }) => (
                    <div 
                        key={team!.id} 
                        className="flex items-center gap-4 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/30 p-2 rounded-xl transition-all group"
                        onClick={() => onTeamClick(team!, teamProjects)}
                    >
                        <div className="w-1/3 flex items-center gap-2">
                           <span className="text-sm text-gray-600 dark:text-gray-300 truncate group-hover:text-violet-600 dark:group-hover:text-violet-400 font-medium">{team!.name}</span>
                        </div>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 overflow-hidden">
                                <div className="bg-gradient-to-r from-violet-500 to-indigo-500 h-4 rounded-full transition-all duration-500 group-hover:brightness-110" style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm min-w-[1.5rem]">{count}</span>
                        </div>
                    </div>
                )) : <p className="text-gray-500 dark:text-gray-400 text-sm">{t.noTeams}</p>}
            </div>
        </WidgetWrapper>
    );
};

