                                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                                <p className="text-xs font-medium">{t.noItems}</p>
                            </div>
                        ) : (
                            milestonesList.map((item, idx) => (
                                <div key={idx} className="p-3 bg-slate-50 dark:bg-slate-800/40 rounded-xl border border-slate-200 dark:border-slate-700/50 flex justify-between items-center group animate-in slide-in-from-right-2 duration-200">
                                    <div className="min-w-0 flex-1">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className={`px-2 py-0.5 rounded-full text-[9px] font-bold uppercase ${getStatusBadgeClass(item.status)}`}>{t[item.status] || item.status}</span>
                                            <p className="text-sm font-bold text-slate-800 dark:text-white truncate">{item.title}</p>
                                        </div>
                                        <div className="flex items-center gap-3">
                                            <span className="text-[10px] font-bold text-slate-400">{teams.find(tm => tm.id === item.teamId)?.name}</span>
                                            {item.dueDate && <span className="text-[10px] text-slate-400">📅 {new Date(item.dueDate).toLocaleDateString()}</span>}
                                            {item.hasPayment && <span className="text-[10px] text-green-600 dark:text-green-400 font-black">${item.paymentAmount}</span>}
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => removeItem(idx)}
                                        className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg transition-colors"
                                        title={t.remove}
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                    </button>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>

            <div className="flex justify-end space-x-4 rtl:space-x-reverse pt-6 border-t border-slate-200 dark:border-slate-700 mt-6">
                <button type="button" onClick={onClose} className="px-6 py-2.5 text-sm font-bold text-slate-600 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl transition-colors">{t.cancel}</button>
                <button 
                    onClick={handleFinalSubmit}
                    disabled={milestonesList.length === 0} 
                    className="px-8 py-2.5 text-sm font-bold text-white bg-gradient-to-r from-violet-600 to-indigo-600 rounded-xl hover:opacity-90 shadow-lg shadow-violet-500/20 transition-all disabled:opacity-50 disabled:grayscale"
                >
                    {t.saveAll}
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

