import React, { useState, useMemo } from 'react';
import { Milestone, Project, Lookup, MilestoneStatus, Language, PaymentStatus } from '../types';
import SearchableSelect from './SearchableSelect';

interface AddMilestoneModalProps {
  teams: Lookup[];
  projects: Project[];
  onClose: () => void;
  onAddMilestone: (newMilestones: Omit<Milestone, 'id'>[]) => void;
  language: Language;
}

const AddMilestoneModal: React.FC<AddMilestoneModalProps> = ({ teams, projects, onClose, onAddMilestone, language }) => {
  // Master State
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');

  // Details (Current Item) State
  const [currentMilestone, setCurrentMilestone] = useState({
      title: '',
      description: '',
      teamId: '',
      dueDate: '',
      status: MilestoneStatus.Pending,
      hasPayment: false,
      paymentAmount: 0,
      paymentStatus: PaymentStatus.Pending,
  });

  // The list of items to be added
  const [milestonesList, setMilestonesList] = useState<Omit<Milestone, 'id'>[]>([]);

  const [error, setError] = useState<string | null>(null);

  const translations = {
      ar: {
          title: "إضافة معالم للمشروع",
          masterSection: "1. اختر المشروع",
          detailSection: "2. تفاصيل المعلم",
          milestoneTitle: "اسم المعلم",
          description: "الوصف",
          project: "المشروع",
          team: "الفريق المسؤول",
          dueDate: "تاريخ الاستحقاق",
          status: "حالة الإنجاز",
          hasPayment: "مرتبط بدفعة مالية",
          paymentAmount: "المبلغ",
          paymentStatus: "حالة الدفعة",
          addToList: "إضافة للقائمة",
          saveAll: "حفظ الكل",
          cancel: "إلغاء",
          validationErrorFields: "يرجى ملء الحقول المطلوبة (الاسم والفريق).",
          noProjectSelected: "يرجى اختيار المشروع أولاً.",
          listTitle: "المعالم الجاهزة للإضافة",
          noItems: "القائمة فارغة حالياً.",
          remove: "حذف",
          selectHere: "اختر المشروع...",
          selectTeam: "اختر الفريق...",
          searchProject: "ابحث عن مشروع...",
          Pending: "معلق",
          "In Progress": "قيد التنفيذ",
          Completed: "مكتمل",
          Sent: "مرسلة",
          Paid: "مدفوعة",
      },
      en: {
          title: "Add Project Milestones",
          masterSection: "1. Select Project",
          detailSection: "2. Milestone Details",
          milestoneTitle: "Milestone Title",
          description: "Description",
          project: "Project",
          team: "Assigned Team",
          dueDate: "Due Date",
          status: "Work Status",
          hasPayment: "Includes Payment",
          paymentAmount: "Amount",
          paymentStatus: "Payment Status",
          addToList: "Add to List",
          saveAll: "Save All",
          cancel: "Cancel",
          validationErrorFields: "Please fill required fields (Title and Team).",
          noProjectSelected: "Please select a project first.",
          listTitle: "Milestones in Queue",
          noItems: "No milestones added to the queue yet.",
          remove: "Remove",
          selectHere: "Select project...",
          selectTeam: "Select team...",
          searchProject: "Search for a project...",
          Pending: "Pending",
          "In Progress": "In Progress",
          Completed: "Completed",
          Sent: "Sent",
          Paid: "Paid",
      },
  };
  const t = translations[language];

  const projectOptions = useMemo(() => 
    projects.map(p => ({ value: p.id, label: p.name })),
    [projects]
  );

  const handleProjectChange = (projectId: string) => {
      setSelectedProjectId(projectId);
      setError(null);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
      setCurrentMilestone(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
      setCurrentMilestone(prev => ({ ...prev, [name]: value }));
    }
  };

  const addMilestoneToList = () => {
    setError(null);
    if (!selectedProjectId) {
        setError(t.noProjectSelected);
        return;
    }
    if (!currentMilestone.title || !currentMilestone.teamId) {
        setError(t.validationErrorFields);
        return;
    }

    const newItem: Omit<Milestone, 'id'> = {
      ...currentMilestone,
      projectId: selectedProjectId,
      dueDate: currentMilestone.dueDate ? new Date(currentMilestone.dueDate).toISOString() : null,
      paymentAmount: currentMilestone.hasPayment ? currentMilestone.paymentAmount : 0,
      paymentStatus: currentMilestone.hasPayment ? currentMilestone.paymentStatus : null,
    };

    setMilestonesList(prev => [...prev, newItem]);

    // Reset only detail fields
    setCurrentMilestone({
        title: '',
        description: '',
        teamId: '',
        dueDate: '',
        status: MilestoneStatus.Pending,
        hasPayment: false,
        paymentAmount: 0,
        paymentStatus: PaymentStatus.Pending,
    });
  };

  const removeItem = (index: number) => {
      setMilestonesList(prev => prev.filter((_, i) => i !== index));
  };

  const handleFinalSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (milestonesList.length === 0) {
        setError(t.noItems);
        return;
    }
    onAddMilestone(milestonesList);
  };

