                <button 
                    onClick={handleFinalSubmit}
                    disabled={milestonesList.length === 0} 
                    className="px-10 py-3 text-sm font-bold text-white bg-gradient-to-r from-violet-600 to-indigo-600 rounded-xl hover:opacity-90 shadow-lg shadow-violet-500/20 transition-all disabled:opacity-50 disabled:grayscale"
                >
                    {t.saveAll}
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

