          paymentAmount: "المبلغ",
          paymentStatus: "حالة الدفعة",
          addToList: "إضافة للقائمة",
          saveAll: "حفظ الكل",
          cancel: "إلغاء",
          validationErrorFields: "يرجى ملء الحقول المطلوبة (الاسم والفريق).",
          noProjectSelected: "يرجى اختيار المشروع أولاً.",
          listTitle: "المعالم الجاهزة للإضافة",
          noItems: "القائمة فارغة حالياً.",
          remove: "حذف",
          selectHere: "اختر المشروع...",
