    setCurrentMilestone({
        title: '',
        description: '',
        teamId: '',
        dueDate: '',
        status: MilestoneStatus.Pending,
        hasPayment: true, // Keep checked for consecutive additions
        paymentAmount: 0,
        paymentStatus: PaymentStatus.Pending,
