  const getStatusColor = (status: MilestoneStatus) => {
      switch (status) {
          case MilestoneStatus.Completed: return 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400';
          case MilestoneStatus.InProgress: return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400';
          default: return 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400';
      }
  };

  const getPaymentColor = (status: PaymentStatus | null) => {
      switch (status) {
          case PaymentStatus.Paid: return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400';
          case PaymentStatus.Sent: return 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/30 dark:text-cyan-400';
          default: return 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-400';
      }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-50 transition-opacity">
      <div className="bg-white dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-700/50 p-2 rounded-2xl shadow-2xl w-full max-w-6xl m-4" dir={language === 'ar' ? 'rtl' : 'ltr'}>
        <div className="p-6 max-h-[90vh] overflow-y-auto">
