                                            {item.hasPayment && (
                                                <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${getPaymentColor(item.paymentStatus)}`}>💰 {t[item.paymentStatus!] || item.paymentStatus}</span>
                                            )}
                                            <p className="text-sm font-bold text-slate-800 dark:text-white truncate">{item.title}</p>
