export default AddMilestoneModal;

import React, { useState, useMemo } from 'react';
import { Milestone, Project, Lookup, MilestoneStatus, Language, PaymentStatus } from '../types';
import SearchableSelect from './SearchableSelect';

interface AddMilestoneModalProps {
  teams: Lookup[];
  projects: Project[];
  onClose: () => void;
  onAddMilestone: (newMilestones: Omit<Milestone, 'id'>[]) => void;
  language: Language;
}

const AddMilestoneModal: React.FC<AddMilestoneModalProps> = ({ teams, projects, onClose, onAddMilestone, language }) => {
  // Master State
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');

  // Details (Current Item) State
  const [currentMilestone, setCurrentMilestone] = useState({
      title: '',
      description: '',
      teamId: '',
      dueDate: '',
      status: MilestoneStatus.Pending,
      hasPayment: true, // Updated: Changed from false to true by default
      paymentAmount: 0,
      paymentStatus: PaymentStatus.Pending,
  });

  // The list of items to be added
  const [milestonesList, setMilestonesList] = useState<Omit<Milestone, 'id'>[]>([]);

  const [error, setError] = useState<string | null>(null);

  const translations = {
      ar: {
          title: "إضافة معالم للمشروع",
          masterSection: "1. اختر المشروع",
          detailSection: "2. تفاصيل المعلم",
          milestoneTitle: "اسم المعلم",
          description: "الوصف",
          project: "المشروع",
          team: "الفريق المسؤول",
          dueDate: "تاريخ الاستحقاق",
          status: "حالة الإنجاز",
          hasPayment: "مرتبط بدفعة مالية",
          paymentAmount: "المبلغ",
          paymentStatus: "حالة الدفعة",
          addToList: "إضافة للقائمة",
          saveAll: "حفظ الكل",
          cancel: "إلغاء",
          validationErrorFields: "يرجى ملء الحقول المطلوبة (الاسم والفريق).",
          noProjectSelected: "يرجى اختيار المشروع أولاً.",
          listTitle: "المعالم الجاهزة للإضافة",
          noItems: "القائمة فارغة حالياً.",
          remove: "حذف",
          selectHere: "اختر المشروع...",
          selectTeam: "اختر الفريق...",
          searchProject: "ابحث عن مشروع...",
          Pending: "معلق",
          "In Progress": "قيد التنفيذ",
          Completed: "مكتمل",
          Sent: "مرسلة",
