                        <input type="text" name="title" value={currentMilestone.title} onChange={handleInputChange} placeholder={t.milestoneTitle} className={inputClasses}/>
                        <textarea name="description" value={currentMilestone.description} onChange={handleInputChange} placeholder={t.description} rows={2} className={inputClasses}/>

                        <div className="grid grid-cols-2 gap-4">
                            <select name="teamId" value={currentMilestone.teamId} onChange={handleInputChange} className={selectClasses}>
                                <option value="" disabled>{t.selectTeam}</option>
                                {teams.map(tm => (<option key={tm.id} value={tm.id}>{tm.name}</option>))}
                            </select>
                            <input type="date" name="dueDate" value={currentMilestone.dueDate} onChange={handleInputChange} className={inputClasses} />
                        </div>

                        <div className="p-4 bg-slate-50 dark:bg-slate-800/30 rounded-xl border border-slate-100 dark:border-slate-800 space-y-4">
                            <div className="flex items-center justify-between">
