    const handleImportProjects = async (importedRows: ProjectImportRow[]): Promise<void> => {
        if (!isDbConnected) return;
        setNotification(null);

        const t = {
            ar: {
                row: "صف",
                nameMissing: "اسم المشروع مفقود.",
                customerMissing: "اسم العميل مفقود.",
                managerMissing: "اسم مدير المشروع مفقود.",
                statusMissing: "اسم الحالة مفقود.",
                customerNotFound: (name: string) => `العميل '${name}' غير موجود.`,
                managerNotFound: (name: string) => `مدير المشروع '${name}' غير موجود.`,
                statusNotFound: (name: string) => `الحالة '${name}' غير موجودة.`,
                invalidDate: (field: string) => `تنسيق غير صالح لـ ${field} (المتوقع YYYY-MM-DD).`,
                invalidProgress: "يجب أن يكون التقدم رقمًا بين 0 و 100.",
                importSuccess: (count: number) => `تم استيراد ${count} مشروع بنجاح.\n`,
                importFail: (count: number, details: string) => `فشل استيراد ${count} صف.\n${details}`,
                apiError: "خطأ في واجهة برمجة التطبيقات",
            },
            en: {
                row: "Row",
                nameMissing: "Project name is missing.",
                customerMissing: "Customer name is missing.",
                managerMissing: "Project manager name is missing.",
                statusMissing: "Status name is missing.",
                customerNotFound: (name: string) => `Customer '${name}' not found.`,
                managerNotFound: (name: string) => `Project Manager '${name}' not found.`,
                statusNotFound: (name: string) => `Status '${name}' not found.`,
                invalidDate: (field: string) => `Invalid format for ${field} (expected YYYY-MM-DD).`,
                invalidProgress: "Progress must be a number between 0 and 100.",
                importSuccess: (count: number) => `Successfully imported ${count} projects.\n`,
                importFail: (count: number, details: string) => `Failed to import ${count} rows.\n${details}`,
                apiError: "API Error",
            }
        };
        const importT = t[language];

        const validProjects: Omit<Project, 'id' | 'projectCode' | 'country' | 'category' | 'team' | 'product' | 'status' | 'projectManager' | 'customer'>[] = [];
        const errors: string[] = [];

        importedRows.forEach((row, index) => {
            const rowErrors: string[] = [];

            if (!row.name) rowErrors.push(importT.nameMissing);
            if (!row.customerName) rowErrors.push(importT.customerMissing);
            if (!row.projectManagerName) rowErrors.push(importT.managerMissing);
            if (!row.statusName) rowErrors.push(importT.statusMissing);

            if(rowErrors.length > 0) {
                errors.push(`${importT.row} ${index + 2}: ${rowErrors.join(' ')}`);
                return;
            }

            const customer = lookups.customers.find(c => c.name.toLowerCase() === row.customerName?.toLowerCase());
            if (!customer) rowErrors.push(importT.customerNotFound(row.customerName!));

            const manager = lookups.projectManagers.find(pm => pm.name.toLowerCase() === row.projectManagerName?.toLowerCase());
            if (!manager) rowErrors.push(importT.managerNotFound(row.projectManagerName!));

            const status = lookups.projectStatuses.find(s => s.name.toLowerCase() === row.statusName?.toLowerCase());
            if (!status) rowErrors.push(importT.statusNotFound(row.statusName!));

            const validateDate = (dateString: string | undefined): boolean => {
                if (!dateString || dateString.trim() === '') return true;
                return /^\d{4}-\d{2}-\d{2}$/.test(dateString) && !isNaN(new Date(dateString).getTime());
            };

            if (!validateDate(row.launchDate)) rowErrors.push(importT.invalidDate('launchDate'));
            if (!validateDate(row.actualStartDate)) rowErrors.push(importT.invalidDate('actualStartDate'));
            if (!validateDate(row.expectedClosureDate)) rowErrors.push(importT.invalidDate('expectedClosureDate'));

            let progressValue = 0;
            if (row.progress) {
                const parsedProgress = parseInt(row.progress, 10);
                if (isNaN(parsedProgress) || parsedProgress < 0 || parsedProgress > 100) {
                    rowErrors.push(importT.invalidProgress);
                } else {
                    progressValue = parsedProgress;
                }
            }

            if (rowErrors.length > 0) {
                errors.push(`${importT.row} ${index + 2}: ${rowErrors.join(' ')}`);
                return;
            }

            validProjects.push({
                name: row.name!,
                description: row.description || '',
                customerId: customer!.id,
                projectManagerId: manager!.id,
                statusId: status!.id,
                countryId: lookups.countries.find(c => c.name.toLowerCase() === row.countryName?.toLowerCase())?.id || null,
                categoryId: lookups.categories.find(c => c.name.toLowerCase() === row.categoryName?.toLowerCase())?.id || null,
                teamId: lookups.teams.find(t => t.name.toLowerCase() === row.teamName?.toLowerCase())?.id || null,
                productId: lookups.products.find(p => p.name.toLowerCase() === row.productName?.toLowerCase())?.id || null,
                launchDate: row.launchDate || null,
                actualStartDate: row.actualStartDate || null,
                expectedClosureDate: row.expectedClosureDate || null,
                progress: progressValue,
                revenueImpact: 1,
                strategicValue: 1,
                deliveryRisk: 1,
                customerPressure: 1,
                resourceLoad: 1,
            });
        });

        let successCount = 0;
        if (validProjects.length > 0) {
            try {
                const newProjects = await apiAddProjects(validProjects);
                successCount = newProjects.length;
                const newProjectsWithLookups: Project[] = newProjects.map(newProject => ({
                    ...newProject,
                    country: lookups.countries.find(l => l.id === newProject.countryId),
                    category: lookups.categories.find(l => l.id === newProject.categoryId),
                    team: lookups.teams.find(l => l.id === newProject.teamId),
                    product: lookups.products.find(l => l.id === newProject.productId),
                    status: lookups.projectStatuses.find(l => l.id === newProject.statusId),
                    projectManager: lookups.projectManagers.find(l => l.id === newProject.projectManagerId),
                    customer: lookups.customers.find(l => l.id === newProject.customerId),
                }));
                setProjects(prev => [...prev, ...newProjectsWithLookups]);
            } catch (error) {
                errors.push(`${importT.apiError}: ${getApiErrorMessage(error)}`);
            }
        }

        const errorCount = importedRows.length - successCount;
        let message = '';

        if (successCount > 0) {
            message += importT.importSuccess(successCount);
        }
        if (errorCount > 0) {
            const errorDetails = errors.slice(0, 5).join('\n');
            message += importT.importFail(errorCount, errorDetails);
        }

        if (message) {
            setNotification({
                message,
                type: errorCount > 0 ? 'error' : 'success',
            });
        }
        setIsImportModalOpen(false);
    };

    const handleUpdateProject = async (projectId: string, updatedData: Omit<Project, 'id' | 'country' | 'category' | 'team' | 'product' | 'status' | 'projectManager' | 'customer'>): Promise<void> => {
        if (!isDbConnected) {
            const error = new Error(language === 'ar' ? 'غير متصل بقاعدة البيانات.' : 'Not connected to the database.');
            setNotification({ message: error.message, type: 'error' });
            throw error;
        }
        setNotification(null);
        try {
            await apiUpdateProject(projectId, updatedData);
            const updatedProjectWithLookups: Project = {
                id: projectId, ...updatedData,
                country: lookups.countries.find(l => l.id === updatedData.countryId),
                category: lookups.categories.find(l => l.id === updatedData.categoryId),
                team: lookups.teams.find(l => l.id === updatedData.teamId),
                product: lookups.products.find(l => l.id === updatedData.productId),
                status: lookups.projectStatuses.find(l => l.id === updatedData.statusId),
                projectManager: lookups.projectManagers.find(l => l.id === updatedData.projectManagerId),
                customer: lookups.customers.find(l => l.id === updatedData.customerId),
            };
            setProjects(prevProjects => prevProjects.map(p => p.id === projectId ? updatedProjectWithLookups : p));
        } catch (error) {
            console.error("Failed to update project:", error);
            const detailMessage = getApiErrorMessage(error);
            setNotification({ message: `${language === 'ar' ? 'فشل تحديث المشروع' : 'Failed to update project'}: ${detailMessage}`, type: 'error' });
            throw new Error(detailMessage);
        }
    };

    const handleDeleteProject = async (projectId: string) => {
        if (!isDbConnected) return;
        setNotification(null);
        try {
            await apiDeleteProject(projectId);
            setProjects(prevProjects => prevProjects.filter(p => p.id !== projectId));
            setMilestones(prevMilestones => prevMilestones.filter(m => m.projectId !== projectId));
            setDeletingProject(null);
            setNotification({ message: language === 'ar' ? 'تم حذف المشروع بنجاح!' : 'Project deleted successfully!', type: 'success' });
        } catch (error) {
            console.error("Failed to delete project:", error);
            setNotification({ message: `${language === 'ar' ? 'فشل حذف المشروع' : 'Failed to delete project'}: ${getApiErrorMessage(error)}`, type: 'error' });
        }
    };

    const handleAddMilestones = async (newMilestonesData: Omit<Milestone, 'id'>[]) => {
        if (!isDbConnected) return;
        setNotification(null);
        try {
            const newMilestones = await apiAddMilestones(newMilestonesData);
            setMilestones(prevMilestones => [...prevMilestones, ...newMilestones]);
            setNotification({ message: language === 'ar' ? 'تمت إضافة المعالم بنجاح!' : 'Milestones added successfully!', type: 'success' });
        } catch (error) {
            console.error("Failed to add milestones:", error);
            setNotification({ message: `${language === 'ar' ? 'فشل إضافة المعالم' : 'Failed to add milestones'}: ${getApiErrorMessage(error)}`, type: 'error' });
        }
    };

    const handleUpdateMilestone = async (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>): Promise<void> => {
        if (!isDbConnected) {
            const error = new Error(language === 'ar' ? 'غير متصل بقاعدة البيانات.' : 'Not connected to the database.');
            setNotification({ message: error.message, type: 'error' });
            throw error;
        }
        setNotification(null);
        try {
            const updatedMilestone = await apiUpdateMilestone(milestoneId, updatedData);
            setMilestones(prevMilestones => prevMilestones.map(m => m.id === milestoneId ? { ...m, ...updatedMilestone } : m));
        } catch (error) {
            console.error("Failed to update milestone:", error);
            const detailMessage = getApiErrorMessage(error);
            setNotification({ message: `${language === 'ar' ? 'فشل تحديث المعلم' : 'Failed to update milestone'}: ${detailMessage}`, type: 'error' });
            throw new Error(detailMessage);
        }
    };

    const handleAddMilestoneUpdate = async (updateData: Omit<MilestoneUpdate, 'id' | 'createdAt' | 'user'>) => {
        if (!isDbConnected) return;
        setNotification(null);
        try {
            const newUpdate = await apiAddMilestoneUpdate(updateData);
            setMilestoneUpdates(prev => [newUpdate, ...prev]);
        } catch (error) {
             console.error("Failed to add milestone update:", error);
            setNotification({ message: `${language === 'ar' ? 'فشل إضافة تحديث' : 'Failed to add update'}: ${getApiErrorMessage(error)}`, type: 'error' });
        }
    };

    const handleLookupsUpdate = async (lookupType: keyof Lookups, newLookups: Lookup[]) => {
        const t = {
            ar: { success: 'تم تحديث القائمة بنجاح!', error: 'فشل تحديث القائمة' },
            en: { success: 'Lookup list updated successfully!', error: 'Failed to update list' },
        };
        if (!isDbConnected) return;
        setNotification(null);
        try {
            await apiUpdateLookups(lookupType, newLookups);
            setNotification({ message: t[language].success, type: 'success' });
        } catch (error) {
            console.error(`Failed to update ${String(lookupType)}:`, error);
            setNotification({ 
                message: `${t[language].error}: ${getApiErrorMessage(error)}`, 
                type: 'error' 
            });
        } finally {
            // Always reload data to ensure UI consistency after an update attempt.
            await loadDataFromDb();
        }
    };

    const handleAddMaintenanceContract = async (contractData: Omit<MaintenanceContract, 'id' | 'createdAt' | 'customer'>) => {
        if (!isDbConnected) return;
        setNotification(null);
        try {
            const newContract = await apiAddMaintenanceContract(contractData);
            const newContractWithLookups: MaintenanceContract = {
                ...newContract,
                customer: lookups.customers.find(c => c.id === newContract.customerId),
            };
            setMaintenanceContracts(prev => [...prev, newContractWithLookups]);
            setNotification({ message: language === 'ar' ? 'تمت إضافة العقد بنجاح!' : 'Contract added successfully!', type: 'success' });
        } catch (error) {
            console.error("Failed to add contract:", error);
            setNotification({ message: `${language === 'ar' ? 'فشل إضافة العقد' : 'Failed to add contract'}: ${getApiErrorMessage(error)}`, type: 'error' });
            throw error;
        }
    };

    const handleUpdateMaintenanceContract = async (contractId: string, updatedData: Partial<Omit<MaintenanceContract, 'id' | 'createdAt' | 'customer'>>) => {
        if (!isDbConnected) {
             const error = new Error(language === 'ar' ? 'غير متصل بقاعدة البيانات.' : 'Not connected to the database.');
             setNotification({ message: error.message, type: 'error' });
             throw error;
        }
        setNotification(null);
        try {
            const updatedContract = await apiUpdateMaintenanceContract(contractId, updatedData);
            const updatedContractWithLookups: MaintenanceContract = {
                ...updatedContract,
                customer: lookups.customers.find(c => c.id === updatedContract.customerId),
            };
            setMaintenanceContracts(prev => prev.map(c => c.id === contractId ? updatedContractWithLookups : c));
            setNotification({ message: language === 'ar' ? 'تم تحديث العقد بنجاح!' : 'Contract updated successfully!', type: 'success' });
        } catch (error) {
            console.error("Failed to update contract:", error);
            const detailMessage = getApiErrorMessage(error);
            setNotification({ message: `${language === 'ar' ? 'فشل تحديث العقد' : 'Failed to update contract'}: ${detailMessage}`, type: 'error' });
            throw new Error(detailMessage);
        }
    };

    const handleImportMaintenanceContracts = async (importedRows: MaintenanceContractImportRow[]) => {
        if (!isDbConnected) return;
        setNotification(null);

        const t = {
            ar: {
                row: "صف", required: (field: string) => `${field} مطلوب.`, notFound: (type: string, name: string) => `${type} '${name}' غير موجود.`,
                invalid: (field: string) => `${field} غير صالح.`, importSuccess: (count: number) => `تم استيراد ${count} عقد بنجاح.\n`,
                importFail: (count: number, details: string) => `فشل استيراد ${count} صف.\n${details}`, apiError: "خطأ في واجهة برمجة التطبيقات",
                customer: "العميل", projectCode: "كود المشروع",
            },
            en: {
                row: "Row", required: (field: string) => `${field} is required.`, notFound: (type: string, name: string) => `${type} '${name}' not found.`,
                invalid: (field: string) => `Invalid ${field}.`, importSuccess: (count: number) => `Successfully imported ${count} contracts.\n`,
                importFail: (count: number, details: string) => `Failed to import ${count} rows.\n${details}`, apiError: "API Error",
                customer: "Customer", projectCode: "Project Code",
            }
        };
        const importT = t[language];

        const validContracts: Omit<MaintenanceContract, 'id' | 'createdAt' | 'customer'>[] = [];
        const errors: string[] = [];
        const cleanNumberString = (s: string | undefined): string => (s || '').replace(/,/g, '');


        importedRows.forEach((row, index) => {
            const rowErrors: string[] = [];

            const { customerName, month, year, totalAmount } = row;
            if (!customerName) rowErrors.push(importT.required('customerName'));
            if (!month) rowErrors.push(importT.required('month'));
            if (!year) rowErrors.push(importT.required('year'));
            if (!totalAmount) rowErrors.push(importT.required('totalAmount'));

            const customer = lookups.customers.find(c => c.name.toLowerCase() === customerName?.toLowerCase());
            if (customerName && !customer) rowErrors.push(importT.notFound(importT.customer, customerName));

            const monthNum = parseMonth(month);
            if (month && !monthNum && month.toLowerCase().trim() !== 'na') {
                rowErrors.push(importT.invalid('month'));
            }

            const yearNum = parseInt(year, 10);
            if (year && (isNaN(yearNum) || year.length !== 4)) rowErrors.push(importT.invalid('year'));

            const totalNum = parseFloat(cleanNumberString(totalAmount));
            if (totalAmount && isNaN(totalNum)) rowErrors.push(importT.invalid('totalAmount'));

            const startDateParsed = parseDateToYyyyMmDd(row.startDate);
            if (row.startDate && !startDateParsed) rowErrors.push(importT.invalid('startDate'));

            const endDateParsed = parseDateToYyyyMmDd(row.endDate);
            if (row.endDate && !endDateParsed) rowErrors.push(importT.invalid('endDate'));

            if (rowErrors.length > 0) {
                errors.push(`${importT.row} ${index + 2}: ${rowErrors.join(' ')}`);
                return;
            }

            validContracts.push({
                type: row.type || null,
                month: monthNum,
                year: yearNum!,
                customerId: customer!.id,
                projectCode: row.projectCode || null,
                totalAmount: totalNum!,
                collectedAmount: parseFloat(cleanNumberString(row.collectedAmount) || '0') || 0,
                lostAmount: parseFloat(cleanNumberString(row.lostAmount) || '0') || 0,
                startDate: startDateParsed,
                endDate: endDateParsed,
                notes: row.notes || null,
            });
        });

        let successCount = 0;
        if (validContracts.length > 0) {
            try {
                const newContracts = await apiAddMaintenanceContracts(validContracts);
                successCount = newContracts.length;
                const newContractsWithLookups = newContracts.map(c => {
                    return {
                        ...c,
                        customer: lookups.customers.find(cust => cust.id === c.customerId),
                    };
                });
                setMaintenanceContracts(prev => [...prev, ...newContractsWithLookups]);
            } catch (error) {
                errors.push(`${importT.apiError}: ${getApiErrorMessage(error)}`);
            }
        }

        let message = '';
        if (successCount > 0) message += importT.importSuccess(successCount);
        if (errors.length > 0) message += importT.importFail(errors.length, errors.slice(0, 5).join('\n'));

        if (message) {
            setNotification({ message, type: errors.length > 0 ? 'error' : 'success' });
        }
    };


    // --- Render Logic ---
    const currentUser = users.find(u => u.id === session?.user.id);

    const renderView = () => {
        if (isLoading && !projects.length) return <div className="text-center text-slate-400">Loading Data...</div>;

        switch (view) {
            case 'projects':
                return <Projects allProjects={projects} allUsers={users} language={language} onAddProject={handleAddProject} onOpenEditModal={setEditingProject} onOpenDeleteModal={setDeletingProject} searchResult={searchResult?.resultType === 'PROJECTS' ? searchResult.projects : undefined} lookups={lookups} currentUser={currentUser} onOpenImportModal={() => setIsImportModalOpen(true)} isImportModalOpen={isImportModalOpen} onCloseImportModal={() => setIsImportModalOpen(false)} onImportProjects={handleImportProjects} />;
            case 'milestones':
                return <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={handleAddMilestones} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={handleUpdateMilestone} searchResult={searchResult?.resultType === 'MILESTONES' ? searchResult.milestones : undefined} lookups={lookups} currentUser={currentUser} />;
            case 'filter':
                return <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} currentUser={currentUser} onUpdateMilestone={handleUpdateMilestone} />;
            case 'team':
                return <Team allUsers={users} allProjects={projects} language={language} />;
            case 'payments':
                return <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={handleUpdateMilestone} />;
            case 'maintenanceContracts':
                return <MaintenanceContracts contracts={maintenanceContracts} customers={lookups.customers} language={language} onAddContract={handleAddMaintenanceContract} onUpdateContract={handleUpdateMaintenanceContract} />;
            case 'system':
                return <SystemManagement lookups={lookups} onUpdate={handleLookupsUpdate} language={language} onSaveConfig={handleConfigSave} />;
            case 'dashboard':
            default:
                return <AnalyticsDashboard 
                    projects={projects} 
                    milestones={milestones} 
                    teams={lookups.teams} 
                    customers={lookups.customers} 
                    projectManagers={lookups.projectManagers}
                    language={language}
                    currentUser={currentUser}
                    onUpdateMilestone={handleUpdateMilestone}
                />;
        }
    };

    if (isLoading) {
       return <div className="flex items-center justify-center min-h-screen bg-slate-100 dark:bg-slate-900 text-slate-300">Initializing...</div>;
    }

    const notificationClasses = `fixed bottom-5 p-4 rounded-lg shadow-lg text-white text-sm z-[9999] transition-all whitespace-pre-wrap max-w-md ${notification?.type === 'error' ? 'bg-red-800/90 border border-red-600' : 'bg-green-800/90 border border-green-600'} ${language === 'ar' ? 'left-5' : 'right-5'}`;

    if (!isAppConfigured) {
        return (
            <div dir={language === 'ar' ? 'rtl' : 'ltr'} lang={language} className="flex h-screen font-sans transition-colors duration-300 bg-slate-100 dark:bg-slate-900 text-slate-800 dark:text-slate-200">
                {notification && <div className={notificationClasses} role="alert">{notification.message}</div>}
                <Sidebar currentView={'system'} setCurrentView={() => {}} language={language} />
                <div className="flex-1 flex flex-col overflow-hidden">
                    <main className="flex-1 overflow-x-hidden overflow-y-auto p-8">
                        <SystemManagement isSetupMode={true} lookups={lookups} onUpdate={async () => {}} language={language} onSaveConfig={handleConfigSave} />
                    </main>
                </div>
            </div>
        );
    }

    if (!session) {
        return <Login language={language} setLanguage={setLanguage} onLoginSuccess={handleLoginSuccess} supabaseClient={supabaseClient!} />;
    }

    return (
        <div dir={language === 'ar' ? 'rtl' : 'ltr'} lang={language} className="flex h-screen font-sans transition-colors duration-300 bg-slate-100 dark:bg-slate-900 text-slate-800 dark:text-slate-200">
            {editingProject && (
                <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={handleUpdateProject} language={language} />
            )}
            {editingMilestone && (
                <EditMilestoneModal
                    milestoneToEdit={editingMilestone}
                    teams={lookups.teams}
                    projects={projects}
                    allMilestoneUpdates={milestoneUpdates}
                    allUsers={users}
                    currentUser={currentUser}
                    onClose={() => setEditingMilestone(null)}
                    onUpdateMilestone={handleUpdateMilestone}
                    onAddMilestones={handleAddMilestones}
                    onAddUpdate={handleAddMilestoneUpdate}
                    language={language}
                />
            )}
            {viewingMilestone && (
                 <MilestoneDetailModal
                    milestone={viewingMilestone}
                    onClose={() => setViewingMilestone(null)}
                    projects={projects}
                    allMilestoneUpdates={milestoneUpdates}
                    allUsers={users}
                    lookups={lookups}
                    language={language}
                />
            )}
            {deletingProject && (
                <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={() => handleDeleteProject(deletingProject.id)} language={language} />
            )}
            {aiInsightResult && (
                <SearchResultModal
                    result={aiInsightResult}
                    onClose={() => setAiInsightResult(null)}
                    language={language}
                />
            )}
            {notification && <div className={notificationClasses} role="alert">{notification.message}</div>}

            <Sidebar currentView={view} setCurrentView={setView} language={language} />
            <div className="flex-1 flex flex-col overflow-hidden">
                <Header 
                    user={currentUser}
                    language={language} 
                    setLanguage={setLanguage} 
                    onSearch={handleSearch}
                    onLogout={handleLogout}
                    theme={theme}
                    setTheme={setTheme}
                    isDbConnected={isDbConnected}
                />
                <main className="flex-1 overflow-x-hidden overflow-y-auto p-8">
                    {isSearching ? <div className="text-center text-slate-400">Asking AI...</div> : renderView()}
                </main>
            </div>

            <button
                onClick={() => setIsChatbotOpen(true)}
                title={language === 'ar' ? 'اسأل المساعد الذكي' : 'Ask AI Assistant'}
                className="fixed bottom-8 right-8 rtl:right-auto rtl:left-8 z-40 w-16 h-16 bg-gradient-to-r from-violet-600 to-indigo-600 rounded-full flex items-center justify-center shadow-lg cursor-pointer hover:scale-110 transition-transform duration-200 ease-in-out group"
            >
                <span className="absolute inline-flex h-full w-full rounded-full bg-violet-400 opacity-75 animate-ping group-hover:animate-none"></span>
                 <svg xmlns="http://www.w3.org/2000/svg" className="relative w-8 h-8 text-white" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M10 3.5a1.5 1.5 0 011.5 1.5v.065a4.23 4.23 0 010 6.87V15a1.5 1.5 0 01-3 0v-3.065a4.23 4.23 0 010-6.87V5A1.5 1.5 0 0110 3.5zM8.5 7v6.065a2.73 2.73 0 000-4.13V7h3v1.935a2.73 2.73 0 000 4.13V13h-3V7z" />
                    <path d="M5 5.5A1.5 1.5 0 016.5 4h.065a4.23 4.23 0 016.87 0H13.5A1.5 1.5 0 0115 5.5v.065a4.23 4.23 0 010 6.87V12.5A1.5 1.5 0 0113.5 14h-.065a4.23 4.23 0 01-6.87 0H6.5A1.5 1.5 0 015 12.5v-.065a4.23 4.23 0 010-6.87V5.5zm6.065 1.5h-4.13a2.73 2.73 0 000 4.13h4.13a2.73 2.73 0 000-4.13z" />
                </svg>
            </button>

            <Chatbot
                isOpen={isChatbotOpen}
                onClose={() => setIsChatbotOpen(false)}
                language={language}
                projects={projects}
                milestones={milestones}
                users={users}
                lookups={lookups}
            />
        </div>
    );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Milestone, Project, Lookup, MilestoneStatus, Language, PaymentStatus, MilestoneUpdate, User } from '../types';

interface EditMilestoneModalProps {
  milestoneToEdit: Milestone;
  teams: Lookup[];
  projects: Project[];
  allMilestoneUpdates: MilestoneUpdate[];
  allUsers: User[];
  currentUser?: User;
  onClose: () => void;
  onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
  onAddMilestones: (newMilestones: Omit<Milestone, 'id'>[]) => Promise<void>;
  onAddUpdate: (updateData: Omit<MilestoneUpdate, 'id' | 'createdAt' | 'user'>) => Promise<void>;
  language: Language;
}

