          dueDate: "تاريخ الاستحقاق",
          status: "حالة الإنجاز",
          hasPayment: "مرتبط بدفعة مالية",
          paymentAmount: "المبلغ",
          paymentStatus: "حالة الدفعة",
          saveAll: "حفظ كافة التغييرات",
          cancel: "إلغاء",
          addAsNew: "إضافة كمعلم جديد للمشروع",
          submitting: "جاري الحفظ...",
          validationError: "يرجى ملء الحقول المطلوبة (الاسم والفريق).",
          successMessage: "تم الحفظ بنجاح!",
          updatesTitle: "سجل التحديثات",
          noUpdates: "لا توجد تحديثات مسجلة.",
          addUpdatePlaceholder: "اكتب تحديثاً...",
          post: "إرسال",
          Pending: "معلق",
          "In Progress": "قيد التنفيذ",
          Completed: "مكتمل",
          Sent: "مرسلة",
          Paid: "مدفوعة",
          queueTitle: "معالم جديدة سيتم إضافتها",
          queueEmpty: "لم يتم تجهيز معالم إضافية.",
          remove: "حذف",
      },
      en: {
          title: "Manage Project Milestones",
          associatedProject: "Open Project",
          detailSection: "Milestone Data",
          milestoneTitle: "Milestone Title",
          description: "Description",
          project: "Project",
          team: "Assigned Team",
          dueDate: "Due Date",
          status: "Work Status",
          hasPayment: "Includes Payment",
          paymentAmount: "Amount",
          paymentStatus: "Payment Status",
          saveAll: "Save All Changes",
          cancel: "Cancel",
          addAsNew: "Add as New Milestone",
          submitting: "Saving...",
          validationError: "Please fill required fields (Title and Team).",
          successMessage: "Changes saved successfully!",
          updatesTitle: "Updates History",
          noUpdates: "No updates found.",
          addUpdatePlaceholder: "Write an update...",
          post: "Post",
          Pending: "Pending",
          "In Progress": "In Progress",
          Completed: "Completed",
          Sent: "Sent",
          Paid: "Paid",
          queueTitle: "New Milestones in Queue",
          queueEmpty: "No additional milestones prepared.",
          remove: "Remove",
      },
  };
  const t = translations[language];

  const currentProjectName = projects.find(p => p.id === formData.projectId)?.name || '--';
  const milestoneUpdates = allMilestoneUpdates.filter(u => u.milestoneId === milestoneToEdit.id);
  const getUserById = (id: string) => allUsers.find(u => u.id === id);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
        setFormData(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleAddUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUpdateText.trim() || !currentUser) return;
    onAddUpdate({
        milestoneId: milestoneToEdit.id,
        userId: currentUser.id,
        updateText: newUpdateText,
    });
    setNewUpdateText('');
  };

  const addAsNewToQueue = () => {
      if (!formData.title || !formData.teamId) {
          setError(t.validationError);
          return;
      }
      const newItem: Omit<Milestone, 'id'> = {
          ...formData,
          dueDate: formData.dueDate ? new Date(formData.dueDate).toISOString() : null,
          paymentAmount: formData.hasPayment ? Number(formData.paymentAmount) : 0,
          paymentStatus: formData.hasPayment ? formData.paymentStatus : null,
      };
      setNewMilestonesQueue(prev => [...prev, newItem]);
      setError(null);

      // Clear form except project context
      setFormData(prev => ({
          ...prev,
          title: '',
          description: '',
          dueDate: '',
          status: MilestoneStatus.Pending,
          paymentAmount: 0,
      }));
  };

  const handleFinalSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsSuccess(false);

    // 1. Update the original milestone being edited
    if (!formData.title || !formData.teamId) {
        setError(t.validationError);
        return;
    }

    setIsSubmitting(true);
    try {
        // Update current
        const updatedData: Partial<Omit<Milestone, 'id'>> = {
          ...formData,
          dueDate: formData.dueDate ? new Date(formData.dueDate).toISOString() : null,
          paymentAmount: formData.hasPayment ? Number(formData.paymentAmount) : 0,
          paymentStatus: formData.hasPayment ? formData.paymentStatus : null,
        };
        await onUpdateMilestone(milestoneToEdit.id, updatedData);

        // Add any new ones in queue
        if (newMilestonesQueue.length > 0) {
            await onAddMilestones(newMilestonesQueue);
        }

        setIsSuccess(true);
        setTimeout(() => onClose(), 1000);
    } catch (err: any) {
        setError(err?.message || "An unknown error occurred.");
    } finally {
        setIsSubmitting(false);
    }
  };

  const inputClasses = "w-full p-2.5 bg-slate-100 dark:bg-slate-800/50 rounded-lg border border-slate-300 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-violet-500 text-slate-800 dark:text-white text-sm transition-all";
  const selectClasses = "w-full p-2.5 bg-slate-100 dark:bg-slate-800/50 rounded-lg border border-slate-300 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-violet-500 text-slate-800 dark:text-white text-sm";

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-50 transition-opacity">
      <div className="bg-white dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-700/50 p-2 rounded-2xl shadow-2xl w-full max-w-6xl m-4" dir={language === 'ar' ? 'rtl' : 'ltr'}>
        <div className="p-6 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center border-b border-slate-200 dark:border-slate-700 pb-4 mb-6">
                <h2 className="text-2xl font-bold text-slate-800 dark:text-white">{t.title}</h2>
                <button onClick={onClose} className="text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white text-2xl">&times;</button>
            </div>

            {error && <div className="p-3 mb-4 text-sm text-red-800 dark:text-red-200 bg-red-100 dark:bg-red-500/20 rounded-lg" role="alert">{error}</div>}
            {isSuccess && <div className="p-3 mb-4 text-sm text-green-800 dark:text-green-200 bg-green-100 dark:bg-green-500/20 rounded-lg" role="alert">{t.successMessage}</div>}

            <form onSubmit={handleFinalSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Left Side: Form Fields */}
                <div className="lg:col-span-6 space-y-6">
                    <div className="bg-violet-50 dark:bg-violet-900/10 p-4 rounded-xl border border-violet-100 dark:border-violet-800/30">
                        <label className="block text-[10px] font-black text-violet-600 dark:text-violet-400 uppercase tracking-widest mb-1">{t.associatedProject}</label>
                        <div className="text-sm font-bold text-slate-800 dark:text-white flex items-center gap-2">
                             <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-violet-500" viewBox="0 0 20 20" fill="currentColor"><path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" /></svg>
                             {currentProjectName}
                        </div>
                    </div>

                    <div className="space-y-4">
                        <label className="block text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{t.detailSection}</label>
                        <input type="text" name="title" value={formData.title} onChange={handleInputChange} placeholder={t.milestoneTitle} className={inputClasses} required/>
                        <textarea name="description" value={formData.description} onChange={handleInputChange} placeholder={t.description} rows={3} className={inputClasses}/>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">{t.team}</label>
                                <select name="teamId" value={formData.teamId} onChange={handleInputChange} className={selectClasses} required>
                                    <option value="" disabled>{t.team}</option>
                                    {teams.map(tm => (<option key={tm.id} value={tm.id}>{tm.name}</option>))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">{t.dueDate}</label>
                                <input type="date" name="dueDate" value={formData.dueDate} onChange={handleInputChange} className={inputClasses} />
                            </div>
                        </div>

                        <div className="p-4 bg-slate-50 dark:bg-slate-800/30 rounded-xl border border-slate-100 dark:border-slate-800 space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="w-1/2 pe-2">
                                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">{t.status}</label>
                                    <select name="status" value={formData.status} onChange={handleInputChange} className={selectClasses}>
                                        {Object.values(MilestoneStatus).map(s => (<option key={s} value={s}>{t[s] || s}</option>))}
                                    </select>
                                </div>
                                <div className="w-1/2 flex items-center gap-2 pt-4">
                                    <input id="edit_pay_toggle" name="hasPayment" type="checkbox" checked={formData.hasPayment} onChange={handleInputChange} className="w-4 h-4 text-violet-600 rounded border-slate-300 dark:border-slate-600" />
                                    <label htmlFor="edit_pay_toggle" className="text-xs font-bold text-slate-600 dark:text-slate-300">{t.hasPayment}</label>
                                </div>
                            </div>

                            {formData.hasPayment && (
                                <div className="grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-2 duration-200">
                                    <div>
                                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">{t.paymentAmount}</label>
                                        <input type="number" name="paymentAmount" value={formData.paymentAmount} onChange={handleInputChange} className={inputClasses} placeholder="0.00" min="0" />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">{t.paymentStatus}</label>
                                        <select name="paymentStatus" value={formData.paymentStatus || ''} onChange={handleInputChange} className={selectClasses}>
                                            {Object.values(PaymentStatus).map(s => (<option key={s} value={s}>{t[s] || s}</option>))}
                                        </select>
                                    </div>
                                </div>
                            )}
                        </div>

                        <button 
                            type="button" 
                            onClick={addAsNewToQueue}
                            className="w-full py-3 bg-slate-800 dark:bg-slate-700 text-white text-sm font-bold rounded-xl hover:bg-slate-700 dark:hover:bg-slate-600 transition-colors flex items-center justify-center gap-2 shadow-lg"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                            {t.addAsNew}
                        </button>
                    </div>
                </div>

                {/* Right Side: Queue + Updates */}
                <div className="lg:col-span-6 border-l dark:border-slate-800 px-4 rtl:border-l-0 rtl:border-r flex flex-col h-full space-y-8">
                    {/* New Milestones Queue Section */}
                    <div>
                        <h3 className="text-sm font-black text-violet-600 dark:text-violet-400 uppercase tracking-wider mb-4 flex justify-between items-center">
                            {t.queueTitle}
                            <span className="bg-violet-100 dark:bg-violet-900/50 px-2 py-0.5 rounded text-[10px]">{newMilestonesQueue.length}</span>
                        </h3>
                        <div className="max-h-[200px] overflow-y-auto custom-scrollbar space-y-2 mb-4 border-b dark:border-slate-800 pb-4">
                            {newMilestonesQueue.length > 0 ? newMilestonesQueue.map((item, qIdx) => (
                                <div key={qIdx} className="p-3 bg-slate-50 dark:bg-slate-800/40 rounded-xl border border-slate-100 dark:border-slate-800 flex justify-between items-center group">
                                    <div className="min-w-0">
                                        <p className="text-xs font-bold text-slate-800 dark:text-white truncate">{item.title}</p>
                                        <p className="text-[10px] text-slate-500 font-bold flex items-center gap-2">
                                            <span>{teams.find(tm => tm.id === item.teamId)?.name}</span>
                                            {item.hasPayment && <span className="text-green-600 dark:text-green-400">${item.paymentAmount.toLocaleString()}</span>}
                                        </p>
                                    </div>
                                    <button 
                                        type="button"
                                        onClick={() => setNewMilestonesQueue(prev => prev.filter((_, i) => i !== qIdx))}
                                        className="p-1.5 text-slate-400 hover:text-red-500 transition-colors"
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                    </button>
                                </div>
                            )) : <p className="text-xs text-slate-400 text-center py-4 italic">{t.queueEmpty}</p>}
                        </div>
                    </div>

                    {/* Updates Section */}
                    <div className="flex-grow flex flex-col min-h-0">
                        <h3 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-wider mb-4">{t.updatesTitle}</h3>
                        <div className="flex-grow space-y-4 max-h-[300px] overflow-y-auto custom-scrollbar pr-2 rtl:pl-2 mb-6">
                            {milestoneUpdates.length > 0 ? milestoneUpdates.map(update => {
                                const user = getUserById(update.userId);
                                return (
                                    <div key={update.id} className="flex items-start gap-3 group">
                                        <img src={user?.avatarUrl || `https://ui-avatars.com/api/?name=${user?.name || '?'}&background=a78bfa&color=f5f3ff`} alt={user?.name || 'User'} className="w-8 h-8 rounded-full mt-1 flex-shrink-0 border border-slate-200 dark:border-slate-700" />
                                        <div className="flex-1 min-w-0">
                                            <div className="flex justify-between items-center mb-0.5">
                                                <span className="text-xs font-bold text-slate-700 dark:text-slate-200">{user?.name}</span>
                                                <span className="text-[10px] text-slate-400">{new Date(update.createdAt).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' })}</span>
                                            </div>
                                            <p className="text-sm text-slate-600 dark:text-slate-300 bg-slate-50 dark:bg-slate-800/40 p-2.5 rounded-lg rounded-tl-none rtl:rounded-tl-lg rtl:rounded-tr-none border border-slate-100 dark:border-slate-800/60 whitespace-pre-wrap">{update.updateText}</p>
                                        </div>
                                    </div>
                                )
                            }) : (
                                <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50 py-10">
                                    <p className="text-xs font-medium">{t.noUpdates}</p>
                                </div>
                            )}
                        </div>

                        <div className="mt-auto">
                            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-800/30 p-2 rounded-xl border border-slate-100 dark:border-slate-800">
                                <img src={currentUser?.avatarUrl || `https://ui-avatars.com/api/?name=${currentUser?.name || '?'}&background=8b5cf6&color=f5f3ff`} alt={currentUser?.name} className="w-8 h-8 rounded-full flex-shrink-0" />
                                <input
                                    type="text"
                                    value={newUpdateText}
                                    onChange={(e) => setNewUpdateText(e.target.value)}
                                    placeholder={t.addUpdatePlaceholder}
                                    className="flex-grow bg-transparent border-none focus:ring-0 text-sm placeholder-slate-400 dark:placeholder-slate-500 dark:text-white"
                                />
                                <button type="button" onClick={handleAddUpdate} disabled={!newUpdateText.trim()} className="px-4 py-1.5 text-xs font-bold text-white bg-violet-600 rounded-lg hover:bg-violet-700 transition-colors disabled:opacity-50">{t.post}</button>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-12 flex justify-end space-x-4 rtl:space-x-reverse pt-6 border-t border-slate-200 dark:border-slate-700 mt-6">
                    <button type="button" onClick={onClose} className="px-6 py-2.5 text-sm font-bold text-slate-600 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl transition-colors">{t.cancel}</button>
                    <button type="submit" disabled={isSubmitting || isSuccess} className="px-10 py-2.5 text-sm font-bold text-white bg-gradient-to-r from-violet-600 to-indigo-600 rounded-xl hover:opacity-90 shadow-lg shadow-violet-500/20 transition-all disabled:opacity-50">
                        {isSubmitting ? t.submitting : t.saveAll}
                    </button>
                </div>
            </form>
        </div>
      </div>
    </div>
  );
};

export default EditMilestoneModal;

import React, { useState, useEffect } from 'react';
import { Milestone, Project, Lookup, MilestoneStatus, Language, PaymentStatus, MilestoneUpdate, User } from '../types';

interface EditMilestoneModalProps {
  milestoneToEdit: Milestone;
  teams: Lookup[];
  projects: Project[];
  allMilestoneUpdates: MilestoneUpdate[];
  allUsers: User[];
  currentUser?: User;
  onClose: () => void;
  onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
  onAddMilestones: (newMilestones: Omit<Milestone, 'id'>[]) => Promise<void>;
  onAddUpdate: (updateData: Omit<MilestoneUpdate, 'id' | 'createdAt' | 'user'>) => Promise<void>;
  language: Language;
}

const EditMilestoneModal: React.FC<EditMilestoneModalProps> = ({ 
    milestoneToEdit, 
    teams, 
    projects, 
    allMilestoneUpdates, 
    allUsers, 
    currentUser, 
    onClose, 
    onUpdateMilestone, 
    onAddMilestones,
    onAddUpdate, 
    language 
}) => {
    // Current Form State
    const [formData, setFormData] = useState<Omit<Milestone, 'id'>>({
        title: '', 
        description: '', 
        projectId: '', 
        teamId: '', 
        dueDate: '',
        status: MilestoneStatus.Pending, 
        hasPayment: true, 
        paymentAmount: 0, 
        paymentStatus: PaymentStatus.Pending,
    });

    // Queue for adding new milestones while in edit mode
    const [newItemsQueue, setNewItemsQueue] = useState<Omit<Milestone, 'id'>[]>([]);

    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [isSuccess, setIsSuccess] = useState(false);
    const [newUpdateText, setNewUpdateText] = useState('');

    useEffect(() => {
        if (milestoneToEdit) {
            const isValidDate = milestoneToEdit.dueDate && !isNaN(new Date(milestoneToEdit.dueDate).getTime());
            setFormData({
                title: milestoneToEdit.title || '',
                description: milestoneToEdit.description || '',
                projectId: milestoneToEdit.projectId || '',
                teamId: milestoneToEdit.teamId || '',
                dueDate: isValidDate ? new Date(milestoneToEdit.dueDate!).toISOString().split('T')[0] : '',
                status: milestoneToEdit.status || MilestoneStatus.Pending,
                hasPayment: milestoneToEdit.hasPayment ?? false,
                paymentAmount: milestoneToEdit.paymentAmount || 0,
                paymentStatus: milestoneToEdit.paymentStatus || PaymentStatus.Pending,
            });
        }
    }, [milestoneToEdit]);

    const translations = {
      ar: {
          title: "إدارة معالم المشروع",
          associatedProject: "المشروع المفتوح",
          detailSection: "تفاصيل المعلم الحالي",
          milestoneTitle: "اسم المعلم",
          description: "الوصف",
          project: "المشروع",
          team: "الفريق المسؤول",
          dueDate: "تاريخ الاستحقاق",
          status: "حالة الإنجاز",
          hasPayment: "مرتبط بدفعة مالية",
          paymentAmount: "المبلغ",
          paymentStatus: "حالة الدفعة",
          saveAll: "حفظ كافة التغييرات",
          cancel: "إلغاء",
          addAsNew: "إضافة كمعلم جديد لهذا المشروع",
          submitting: "جاري الحفظ...",
          validationError: "يرجى ملء الحقول المطلوبة (الاسم والفريق).",
          successMessage: "تم الحفظ بنجاح!",
          updatesTitle: "سجل التحديثات والمناقشات",
          noUpdates: "لا توجد تحديثات مسجلة لهذا المعلم.",
          addUpdatePlaceholder: "اكتب تحديثاً أو ملاحظة...",
          post: "نشر",
          Pending: "معلق",
          "In Progress": "قيد التنفيذ",
          Completed: "مكتمل",
          Sent: "مرسلة",
          Paid: "مدفوعة",
          queueTitle: "معالم جديدة سيتم إضافتها",
          queueEmpty: "القائمة فارغة.",
          remove: "حذف"
      },
      en: {
          title: "Manage Project Milestones",
          associatedProject: "Active Project",
          detailSection: "Current Milestone Details",
          milestoneTitle: "Milestone Title",
          description: "Description",
          project: "Project",
          team: "Assigned Team",
          dueDate: "Due Date",
          status: "Status",
          hasPayment: "Includes Payment",
          paymentAmount: "Amount",
          paymentStatus: "Payment Status",
          saveAll: "Save All Changes",
          cancel: "Cancel",
          addAsNew: "Add as New Milestone to Project",
          submitting: "Saving Changes...",
          validationError: "Please fill required fields (Title and Team).",
          successMessage: "Changes saved successfully!",
          updatesTitle: "Discussion & Update History",
          noUpdates: "No updates for this milestone.",
          addUpdatePlaceholder: "Write an update...",
          post: "Post",
          Pending: "Pending",
          "In Progress": "In Progress",
          Completed: "Completed",
          Sent: "Sent",
          Paid: "Paid",
          queueTitle: "New Milestones in Queue",
          queueEmpty: "Queue is empty.",
          remove: "Remove"
      },
  };
  const t = translations[language];

  const currentProjectName = projects.find(p => p.id === formData.projectId)?.name || '--';
  const milestoneUpdates = allMilestoneUpdates.filter(u => u.milestoneId === milestoneToEdit.id);
  const getUserById = (id: string) => allUsers.find(u => u.id === id);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
        setFormData(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleAddUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUpdateText.trim() || !currentUser) return;
    onAddUpdate({
        milestoneId: milestoneToEdit.id,
        userId: currentUser.id,
        updateText: newUpdateText,
    });
    setNewUpdateText('');
  };

  const addToQueue = () => {
      if (!formData.title || !formData.teamId) {
          setError(t.validationError);
          return;
      }
      const newItem: Omit<Milestone, 'id'> = {
          ...formData,
          dueDate: formData.dueDate ? new Date(formData.dueDate).toISOString() : null,
          paymentAmount: formData.hasPayment ? Number(formData.paymentAmount) : 0,
          paymentStatus: formData.hasPayment ? formData.paymentStatus : null,
      };
      setNewItemsQueue(prev => [...prev, newItem]);
      setError(null);
      // Reset details for next entry
      setFormData(prev => ({
          ...prev,
          title: '',
          description: '',
          dueDate: '',
          status: MilestoneStatus.Pending,
          paymentAmount: 0,
      }));
  };

  const handleFinalSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsSuccess(false);

    if (!formData.title && newItemsQueue.length === 0) {
        setError(t.validationError);
        return;
    }

    setIsSubmitting(true);
    try {
        // 1. Update current milestone
        if (formData.title) {
            const updatedData: Partial<Omit<Milestone, 'id'>> = {
                ...formData,
                dueDate: formData.dueDate ? new Date(formData.dueDate).toISOString() : null,
                paymentAmount: formData.hasPayment ? Number(formData.paymentAmount) : 0,
                paymentStatus: formData.hasPayment ? formData.paymentStatus : null,
            };
            await onUpdateMilestone(milestoneToEdit.id, updatedData);
        }

        // 2. Add new milestones in queue
        if (newItemsQueue.length > 0) {
            await onAddMilestones(newItemsQueue);
        }

        setIsSuccess(true);
        setTimeout(() => onClose(), 1000);
    } catch (err: any) {
        setError(err?.message || "Error saving changes.");
    } finally {
        setIsSubmitting(false);
