// Helper to get current Month Year label based on language
const getCurrentMonthYearLabel = (lang: Language) => {
    const now = new Date();
    const month = now.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
    return `${month} ${now.getFullYear()}`;
};

// --- Widget Component Definitions ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, showPadding?: boolean }> = ({ title, children, maxHeight = '400px', showPadding = true }) => (
    <div className={`bg-white dark:bg-gray-800/50 ${showPadding ? 'p-6' : 'pt-6'} rounded-2xl shadow-sm dark:shadow-none h-full flex flex-col`}>
        <h2 className={`text-xl font-semibold text-gray-900 dark:text-white mb-6 ${showPadding ? '' : 'px-6'}`}>{title}</h2>
        <div className="flex-grow overflow-y-auto custom-scrollbar" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<{ filteredProjects: Project[], filteredMilestones: Milestone[], language: Language }> = ({ filteredProjects, filteredMilestones, language }) => {
    const t = translations[language];

    const stats = useMemo(() => {
        let pendingVal = 0;
        let sentVal = 0;
        let paidVal = 0;

        filteredMilestones.forEach(m => {
            if (!m.hasPayment) return;
            const amount = m.paymentAmount || 0;
            const status = m.paymentStatus || PaymentStatus.Pending;

            if (status === PaymentStatus.Pending) pendingVal += amount;
            else if (status === PaymentStatus.Sent) sentVal += amount;
            else if (status === PaymentStatus.Paid) paidVal += amount;
        });

        return {
            projectsCount: filteredProjects.length,
            pendingVal,
            sentVal,
            paidVal
        };
    }, [filteredProjects, filteredMilestones]);

    const formatVal = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title={t.totalProjects} value={stats.projectsCount.toString()} icon="projects" />
            <StatCard title={t.filteredPending} value={formatVal(stats.pendingVal)} icon="inProgress" trendColor="text-yellow-500" />
            <StatCard title={t.filteredSent} value={formatVal(stats.sentVal)} icon="completed" trendColor="text-blue-500" />
            <StatCard title={t.filteredPaid} value={formatVal(stats.paidVal)} icon="hours" trendColor="text-green-500" />
        </div>
    );
};

const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];

    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();

        filteredMilestones.forEach(m => {
            if (!m.dueDate || !m.hasPayment) return;

            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();

            if (!groups.has(labelKey)) {
                groups.set(labelKey, { totalAmount: 0, sortKey });
            }
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });

        return Array.from(groups.entries())
            .map(([monthYear, data]) => ({ monthYear, ...data }))
            .sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);

    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 50000);
    const yAxisMax = Math.ceil(maxAmount / 50000) * 50000;
    const yAxisMarks = [yAxisMax, yAxisMax * 0.66, yAxisMax * 0.33, 0];

    const formatLabelValue = (val: number) => {
        return `$${(val / 1000).toLocaleString(undefined, { minimumFractionDigits: 1, maximumFractionDigits: 1 })}K`;
    };

    const getShortMonthYear = (my: string) => {
        const [m, y] = my.split(' ');
        const monthsEn = { January: '1', February: '2', March: '3', April: '4', May: '5', June: '6', July: '7', August: '8', September: '9', October: '10', November: '11', December: '12' };
        const monthsAr = { "يناير": '1', "فبراير": '2', "مارس": '3', "أبريل": '4', "مايو": '5', "يونيو": '6', "يوليو": '7', "أغسطس": '8', "سبتمبر": '9', "أكتوبر": '10', "نوفمبر": '11', "ديسمبر": '12' };
        const monthNum = (language === 'ar' ? (monthsAr as any)[m] : (monthsEn as any)[m]) || '?';
        return `${monthNum}/${y}`;
    };

    return (
        <WidgetWrapper title={t.executionChartTitle} maxHeight="none">
            <div className="relative mt-4 mb-8 px-2 overflow-visible">
                <div className="flex h-64 relative overflow-visible">
                    <div className="w-14 flex flex-col justify-between text-[11px] font-bold text-slate-400 pb-8 pr-3 text-right">
                        {yAxisMarks.map((val, idx) => (
                            <span key={idx}>${(val / 1000).toFixed(0)}K</span>
                        ))}
                    </div>

                    <div className="flex-1 flex items-end gap-3 pb-8 relative border-l border-slate-200 dark:border-slate-800/50 overflow-visible">
                        <div className="absolute inset-0 flex flex-col justify-between pointer-events-none pb-8">
                             {[0, 1, 2, 3].map(i => (
                                <div key={i} className="w-full border-t border-slate-100 dark:border-slate-800 border-dashed"></div>
                             ))}
                        </div>

                        {graphData.map((d, i) => (
                            <div key={i} className="flex-1 min-w-[75px] flex flex-col items-center justify-end h-full group relative overflow-visible">
                                <div 
                                    style={{ height: `${Math.max(4, (d.totalAmount / yAxisMax) * 100)}%` }}
                                    className="w-full max-w-[54px] relative group/bar"
                                >
                                    <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-1 z-20 text-[12px] font-black text-slate-900 dark:text-slate-100 whitespace-nowrap transition-transform group-hover/bar:scale-110">
                                        {d.totalAmount > 0 ? formatLabelValue(d.totalAmount) : ''}
                                    </span>
                                    <div 
                                        className="w-full h-full bg-violet-600 rounded-t-[2px] shadow-sm transition-all duration-500 hover:bg-violet-500 cursor-pointer"
                                        title={`${d.monthYear}: ${formatLabelValue(d.totalAmount)}`}
                                    />
                                </div>
                                <span className="absolute top-full mt-2 text-[11px] font-bold text-slate-500 whitespace-nowrap">
                                    {getShortMonthYear(d.monthYear)}
                                </span>
                            </div>
                        ))}
                        {graphData.length === 0 && <div className="absolute inset-0 flex items-center justify-center text-slate-400 text-xs italic">{t.noData}</div>}
                    </div>
                </div>
            </div>
        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], language: Language }> = ({ projectsWithMilestones, language }) => {
    const t = translations[language];
    const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();

        projectsWithMilestones.forEach(p => {
            p.milestones.forEach((m: any) => {
                if (!m.dueDate) return;
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();

                if (!dateGroups.has(label)) {
                    dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                }

                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0 };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) projInGroup.groupTotal += (m.paymentAmount || 0);
            });
        });

        return Array.from(dateGroups.values()).sort((a, b) => b.sortKey - a.sortKey);
    }, [projectsWithMilestones, language]);

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="500px">
            <div className="space-y-3 pb-2">
                {aggregatedByDate.length > 0 ? aggregatedByDate.map((group, idx) => {
                    const isExpanded = !!expandedGroups[group.monthYear];
                    const totalVal = group.projects.reduce((s, p) => s + p.groupTotal, 0);
                    return (
                        <div key={idx} className="bg-slate-50/50 dark:bg-slate-900/10 rounded-xl border border-slate-100 dark:border-slate-800 overflow-hidden">
                            <button onClick={() => setExpandedGroups(p => ({ ...p, [group.monthYear]: !isExpanded }))} className="w-full flex items-center justify-between p-3 hover:bg-slate-100 dark:hover:bg-slate-800/40 transition-colors">
                                <div className="flex items-center gap-3">
                                    <div className={`p-1 rounded ${isExpanded ? 'bg-violet-600 text-white' : 'bg-slate-200 dark:bg-slate-800 text-slate-500'}`}>
                                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                                    </div>
                                    <h3 className="text-sm font-black text-slate-800 dark:text-white">{group.monthYear}</h3>
                                </div>
                                <span className="text-[10px] font-bold text-slate-400">{t.total}: {totalVal.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}</span>
                            </button>
                            {isExpanded && (
                                <div className="p-3 pt-0 space-y-2 animate-in fade-in slide-in-from-top-1">
                                    {group.projects.map((p, pi) => (
                                        <div key={pi} className="bg-white dark:bg-slate-800/60 p-3 rounded-lg border border-slate-100 dark:border-slate-700">
                                            <div className="flex justify-between items-center mb-2">
                                                <h4 className="font-bold text-[12px] text-slate-800 dark:text-white">{p.name}</h4>
                                                <span className="text-[10px] font-black text-violet-600 dark:text-violet-400">{p.groupTotal.toLocaleString()} $</span>
                                            </div>
                                            <ul className="space-y-1">
                                                {p.milestonesInGroup.map((m: any, mi: number) => (
                                                    <li key={mi} className="text-[10px] flex justify-between text-slate-500 dark:text-slate-400">
                                                        <span>• {m.title}</span>
                                                        <span className={m.paymentStatus === 'Paid' ? 'text-green-500' : 'text-yellow-500'}>{t[m.paymentStatus || 'Pending']}</span>
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                }) : <div className="text-center py-10 text-slate-400 italic text-xs">{t.noData}</div>}
            </div>
        </WidgetWrapper>
    );
};

const PaymentBreakdownChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];
    const statusCounts = useMemo(() => {
        const counts = { [PaymentStatus.Paid]: 0, [PaymentStatus.Sent]: 0, [PaymentStatus.Pending]: 0 };
        filteredMilestones.forEach(m => {
            if (m.hasPayment) {
                const s = m.paymentStatus || PaymentStatus.Pending;
                (counts as any)[s]++;
            }
        });
        return Object.entries(counts);
    }, [filteredMilestones]);

    const maxCount = Math.max(...statusCounts.map(([, c]) => c), 1);
    const colorMap: any = { [PaymentStatus.Paid]: 'bg-green-500', [PaymentStatus.Sent]: 'bg-blue-500', [PaymentStatus.Pending]: 'bg-yellow-500' };

    return (
        <WidgetWrapper title={t.paymentBreakdown} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {statusCounts.map(([status, count]) => (
                    <div key={status} className="flex items-center gap-4">
                        <span className="w-1/3 text-sm text-gray-600 dark:text-gray-300 truncate">{t[status as any]}</span>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 overflow-hidden">
                                <div className={`${colorMap[status]} h-4 transition-all duration-500`} style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm">{count}</span>
                        </div>
                    </div>
                ))}
            </div>
        </WidgetWrapper>
    );
};

const TeamWorkloadChartWidget: React.FC<{ filteredProjects: Project[], teams: Lookup[], language: Language, onTeamClick: any }> = ({ filteredProjects, teams, language, onTeamClick }) => {
    const t = translations[language];
    const teamStats = useMemo(() => {
        return teams.map(tm => {
            const pjs = filteredProjects.filter(p => p.teamId === tm.id);
            return { team: tm, count: pjs.length, projects: pjs };
        }).filter(s => s.count > 0).sort((a,b) => b.count - a.count);
    }, [filteredProjects, teams]);

    const max = Math.max(...teamStats.map(s => s.count), 1);

    return (
         <WidgetWrapper title={t.teamWorkload} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {teamStats.map(s => (
                    <div key={s.team.id} className="flex items-center gap-4 cursor-pointer group" onClick={() => onTeamClick(s.team, s.projects)}>
                        <span className="w-1/3 text-sm text-gray-600 dark:text-gray-300 truncate group-hover:text-violet-600 font-medium">{s.team.name}</span>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 overflow-hidden">
                                <div className="bg-violet-500 h-4 transition-all duration-500 group-hover:bg-violet-400" style={{ width: `${s.count / max * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm">{s.count}</span>
                        </div>
                    </div>
                ))}
            </div>
        </WidgetWrapper>
    );
};

