interface AnalyticsDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    customers: Lookup[];
    projectManagers: User[];
    language: Language;
    currentUser?: User;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, teams, projectManagers, language }) => {
    const t = translations[language];

    // Global Filters State
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [globalMonthYear, setGlobalMonthYear] = useState<string[]>([]);

    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });

    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [viewingProject, setViewingProject] = useState<any>(null);
    const [viewingTeam, setViewingTeam] = useState<any>(null);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, string>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                unique.set(label, label);
            }
        });
        return Array.from(unique.values()).map(v => ({ value: v, label: v }));
    }, [milestones, language]);

    // Derived Filtered Data
    const { filteredProjects, filteredMilestones } = useMemo(() => {
        const fps = projects.filter(p => {
            if (globalProjectId !== 'all' && p.id !== globalProjectId) return false;
            if (globalManagerId !== 'all' && p.projectManagerId !== globalManagerId) return false;
            return true;
        });

        const projectIds = new Set(fps.map(p => p.id));
        const fms = milestones.filter(m => {
            if (!projectIds.has(m.projectId)) return false;
            if (globalMonthYear.length > 0) {
                if (!m.dueDate) return false;
                const d = new Date(m.dueDate);
                const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`;
                if (!globalMonthYear.includes(label)) return false;
            }
            return true;
        });

        return { filteredProjects: fps, filteredMilestones: fms };
    }, [projects, milestones, globalProjectId, globalManagerId, globalMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map(p => ({
            ...p,
            milestones: filteredMilestones.filter(m => m.projectId === p.id)
        })).filter(p => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    return (
        <div className="space-y-8">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}
            {viewingProject && <ProjectDetailModal projectWithMilestones={viewingProject} onClose={() => setViewingProject(null)} language={language} />}
            {viewingTeam && <TeamProjectsModal team={viewingTeam.team} projects={viewingTeam.projects} onClose={() => setViewingTeam(null)} language={language} onViewProject={(p) => { setViewingTeam(null); setViewingProject({ ...p, milestones: milestones.filter(m => m.projectId === p.id) }); }} />}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{t.dashboard}</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">{t.overview}</p>
                </div>
