interface AnalyticsDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    customers: Lookup[];
    projectManagers: User[];
    language: Language;
    currentUser?: User;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, teams, projectManagers, language }) => {
    const t = translations[language];

    // Global Filters State
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [globalMonthYear, setGlobalMonthYear] = useState<string[]>([]);

    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });

    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [viewingProject, setViewingProject] = useState<any>(null);
    const [viewingTeam, setViewingTeam] = useState<any>(null);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                unique.set(label, { label, sortKey });
            }
        });
        // Fixed: Ensure filter options are also sorted ASC
        return Array.from(unique.values())
            .sort((a, b) => a.sortKey - b.sortKey)
            .map(v => ({ value: v.label, label: v.label }));
    }, [milestones, language]);

    // Derived Filtered Data
    const { filteredProjects, filteredMilestones } = useMemo(() => {
        const fps = projects.filter(p => {
            if (globalProjectId !== 'all' && p.id !== globalProjectId) return false;
            if (globalManagerId !== 'all' && p.projectManagerId !== globalManagerId) return false;
            return true;
        });

        const projectIds = new Set(fps.map(p => p.id));
        const fms = milestones.filter(m => {
            if (!projectIds.has(m.projectId)) return false;
            if (globalMonthYear.length > 0) {
                if (!m.dueDate) return false;
                const d = new Date(m.dueDate);
                const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`;
                if (!globalMonthYear.includes(label)) return false;
            }
            return true;
        });

        return { filteredProjects: fps, filteredMilestones: fms };
    }, [projects, milestones, globalProjectId, globalManagerId, globalMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map(p => ({
            ...p,
            milestones: filteredMilestones.filter(m => m.projectId === p.id)
        })).filter(p => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    return (
        <div className="space-y-8">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}
            {viewingProject && <ProjectDetailModal projectWithMilestones={viewingProject} onClose={() => setViewingProject(null)} language={language} />}
            {viewingTeam && <TeamProjectsModal team={viewingTeam.team} projects={viewingTeam.projects} onClose={() => setViewingTeam(null)} language={language} onViewProject={(p) => { setViewingTeam(null); setViewingProject({ ...p, milestones: milestones.filter(m => m.projectId === p.id) }); }} />}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{t.dashboard}</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">{t.overview}</p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-slate-200 dark:bg-slate-700/50 hover:bg-slate-300 p-2.5 rounded-full flex items-center gap-2 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 003.464V16a1 1 0 102 0V8.732a2 2 0 00-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" /></svg>
                    <span className="text-sm font-bold px-1">{t.customize}</span>
                </button>
            </div>

            {/* Global Filter Bar */}
            <div className="bg-white dark:bg-slate-900/40 p-4 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{t.project}</label>
                    <SearchableSelect options={[{value:'all', label:t.allProjects}, ...projects.map(p => ({value:p.id, label:p.name}))]} value={globalProjectId} onChange={setGlobalProjectId} placeholder={t.allProjects} language={language} />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{t.manager}</label>
                    <SearchableSelect options={[{value:'all', label:t.allManagers}, ...projectManagers.map(m => ({value:m.id, label:m.name}))]} value={globalManagerId} onChange={setGlobalManagerId} placeholder={t.allManagers} language={language} />
                </div>
                <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{t.monthYear}</label>
                    <SearchableSelect isMulti options={monthYearOptions} value={globalMonthYear} onChange={setGlobalMonthYear} placeholder={t.allMonths} language={language} />
                </div>
                <div className="flex items-end">
                    <button onClick={() => { setGlobalProjectId('all'); setGlobalManagerId('all'); setGlobalMonthYear([]); }} className="w-full py-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-xs font-bold rounded-xl hover:bg-slate-200 transition-colors uppercase tracking-widest">
                        {t.clearFilters}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                {layout.map(widgetId => {
                    const config = WIDGETS_CONFIG.find(w => w.id === widgetId);
                    if (!config) return null;
                    const Component = config.component as any;
                    return (
                        <div key={config.id} className={`lg:col-span-${config.colSpan}`}>
                            <Component 
                                filteredProjects={filteredProjects} 
                                filteredMilestones={filteredMilestones}
                                projectsWithMilestones={projectsWithMilestones}
                                teams={teams}
                                language={language}
                                onTeamClick={(team: any, pjs: any) => setViewingTeam({ team, projects: pjs })}
                            />
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, Milestone, Lookup, Language, PaymentStatus, User } from '../types';
import SearchableSelect from './SearchableSelect';
import ProjectDetailModal from './ProjectDetailModal';

type ProjectWithMilestones = Project & { milestones: Milestone[] };

interface MilestoneFilterProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    customers: Lookup[];
    projectManagers: User[];
    language: Language;
    currentUser?: User;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const translations = {
    ar: {
        filter: "الفلترة المتقدمة", subtitle: "بحث وتصفية متقدمة لمعالم المشاريع والدفعات.", 
        projectMilestones: "معالم المشاريع", noMilestones: "لا توجد معالم.", Pending: "معلقة", Sent: "مرسلة", Paid: "مدفوعة", noDueDate: "لا يوجد تاريخ استحقاق", allProjects: "كل المشاريع", allMonths: "كل الشهور", searchProjects: "ابحث عن مشروع...", searchMonths: "ابحث عن شهر...", exportToExcel: "تصدير إلى Excel", allCustomers: "كل العملاء", searchCustomers: "ابحث عن عميل...", allManagers: "كل المدراء", searchManagers: "ابحث عن مدير...", clearFilters: "مسح الفلاتر", milestoneUnit: "معالم", allPaymentStatuses: "كل حالات الدفع", searchPaymentStatuses: "ابحث عن حالة...",
        listView: "عرض قائمة", gridView: "عرض شبكي", projectManagerHeader: "المشروع/المدير", milestoneCountHeader: "المعالم", countryHeader: "البلد", statusHeader: "الحالة", teamHeader: "الفريق", unassigned: "غير معين", noStatus: "لا توجد حالة",
        dataVisualization: "تصور البيانات", showVisualization: "إظهار التصور البياني", hideVisualization: "إخفاء التصور البياني", chartType: "نوع الرسم البياني", dimension: "البعد (المحور السيني)", measure: "المقياس (المحور الصادي)", barChart: "أعمدة", pieChart: "دائري", status: "حالة المشروع", customer: "العميل", manager: "مدير المشروع", country: "الدولة", team: "الفريق", project: "المشروع", projectCount: "عدد المشاريع", milestoneCount: "عدد المعالم", totalPayment: "إجمالي الدفعات",
        monthYear: "الشهر/السنة", lineChart: "خطي",
    },
    en: {
