// Helper to get current Month Year label based on language
const getCurrentMonthYearLabel = (lang: Language) => {
    const now = new Date();
    const month = now.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
    return `${month} ${now.getFullYear()}`;
};

// --- Widget Component Definitions ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, showPadding?: boolean, headerExtra?: React.ReactNode }> = ({ title, children, maxHeight = '400px', showPadding = true, headerExtra }) => (
    <div className={`bg-white dark:bg-gray-800/50 ${showPadding ? 'p-6' : 'pt-6'} rounded-3xl shadow-sm border border-slate-100 dark:border-slate-800 h-full flex flex-col transition-all`}>
        <div className={`flex justify-between items-center mb-6 ${showPadding ? '' : 'px-6'}`}>
            <h2 className="text-xl font-black text-slate-900 dark:text-white tracking-tight">{title}</h2>
            {headerExtra}
        </div>
        <div className="flex-grow overflow-y-auto custom-scrollbar pr-1 rtl:pl-1" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<{ filteredProjects: Project[], filteredMilestones: Milestone[], language: Language }> = ({ filteredProjects, filteredMilestones, language }) => {
    const t = translations[language];

    const stats = useMemo(() => {
        let pendingVal = 0;
        let sentVal = 0;
        let paidVal = 0;

        filteredMilestones.forEach(m => {
            if (!m.hasPayment) return;
            const amount = m.paymentAmount || 0;
            const status = m.paymentStatus || PaymentStatus.Pending;

            if (status === PaymentStatus.Pending) pendingVal += amount;
            else if (status === PaymentStatus.Sent) sentVal += amount;
            else if (status === PaymentStatus.Paid) paidVal += amount;
        });

        return {
            projectsCount: filteredProjects.length,
            pendingVal,
            sentVal,
            paidVal
        };
    }, [filteredProjects, filteredMilestones]);

    const formatVal = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title={t.totalProjects} value={stats.projectsCount.toString()} icon="projects" />
            <StatCard title={t.filteredPending} value={formatVal(stats.pendingVal)} icon="inProgress" trendColor="text-yellow-500" />
            <StatCard title={t.filteredSent} value={formatVal(stats.sentVal)} icon="completed" trendColor="text-blue-500" />
            <StatCard title={t.filteredPaid} value={formatVal(stats.paidVal)} icon="hours" trendColor="text-green-500" />
        </div>
    );
};

const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];

    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();

        filteredMilestones.forEach(m => {
            if (!m.dueDate || !m.hasPayment) return;

            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();

            if (!groups.has(labelKey)) {
                groups.set(labelKey, { totalAmount: 0, sortKey });
            }
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });

        return Array.from(groups.entries())
            .map(([monthYear, data]) => ({ monthYear, ...data }))
            .sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);

    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 50000);
    const yAxisMax = Math.ceil(maxAmount / 50000) * 50000;
    const yAxisMarks = [yAxisMax, yAxisMax * 0.66, yAxisMax * 0.33, 0];

    const formatLabelValue = (val: number) => {
        return `$${(val / 1000).toLocaleString(undefined, { minimumFractionDigits: 1, maximumFractionDigits: 1 })}K`;
    };

    const getShortMonthYear = (my: string) => {
        const [m, y] = my.split(' ');
        const monthsEn = { January: '1', February: '2', March: '3', April: '4', May: '5', June: '6', July: '7', August: '8', September: '9', October: '10', November: '11', December: '12' };
        const monthsAr = { "يناير": '1', "فبراير": '2', "مارس": '3', "أبريل": '4', "مايو": '5', "يونيو": '6', "يوليو": '7', "أغسطس": '8', "سبتمبر": '9', "أكتوبر": '10', "نوفمبر": '11', "ديسمبر": '12' };
        const monthNum = (language === 'ar' ? (monthsAr as any)[m] : (monthsEn as any)[m]) || '?';
        return `${monthNum}/${y}`;
    };

    return (
        <WidgetWrapper title={t.executionChartTitle} maxHeight="none">
            <div className="relative mt-4 mb-8 px-2 overflow-visible">
                <div className="flex h-64 relative overflow-visible">
                    <div className="w-14 flex flex-col justify-between text-[11px] font-bold text-slate-400 pb-8 pr-3 text-right">
                        {yAxisMarks.map((val, idx) => (
                            <span key={idx}>${(val / 1000).toFixed(0)}K</span>
                        ))}
                    </div>

                    <div className="flex-1 flex items-end gap-3 pb-8 relative border-l border-slate-200 dark:border-slate-800/50 overflow-visible">
                        <div className="absolute inset-0 flex flex-col justify-between pointer-events-none pb-8">
                             {[0, 1, 2, 3].map(i => (
                                <div key={i} className="w-full border-t border-slate-100 dark:border-slate-800 border-dashed"></div>
                             ))}
                        </div>

                        {graphData.map((d, i) => (
                            <div key={i} className="flex-1 min-w-[75px] flex flex-col items-center justify-end h-full group relative overflow-visible">
                                <div 
                                    style={{ height: `${Math.max(4, (d.totalAmount / yAxisMax) * 100)}%` }}
                                    className="w-full max-w-[54px] relative group/bar"
                                >
                                    <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-1 z-20 text-[12px] font-black text-slate-900 dark:text-slate-100 whitespace-nowrap transition-transform group-hover/bar:scale-110">
                                        {d.totalAmount > 0 ? formatLabelValue(d.totalAmount) : ''}
                                    </span>
                                    <div 
                                        className="w-full h-full bg-violet-600 rounded-t-[2px] shadow-sm transition-all duration-500 hover:bg-violet-500 cursor-pointer"
                                        title={`${d.monthYear}: ${formatLabelValue(d.totalAmount)}`}
                                    />
                                </div>
                                <span className="absolute top-full mt-2 text-[11px] font-bold text-slate-500 whitespace-nowrap">
                                    {getShortMonthYear(d.monthYear)}
                                </span>
                            </div>
                        ))}
                        {graphData.length === 0 && <div className="absolute inset-0 flex items-center justify-center text-slate-400 text-xs italic">{t.noData}</div>}
                    </div>
                </div>
            </div>
        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], language: Language }> = ({ projectsWithMilestones, language }) => {
    const t = translations[language];
    const [expandedPeriods, setExpandedPeriods] = useState<Record<string, boolean>>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState<'value' | 'name'>('value');

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();

        projectsWithMilestones.forEach(p => {
            // Apply Widget Search filter
            if (searchTerm && !p.name.toLowerCase().includes(searchTerm.toLowerCase()) && !p.projectManager?.name?.toLowerCase().includes(searchTerm.toLowerCase())) {
                return;
            }

            p.milestones.forEach((m: any) => {
                if (!m.dueDate) return;
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();

                if (!dateGroups.has(label)) {
                    dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                }

                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0 };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) projInGroup.groupTotal += (m.paymentAmount || 0);
            });
        });

        // Sort projects inside each period
        dateGroups.forEach(group => {
            group.projects.sort((a, b) => {
                if (sortBy === 'value') return b.groupTotal - a.groupTotal;
                return a.name.localeCompare(b.name);
            });
        });

        return Array.from(dateGroups.values()).sort((a, b) => a.sortKey - b.sortKey);
    }, [projectsWithMilestones, language, searchTerm, sortBy]);

    useEffect(() => {
        if (aggregatedByDate.length > 0 && Object.keys(expandedPeriods).length === 0) {
            setExpandedPeriods({ [aggregatedByDate[0].monthYear]: true });
        }
    }, [aggregatedByDate, expandedPeriods]);

    const formatCurrency = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    const headerControls = (
        <div className="flex items-center gap-3">
             <div className="relative">
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={e => setSearchTerm(e.target.value)} 
                    placeholder={t.searchProjects}
                    className="pl-8 pr-4 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-full text-[10px] border-none focus:ring-1 focus:ring-violet-500 w-32 md:w-40 transition-all"
                />
                <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
            <button 
                onClick={() => setSortBy(prev => prev === 'value' ? 'name' : 'value')}
                className="p-1.5 bg-slate-100 dark:bg-slate-800 rounded-lg text-slate-500 hover:text-violet-600 transition-colors"
                title={sortBy === 'value' ? t.sortByValue : t.sortByName}
            >
                {sortBy === 'value' ? (
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4h13M3 8h9m-9 4h6m4 0l4-4m0 0l4 4m-4-4v12" /></svg>
                ) : (
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4h13M3 8h9m-9 4h9m5-1v12m0 0l-4-4m4 4l4-4" /></svg>
                )}
            </button>
        </div>
    );

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="550px" headerExtra={headerControls}>
            <div className="space-y-6 pb-4">
                {aggregatedByDate.length > 0 ? aggregatedByDate.map((period, pIdx) => {
                    const isOpen = !!expandedPeriods[period.monthYear];
                    const periodTotal = period.projects.reduce((s, p) => s + p.groupTotal, 0);

                    return (
                        <div key={pIdx} className="group/period">
                            <button 
                                onClick={() => setExpandedPeriods(prev => ({ ...prev, [period.monthYear]: !isOpen }))}
                                className={`w-full flex items-center justify-between mb-4 p-4 rounded-2xl transition-all ${isOpen ? 'bg-violet-600 text-white shadow-lg shadow-violet-500/20 scale-[1.01]' : 'bg-slate-50 dark:bg-slate-900/40 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                            >
                                <div className="flex items-center gap-4">
                                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-colors ${isOpen ? 'bg-white/20' : 'bg-violet-100 dark:bg-violet-900/30'}`}>
                                        <svg className={`w-5 h-5 transition-transform duration-300 ${isOpen ? 'text-white' : 'text-violet-600 dark:text-violet-400'} ${isOpen ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
                                    </div>
                                    <div className="text-start">
                                        <h3 className="text-sm font-black uppercase tracking-wider">{period.monthYear}</h3>
                                        <p className={`text-[10px] font-bold ${isOpen ? 'text-white/70' : 'text-slate-400'}`}>{period.projects.length} {t.projectsCountLabel}</p>
                                    </div>
                                </div>
                                <div className="text-end">
                                    <p className="text-xs font-black">{formatCurrency(periodTotal)}</p>
                                    <p className={`text-[10px] font-bold uppercase ${isOpen ? 'text-white/70' : 'text-slate-400'}`}>{t.periodTotal}</p>
                                </div>
                            </button>

                            {isOpen && (
                                <div className="space-y-4 px-2 animate-in fade-in slide-in-from-top-2 duration-300">
                                    {period.projects.map((proj, prIdx) => (
                                        <div key={prIdx} className="bg-white dark:bg-slate-900/60 rounded-2xl border border-slate-100 dark:border-slate-800 overflow-hidden shadow-sm hover:border-violet-300 dark:hover:border-violet-700 transition-colors">
                                            <div className="p-4 flex items-center justify-between gap-4">
                                                <div className="flex items-center gap-3 min-w-0">
                                                    <img 
                                                        src={proj.projectManager?.avatarUrl || `https://ui-avatars.com/api/?name=${proj.projectManager?.name || '?'}&background=c4b5fd&color=2e1065`} 
                                                        className="w-10 h-10 rounded-full border-2 border-slate-100 dark:border-slate-800 shrink-0"
                                                        alt={proj.projectManager?.name}
                                                    />
                                                    <div className="min-w-0">
                                                        <h4 className="text-[13px] font-black text-slate-800 dark:text-white truncate">{proj.name}</h4>
                                                        <p className="text-[10px] font-bold text-slate-400 truncate">{proj.projectManager?.name || t.unassigned}</p>
                                                    </div>
                                                </div>
                                                <div className="text-end shrink-0">
                                                    <p className="text-xs font-black text-violet-600 dark:text-violet-400">{formatCurrency(proj.groupTotal)}</p>
                                                    <div className="flex items-center justify-end gap-1 mt-0.5">
                                                        <div className="w-16 h-1 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                                                            <div className="h-full bg-violet-500" style={{ width: `${proj.progress}%` }}></div>
                                                        </div>
                                                        <span className="text-[9px] font-bold text-slate-400">{proj.progress}%</span>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="bg-slate-50/50 dark:bg-black/20 px-4 py-3 divide-y divide-slate-100 dark:divide-slate-800">
                                                {proj.milestonesInGroup.map((m: any, mIdx: number) => (
                                                    <div key={mIdx} className="py-2 flex justify-between items-center group/item hover:translate-x-1 transition-transform">
                                                        <div className="flex items-center gap-2 min-w-0">
                                                            <div className={`w-1.5 h-1.5 rounded-full ${m.paymentStatus === 'Paid' ? 'bg-green-500' : m.paymentStatus === 'Sent' ? 'bg-blue-500' : 'bg-yellow-500'}`}></div>
                                                            <span className="text-[11px] font-bold text-slate-600 dark:text-slate-400 truncate">{m.title}</span>
                                                        </div>
                                                        <div className="flex items-center gap-3">
                                                            <span className="text-[10px] font-black text-slate-800 dark:text-slate-200">{formatCurrency(m.paymentAmount)}</span>
                                                            <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded-full ${m.paymentStatus === 'Paid' ? 'bg-green-100 text-green-700 dark:bg-green-900/30' : m.paymentStatus === 'Sent' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30' : 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30'}`}>
                                                                {t[m.paymentStatus || 'Pending']}
                                                            </span>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                }) : (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-300 dark:text-slate-600">
                        <svg className="w-12 h-12 mb-4 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                        <p className="text-sm font-bold">{t.noData}</p>
                    </div>
                )}
            </div>
        </WidgetWrapper>
    );
};

const PaymentBreakdownChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];
    const statusCounts = useMemo(() => {
        const counts = { [PaymentStatus.Paid]: 0, [PaymentStatus.Sent]: 0, [PaymentStatus.Pending]: 0 };
        filteredMilestones.forEach(m => {
            if (m.hasPayment) {
                const s = m.paymentStatus || PaymentStatus.Pending;
                (counts as any)[s]++;
            }
        });
        return Object.entries(counts);
    }, [filteredMilestones]);

    const maxCount = Math.max(...statusCounts.map(([, c]) => c), 1);
    const colorMap: any = { [PaymentStatus.Paid]: 'bg-green-500', [PaymentStatus.Sent]: 'bg-blue-500', [PaymentStatus.Pending]: 'bg-yellow-500' };

    return (
        <WidgetWrapper title={t.paymentBreakdown} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {statusCounts.map(([status, count]) => (
                    <div key={status} className="flex items-center gap-4">
                        <span className="w-1/3 text-sm text-gray-600 dark:text-gray-300 truncate">{t[status as any]}</span>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 overflow-hidden">
                                <div className={`${colorMap[status]} h-4 transition-all duration-500`} style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm">{count}</span>
                        </div>
                    </div>
                ))}
            </div>
        </WidgetWrapper>
    );
};

const TeamWorkloadChartWidget: React.FC<{ filteredProjects: Project[], teams: Lookup[], language: Language, onTeamClick: any }> = ({ filteredProjects, teams, language, onTeamClick }) => {
    const t = translations[language];
    const teamStats = useMemo(() => {
        return teams.map(tm => {
            const pjs = filteredProjects.filter(p => p.teamId === tm.id);
            return { team: tm, count: pjs.length, projects: pjs };
        }).filter(s => s.count > 0).sort((a,b) => b.count - a.count);
    }, [filteredProjects, teams]);

    const max = Math.max(...teamStats.map(s => s.count), 1);

    return (
         <WidgetWrapper title={t.teamWorkload} maxHeight="auto">
             <div className="space-y-3 pt-2">
                {teamStats.map(s => (
                    <div key={s.team.id} className="flex items-center gap-4 cursor-pointer group" onClick={() => onTeamClick(s.team, s.projects)}>
                        <span className="w-1/3 text-sm text-gray-600 dark:text-gray-300 truncate group-hover:text-violet-600 font-medium">{s.team.name}</span>
                        <div className="w-2/3 flex items-center gap-2">
                            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 overflow-hidden">
                                <div className="bg-violet-500 h-4 transition-all duration-500 group-hover:bg-violet-400" style={{ width: `${s.count / max * 100}%` }}></div>
                            </div>
                            <span className="font-bold text-gray-800 dark:text-white text-sm">{s.count}</span>
                        </div>
                    </div>
                ))}
            </div>
        </WidgetWrapper>
    );
};

