export const WIDGETS_CONFIG = [
    { id: 'stats', name: 'Financial Overview', component: StatsOverviewWidget, default: true, colSpan: 4 },
    { id: 'execution_chart', name: 'Monthly Chart', component: ExecutionPerformanceChartWidget, default: true, colSpan: 4 },
