}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, teams, projectManagers, language }) => {
    const t = translations[language];
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [globalMonthYear, setGlobalMonthYear] = useState<string[]>(() => [getCurrentMonthYearLabel(language)]);
    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });
    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [viewingProject, setViewingProject] = useState<any>(null);
    const [viewingTeam, setViewingTeam] = useState<any>(null);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                unique.set(label, { label, sortKey });
            }
        });
        const currentLabel = getCurrentMonthYearLabel(language);
        if (!unique.has(currentLabel)) {
            const now = new Date();
            unique.set(currentLabel, { label: currentLabel, sortKey: now.getFullYear() * 100 + now.getMonth() });
        }
        return Array.from(unique.values()).sort((a, b) => a.sortKey - b.sortKey).map(v => ({ value: v.label, label: v.label }));
    }, [milestones, language]);

    const { filteredProjects, filteredMilestones } = useMemo(() => {
        const fps = projects.filter(p => (globalProjectId === 'all' || p.id === globalProjectId) && (globalManagerId === 'all' || p.projectManagerId === globalManagerId));
        const projectIds = new Set(fps.map(p => p.id));
        const fms = milestones.filter(m => {
            if (!projectIds.has(m.projectId)) return false;
            if (globalMonthYear.length > 0) {
                if (!m.dueDate) return false;
                const d = new Date(m.dueDate);
                const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`;
                if (!globalMonthYear.includes(label)) return false;
            }
            return true;
        });
        return { filteredProjects: fps, filteredMilestones: fms };
    }, [projects, milestones, globalProjectId, globalManagerId, globalMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map(p => ({ ...p, milestones: filteredMilestones.filter(m => m.projectId === p.id) })).filter(p => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    return (
        <div className="space-y-12">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}
            {viewingProject && <ProjectDetailModal projectWithMilestones={viewingProject} onClose={() => setViewingProject(null)} language={language} />}
            {viewingTeam && <TeamProjectsModal team={viewingTeam.team} projects={viewingTeam.projects} onClose={() => setViewingTeam(null)} language={language} onViewProject={(p) => { setViewingTeam(null); setViewingProject({ ...p, milestones: milestones.filter(m => m.projectId === p.id) }); }} />}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div className="relative">
                    <h1 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{t.dashboard}</h1>
                    <p className="text-slate-500 font-bold mt-1.5 flex items-center gap-2">
                        <span className="w-1.5 h-1.5 rounded-full bg-violet-500 animate-pulse"></span>
                        {t.overview}
                    </p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-white dark:bg-slate-800 hover:scale-105 active:scale-95 px-6 py-3 rounded-2xl flex items-center gap-3 transition-all shadow-lg shadow-slate-200/50 dark:shadow-none font-black text-xs uppercase tracking-widest text-slate-700 dark:text-slate-300 border border-slate-100 dark:border-slate-700">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-violet-500" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 003.464V16a1 1 0 102 0V8.732a2 2 0 00-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" /></svg>
                    {t.customize}
                </button>
            </div>

            <div className="bg-white/50 dark:bg-slate-900/30 backdrop-blur-md p-6 rounded-[2.5rem] border border-white dark:border-slate-800 shadow-sm grid grid-cols-1 md:grid-cols-4 gap-6">
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">{t.project}</label>
                    <SearchableSelect options={[{value:'all', label:t.allProjects}, ...projects.map(p => ({value:p.id, label:p.name}))]} value={globalProjectId} onChange={setGlobalProjectId} placeholder={t.allProjects} language={language} />
                </div>
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">{t.manager}</label>
                    <SearchableSelect options={[{value:'all', label:t.allManagers}, ...projectManagers.map(m => ({value:m.id, label:m.name}))]} value={globalManagerId} onChange={setGlobalManagerId} placeholder={t.allManagers} language={language} />
                </div>
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">{t.monthYear}</label>
                    <SearchableSelect isMulti options={monthYearOptions} value={globalMonthYear} onChange={setGlobalMonthYear} placeholder={t.allMonths} language={language} />
                </div>
                <div className="flex items-end">
                    <button onClick={() => { setGlobalProjectId('all'); setGlobalManagerId('all'); setGlobalMonthYear([getCurrentMonthYearLabel(language)]); }} className="w-full py-3 bg-slate-900 dark:bg-slate-700 text-white text-[10px] font-black rounded-2xl hover:bg-black transition-all uppercase tracking-widest shadow-lg shadow-slate-900/20">
                        {t.clearFilters}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 pb-10">
                {layout.map(widgetId => {
                    const config = WIDGETS_CONFIG.find(w => w.id === widgetId);
                    if (!config) return null;
                    const Component = config.component as any;
                    return (
                        <div key={config.id} className={`lg:col-span-${config.colSpan}`}>
                            <Component 
                                filteredProjects={filteredProjects} 
                                filteredMilestones={filteredMilestones}
                                projectsWithMilestones={projectsWithMilestones}
                                teams={teams}
                                language={language}
                                onTeamClick={(team: any, pjs: any) => setViewingTeam({ team, projects: pjs })}
                            />
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

