    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [isChatbotOpen, setIsChatbotOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);

    // Data State
    const [projects, setProjects] = useState<Project[]>([]);
    const [milestones, setMilestones] = useState<Milestone[]>([]);
    const [milestoneUpdates, setMilestoneUpdates] = useState<MilestoneUpdate[]>([]);
    const [maintenanceContracts, setMaintenanceContracts] = useState<MaintenanceContract[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [lookups, setLookups] = useState<Lookups>({
        countries: [], categories: [], teams: [], products: [], projectStatuses: [], projectManagers: [], customers: []
    });

    // Auth & DB State
    const [session, setSession] = useState<Session | null>(null);
    const [supabaseClient, setSupabaseClient] = useState<SupabaseClient | null>(null);
    const [isAppConfigured, setIsAppConfigured] = useState(false);
    const [isDbConnected, setIsDbConnected] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        localStorage.setItem('lastView', view);
    }, [view]);

    useEffect(() => {
        localStorage.setItem('theme', theme);
        if (theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    }, [theme]);

    useEffect(() => {
        localStorage.setItem('language', language);
    }, [language]);

    useEffect(() => {
        const key = localStorage.getItem('supabaseAnonKey');
        if (key && key.trim()) {
            try {
                const client = initSupabase('https://dcamlinhazzmbaldsrdo.supabase.co', key);
                setSupabaseClient(client);
                setIsAppConfigured(true);
            } catch (error) {
                console.error("Supabase auto-initialization failed:", error);
                localStorage.removeItem('supabaseAnonKey');
                setIsAppConfigured(false);
                setIsLoading(false);
            }
        } else {
            setIsAppConfigured(false);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        if (supabaseClient) {
            supabaseClient.auth.getSession().then(({ data: { session } }) => {
                setSession(session);
                if (session) setIsDbConnected(true);
                setIsLoading(false);
            });

            const { data: { subscription } } = supabaseClient.auth.onAuthStateChange((_event, session) => {
                setSession(session);
                setIsDbConnected(!!session);
            });

            return () => subscription.unsubscribe();
        }
    }, [supabaseClient]);

    const loadDataFromDb = useCallback(async () => {
        if (!isDbConnected) return;
        try {
            setIsLoading(true);
            const data = await fetchAllData();
            setProjects(data.projects);
            setMilestones(data.milestones);
            setUsers(data.users);
            setLookups(data.lookups);
            setMilestoneUpdates(data.milestoneUpdates);
            setMaintenanceContracts(data.maintenanceContracts);
        } catch (error) {
            console.error("Failed to load data from database:", error);
            setIsDbConnected(false);
        } finally {
            setIsLoading(false);
        }
    }, [isDbConnected]);

    useEffect(() => {
        if (isDbConnected) {
            loadDataFromDb();
        }
    }, [isDbConnected, loadDataFromDb]);

    const handleLogout = async () => {
        if (supabaseClient) await supabaseClient.auth.signOut();
    };

    if (isLoading) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center">
                <div className="w-12 h-12 border-4 border-violet-600 border-t-transparent rounded-full animate-spin"></div>
            </div>
        );
    }

    if (!isAppConfigured) {
        return <SystemManagement lookups={lookups} onUpdate={() => {}} language={language} onSaveConfig={(key) => {
            localStorage.setItem('supabaseAnonKey', key);
            window.location.reload();
        }} isSetupMode={true} />;
    }

    if (!session) {
        return <Login onLoginSuccess={() => setIsDbConnected(true)} language={language} setLanguage={setLanguage} supabaseClient={supabaseClient!} />;
    }

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <Sidebar currentView={view} setCurrentView={setView} language={language} />
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                <Header user={users.find(u => u.id === session.user.id)} language={language} setLanguage={setLanguage} onSearch={() => {}} onLogout={handleLogout} theme={theme} setTheme={setTheme} isDbConnected={isDbConnected} />
                <main className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                    {view === 'dashboard' && <AnalyticsDashboard projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={async () => {}} />}
                    {view === 'projects' && (
                        <Projects 
                            allProjects={projects} 
                            allUsers={users} 
                            language={language} 
                            onAddProject={async () => {}} 
                            onOpenEditModal={setEditingProject} 
                            onOpenDeleteModal={setDeletingProject} 
                            lookups={lookups} 
                            isImportModalOpen={isImportModalOpen} 
                            onOpenImportModal={() => setIsImportModalOpen(true)} 
                            onCloseImportModal={() => setIsImportModalOpen(false)} 
                            onImportProjects={async () => {}} 
                        />
                    )}
                    {view === 'milestones' && <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={async () => {}} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={async () => {}} lookups={lookups} />}
                    {view === 'team' && <Team allUsers={users} allProjects={projects} language={language} />}
                    {view === 'payments' && <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={async () => {}} />}
                    {view === 'maintenanceContracts' && <MaintenanceContracts contracts={maintenanceContracts} customers={lookups.customers} language={language} onAddContract={async () => {}} onUpdateContract={async () => {}} />}
                    {view === 'system' && <SystemManagement lookups={lookups} onUpdate={apiUpdateLookups} language={language} onSaveConfig={() => {}} />}
                    {view === 'filter' && <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={async () => {}} />}
                </main>
            </div>

            {editingProject && <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={async () => {}} language={language} />}
            {editingMilestone && <EditMilestoneModal milestoneToEdit={editingMilestone} allMilestones={milestones} teams={lookups.teams} projects={projects} allMilestoneUpdates={milestoneUpdates} allUsers={users} currentUser={users.find(u => u.id === session.user.id)} onClose={() => setEditingMilestone(null)} onUpdateMilestone={async () => {}} onAddMilestones={async () => {}} onAddUpdate={async () => {}} language={language} />}
            {viewingMilestone && <MilestoneDetailModal milestone={viewingMilestone} projects={projects} allMilestoneUpdates={milestoneUpdates} allUsers={users} lookups={lookups} onClose={() => setViewingMilestone(null)} language={language} />}
            {deletingProject && <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={async () => {}} language={language} />}

            <button onClick={() => setIsChatbotOpen(true)} className="fixed bottom-8 right-8 rtl:right-auto rtl:left-8 bg-gradient-to-r from-violet-600 to-indigo-600 p-4 rounded-full shadow-2xl hover:scale-110 active:scale-95 transition-all z-50 group">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /><path d="M15 7v2a4 4 0 01-4 4H9.828l-1.766 1.767c.28.149.599.233.938.233h2l3 3v-3h2a2 2 0 002-2V9a2 2 0 00-2-2h-1z" /></svg>
