import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, Milestone, Lookup, MilestoneStatus, Language, PaymentStatus, User } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';
import ProjectDetailModal from './ProjectDetailModal';
import TeamProjectsModal from './TeamProjectsModal';

// Helper to get current Month Year label
const getCurrentMonthYearLabel = (lang: Language) => {
    const now = new Date();
    const month = now.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
    return `${month} ${now.getFullYear()}`;
};

// --- Widget Component Definitions ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, showPadding?: boolean, headerExtra?: React.ReactNode }> = ({ title, children, maxHeight = '400px', showPadding = true, headerExtra }) => (
    <div className={`bg-white/80 dark:bg-slate-900/40 backdrop-blur-xl rounded-[2.5rem] shadow-xl shadow-slate-200/40 dark:shadow-none border border-white dark:border-slate-800 h-full flex flex-col transition-all overflow-hidden`}>
        <div className={`flex justify-between items-center py-6 px-8 border-b border-slate-100 dark:border-slate-800/50 flex-wrap gap-4`}>
            <h2 className="text-xl font-black text-slate-900 dark:text-white tracking-tight">{title}</h2>
            {headerExtra}
        </div>
        <div className="flex-grow overflow-y-auto custom-scrollbar px-6 py-4" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<{ filteredProjects: Project[], filteredMilestones: Milestone[], language: Language }> = ({ filteredProjects, filteredMilestones, language }) => {
    const t = translations[language];
    const stats = useMemo(() => {
        let pendingVal = 0; let sentVal = 0; let paidVal = 0;
        filteredMilestones.forEach(m => {
            if (!m.hasPayment) return;
            const amount = m.paymentAmount || 0;
            const status = m.paymentStatus || PaymentStatus.Pending;
            if (status === PaymentStatus.Pending) pendingVal += amount;
            else if (status === PaymentStatus.Sent) sentVal += amount;
            else if (status === PaymentStatus.Paid) paidVal += amount;
        });
        return { projectsCount: filteredProjects.length, pendingVal, sentVal, paidVal };
    }, [filteredProjects, filteredMilestones]);
    const formatVal = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title={t.totalProjects} value={stats.projectsCount.toString()} icon="projects" />
            <StatCard title={t.filteredPending} value={formatVal(stats.pendingVal)} icon="inProgress" trendColor="text-orange-500" />
            <StatCard title={t.filteredSent} value={formatVal(stats.sentVal)} icon="completed" trendColor="text-blue-500" />
            <StatCard title={t.filteredPaid} value={formatVal(stats.paidVal)} icon="hours" trendColor="text-emerald-500" />
        </div>
    );
};

const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];
    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();
        filteredMilestones.forEach(m => {
            if (!m.dueDate || !m.hasPayment) return;
            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();
            if (!groups.has(labelKey)) groups.set(labelKey, { totalAmount: 0, sortKey });
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });
        return Array.from(groups.entries()).map(([monthYear, data]) => ({ monthYear, ...data })).sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);
    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 50000);
    const yAxisMax = Math.ceil(maxAmount / 50000) * 50000;
    return (
        <WidgetWrapper title={t.executionChartTitle} maxHeight="none">
            {/* Added overflow-x-auto and min-w to handle chart scrolling without breaking dashboard width */}
            <div className="overflow-x-auto custom-scrollbar">
                <div className="flex h-64 items-end gap-3 pb-8 relative mt-4 min-w-[500px]">
                    {graphData.map((d, i) => (
                        <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                            <div style={{ height: `${Math.max(5, (d.totalAmount / yAxisMax) * 100)}%` }} className="w-full max-w-[40px] bg-violet-600/80 rounded-t-xl group-hover:bg-violet-600 transition-all relative">
                                <span className="absolute -top-6 left-1/2 -translate-x-1/2 text-[10px] font-black text-slate-900 dark:text-white whitespace-nowrap">${(d.totalAmount / 1000).toFixed(0)}K</span>
                            </div>
                            <span className="absolute -bottom-6 text-[10px] font-bold text-slate-400 uppercase tracking-tighter text-center leading-none px-1 h-4 overflow-hidden">{d.monthYear.split(' ')[0]}</span>
                        </div>
                    ))}
                    {graphData.length === 0 && <div className="absolute inset-0 flex items-center justify-center text-slate-400 font-bold">{t.noData}</div>}
                </div>
            </div>
        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], language: Language }> = ({ projectsWithMilestones, language }) => {
    const t = translations[language];
    const [expandedPeriods, setExpandedPeriods] = useState<Record<string, boolean>>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState<'value' | 'name'>('value');

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();
        projectsWithMilestones.forEach(p => {
            if (searchTerm && !p.name.toLowerCase().includes(searchTerm.toLowerCase()) && !p.projectManager?.name?.toLowerCase().includes(searchTerm.toLowerCase())) return;
            p.milestones.forEach((m: any) => {
                if (!m.dueDate) return;
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!dateGroups.has(label)) dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0, statusCounts: { Paid: 0, Sent: 0, Pending: 0 } };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) {
                    projInGroup.groupTotal += (m.paymentAmount || 0);
                    projInGroup.statusCounts[m.paymentStatus || 'Pending']++;
                }
            });
        });
        dateGroups.forEach(group => {
            group.projects.sort((a, b) => sortBy === 'value' ? b.groupTotal - a.groupTotal : a.name.localeCompare(b.name));
        });
        return Array.from(dateGroups.values()).sort((a, b) => a.sortKey - b.sortKey);
    }, [projectsWithMilestones, language, searchTerm, sortBy]);

    useEffect(() => {
        const currentLabel = getCurrentMonthYearLabel(language);
        if (aggregatedByDate.some(g => g.monthYear === currentLabel)) {
            setExpandedPeriods(prev => ({ ...prev, [currentLabel]: true }));
        } else if (aggregatedByDate.length > 0 && Object.keys(expandedPeriods).length === 0) {
            setExpandedPeriods({ [aggregatedByDate[0].monthYear]: true });
        }
    }, [aggregatedByDate, language]);

    const formatCurrency = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

