                        <p className="text-sm font-black uppercase tracking-widest">{t.noData}</p>
                    </div>
                )}
            </div>
        </WidgetWrapper>
    );
};

// Simplified and styled breakdowns
const PaymentBreakdownChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];
    const statusCounts = useMemo(() => {
        const counts = { [PaymentStatus.Paid]: 0, [PaymentStatus.Sent]: 0, [PaymentStatus.Pending]: 0 };
        filteredMilestones.forEach(m => { if (m.hasPayment) (counts as any)[m.paymentStatus || PaymentStatus.Pending]++; });
        return Object.entries(counts);
    }, [filteredMilestones]);
    const maxCount = Math.max(...statusCounts.map(([, c]) => c), 1);
    const colorMap: any = { [PaymentStatus.Paid]: 'bg-emerald-500', [PaymentStatus.Sent]: 'bg-blue-500', [PaymentStatus.Pending]: 'bg-orange-500' };
    return (
        <WidgetWrapper title={t.paymentBreakdown} maxHeight="auto">
             <div className="space-y-4 pt-2">
                {statusCounts.map(([status, count]) => (
                    <div key={status} className="flex items-center gap-4">
                        <span className="w-24 text-[10px] font-black text-slate-500 uppercase truncate">{t[status as any]}</span>
                        <div className="flex-1 flex items-center gap-3">
                            <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-full h-2.5 overflow-hidden">
                                <div className={`${colorMap[status]} h-full transition-all duration-700`} style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-black text-slate-900 dark:text-white text-xs">{count}</span>
                        </div>
                    </div>
                ))}
            </div>
        </WidgetWrapper>
    );
};

const TeamWorkloadChartWidget: React.FC<{ filteredProjects: Project[], teams: Lookup[], language: Language, onTeamClick: any }> = ({ filteredProjects, teams, language, onTeamClick }) => {
    const t = translations[language];
    const teamStats = useMemo(() => {
        return teams.map(tm => {
            const pjs = filteredProjects.filter(p => p.teamId === tm.id);
            return { team: tm, count: pjs.length, projects: pjs };
        }).filter(s => s.count > 0).sort((a,b) => b.count - a.count);
    }, [filteredProjects, teams]);
    const max = Math.max(...teamStats.map(s => s.count), 1);
    return (
         <WidgetWrapper title={t.teamWorkload} maxHeight="auto">
             <div className="space-y-4 pt-2">
                {teamStats.map(s => (
                    <div key={s.team.id} className="flex items-center gap-4 cursor-pointer group" onClick={() => onTeamClick(s.team, s.projects)}>
                        <span className="w-24 text-[10px] font-black text-slate-500 uppercase truncate group-hover:text-violet-600 transition-colors">{s.team.name}</span>
                        <div className="flex-1 flex items-center gap-3">
                            <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-full h-2.5 overflow-hidden">
                                <div className="bg-violet-500 h-full transition-all duration-700 group-hover:bg-violet-400" style={{ width: `${s.count / max * 100}%` }}></div>
                            </div>
                            <span className="font-black text-slate-900 dark:text-white text-xs">{s.count}</span>
                        </div>
                    </div>
                ))}
            </div>
        </WidgetWrapper>
    );
};

