interface AnalyticsDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    customers: Lookup[];
    projectManagers: User[];
    language: Language;
    currentUser?: User;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, teams, projectManagers, language }) => {
    const t = translations[language];
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [globalMonthYear, setGlobalMonthYear] = useState<string[]>(() => [getCurrentMonthYearLabel(language)]);
    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });
    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [viewingProject, setViewingProject] = useState<any>(null);
    const [viewingTeam, setViewingTeam] = useState<any>(null);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                unique.set(label, { label, sortKey });
            }
        });
        const currentLabel = getCurrentMonthYearLabel(language);
        if (!unique.has(currentLabel)) {
            const now = new Date();
            unique.set(currentLabel, { label: currentLabel, sortKey: now.getFullYear() * 100 + now.getMonth() });
        }
        return Array.from(unique.values()).sort((a, b) => a.sortKey - b.sortKey).map(v => ({ value: v.label, label: v.label }));
    }, [milestones, language]);

    const { filteredProjects, filteredMilestones } = useMemo(() => {
        const fps = projects.filter(p => (globalProjectId === 'all' || p.id === globalProjectId) && (globalManagerId === 'all' || p.projectManagerId === globalManagerId));
        const projectIds = new Set(fps.map(p => p.id));
        const fms = milestones.filter(m => {
            if (!projectIds.has(m.projectId)) return false;
            if (globalMonthYear.length > 0) {
                if (!m.dueDate) return false;
                const d = new Date(m.dueDate);
                const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`;
                if (!globalMonthYear.includes(label)) return false;
            }
            return true;
        });
        return { filteredProjects: fps, filteredMilestones: fms };
    }, [projects, milestones, globalProjectId, globalManagerId, globalMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map(p => ({ ...p, milestones: filteredMilestones.filter(m => m.projectId === p.id) })).filter(p => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    return (
        <div className="space-y-12">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}
            {viewingProject && <ProjectDetailModal projectWithMilestones={viewingProject} onClose={() => setViewingProject(null)} language={language} />}
            {viewingTeam && <TeamProjectsModal team={viewingTeam.team} projects={viewingTeam.projects} onClose={() => setViewingTeam(null)} language={language} onViewProject={(p) => { setViewingTeam(null); setViewingProject({ ...p, milestones: milestones.filter(m => m.projectId === p.id) }); }} />}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div className="relative">
                    <h1 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{t.dashboard}</h1>
                    <p className="text-slate-500 font-bold mt-1.5 flex items-center gap-2">
                        <span className="w-1.5 h-1.5 rounded-full bg-violet-500 animate-pulse"></span>
                        {t.overview}
                    </p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-white dark:bg-slate-800 hover:scale-105 active:scale-95 px-6 py-3 rounded-2xl flex items-center gap-3 transition-all shadow-lg font-black text-xs uppercase tracking-widest text-slate-700 dark:text-slate-300 border border-slate-100 dark:border-slate-700">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-violet-500" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 003.464V16a1 1 0 102 0V8.732a2 2 0 00-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" /></svg>
                    {t.customize}
                </button>
            </div>

            <div className="bg-white/50 dark:bg-slate-900/30 backdrop-blur-md p-6 rounded-[2.5rem] border border-white dark:border-slate-800 shadow-sm grid grid-cols-1 md:grid-cols-4 gap-6">
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">{t.project}</label>
                    <SearchableSelect options={[{value:'all', label:t.allProjects}, ...projects.map(p => ({value:p.id, label:p.name}))]} value={globalProjectId} onChange={setGlobalProjectId} placeholder={t.allProjects} language={language} />
                </div>
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">{t.manager}</label>
                    <SearchableSelect options={[{value:'all', label:t.allManagers}, ...projectManagers.map(m => ({value:m.id, label:m.name}))]} value={globalManagerId} onChange={setGlobalManagerId} placeholder={t.allManagers} language={language} />
                </div>
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">{t.monthYear}</label>
                    <SearchableSelect isMulti options={monthYearOptions} value={globalMonthYear} onChange={setGlobalMonthYear} placeholder={t.allMonths} language={language} />
                </div>
                <div className="flex items-end">
                    <button onClick={() => { setGlobalProjectId('all'); setGlobalManagerId('all'); setGlobalMonthYear([getCurrentMonthYearLabel(language)]); }} className="w-full py-3 bg-slate-900 dark:bg-slate-700 text-white text-[10px] font-black rounded-2xl hover:bg-black transition-all uppercase tracking-widest shadow-lg shadow-slate-900/20">
                        {t.clearFilters}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 pb-10">
                {layout.map(widgetId => {
                    const config = WIDGETS_CONFIG.find(w => w.id === widgetId);
                    if (!config) return null;
                    const Component = config.component as any;
                    return (
                        <div key={config.id} className={`lg:col-span-${config.colSpan}`}>
                            <Component 
                                filteredProjects={filteredProjects} 
                                filteredMilestones={filteredMilestones}
                                projectsWithMilestones={projectsWithMilestones}
                                teams={teams}
                                language={language}
                                onTeamClick={(team: any, pjs: any) => setViewingTeam({ team, projects: pjs })}
                            />
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, Milestone, Lookup, MilestoneStatus, Language, PaymentStatus, User } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';
import ProjectDetailModal from './ProjectDetailModal';
import TeamProjectsModal from './TeamProjectsModal';

// Helper to get current Month Year label
const getCurrentMonthYearLabel = (lang: Language) => {
    const now = new Date();
    const month = now.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
    return `${month} ${now.getFullYear()}`;
};

// --- Widget Component Definitions ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, showPadding?: boolean, headerExtra?: React.ReactNode }> = ({ title, children, maxHeight = '400px', showPadding = true, headerExtra }) => (
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2rem] shadow-sm flex flex-col transition-all overflow-hidden h-full">
        <div className="flex justify-between items-center py-5 px-8 border-b border-slate-100 dark:border-slate-800/50 flex-wrap gap-4 bg-slate-50/50 dark:bg-transparent">
            <h2 className="text-lg font-black text-slate-800 dark:text-white tracking-tight">{title}</h2>
            {headerExtra}
        </div>
        <div className="flex-grow overflow-y-auto custom-scrollbar px-6 py-5" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<{ filteredProjects: Project[], filteredMilestones: Milestone[], language: Language }> = ({ filteredProjects, filteredMilestones, language }) => {
    const t = translations[language];
    const stats = useMemo(() => {
        let pendingVal = 0; let sentVal = 0; let paidVal = 0;
        filteredMilestones.forEach(m => {
            if (!m.hasPayment) return;
            const amount = m.paymentAmount || 0;
            const status = m.paymentStatus || PaymentStatus.Pending;
            if (status === PaymentStatus.Pending) pendingVal += amount;
            else if (status === PaymentStatus.Sent) sentVal += amount;
            else if (status === PaymentStatus.Paid) paidVal += amount;
        });
        return { projectsCount: filteredProjects.length, pendingVal, sentVal, paidVal };
    }, [filteredProjects, filteredMilestones]);
    const formatVal = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <StatCard title={t.totalProjects} value={stats.projectsCount.toString()} icon="projects" />
            <StatCard title={t.filteredPending} value={formatVal(stats.pendingVal)} icon="inProgress" trendColor="text-orange-600" />
            <StatCard title={t.filteredSent} value={formatVal(stats.sentVal)} icon="completed" trendColor="text-blue-600" />
            <StatCard title={t.filteredPaid} value={formatVal(stats.paidVal)} icon="hours" trendColor="text-emerald-600" />
        </div>
    );
};

const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];
    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();
        filteredMilestones.forEach(m => {
            if (!m.dueDate || !m.hasPayment) return;
            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();
            if (!groups.has(labelKey)) groups.set(labelKey, { totalAmount: 0, sortKey });
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });
        return Array.from(groups.entries()).map(([monthYear, data]) => ({ monthYear, ...data })).sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);
    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 50000);
    const yAxisMax = Math.ceil(maxAmount / 50000) * 50000;
    return (
        <WidgetWrapper title={t.executionChartTitle} maxHeight="none">
            <div className="overflow-x-auto no-scrollbar">
                <div className="flex h-56 items-end gap-2 pb-8 relative mt-4 min-w-[400px]">
                    {graphData.map((d, i) => (
                        <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                            <div style={{ height: `${Math.max(10, (d.totalAmount / yAxisMax) * 100)}%` }} className="w-full max-w-[32px] bg-violet-500 rounded-t-lg group-hover:bg-violet-600 transition-all relative">
                                <span className="absolute -top-6 left-1/2 -translate-x-1/2 text-[9px] font-black text-slate-800 dark:text-white whitespace-nowrap">${(d.totalAmount / 1000).toFixed(0)}K</span>
                            </div>
                            <span className="absolute -bottom-6 text-[9px] font-bold text-slate-400 uppercase tracking-tighter text-center w-full truncate">{d.monthYear.split(' ')[0]}</span>
                        </div>
                    ))}
                    {graphData.length === 0 && <div className="absolute inset-0 flex items-center justify-center text-slate-400 text-sm font-bold">{t.noData}</div>}
                </div>
            </div>
        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], language: Language }> = ({ projectsWithMilestones, language }) => {
    const t = translations[language];
    const [expandedPeriods, setExpandedPeriods] = useState<Record<string, boolean>>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState<'value' | 'name'>('value');

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();
        projectsWithMilestones.forEach(p => {
            if (searchTerm && !p.name.toLowerCase().includes(searchTerm.toLowerCase()) && !p.projectManager?.name?.toLowerCase().includes(searchTerm.toLowerCase())) return;
            p.milestones.forEach((m: any) => {
                if (!m.dueDate) return;
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!dateGroups.has(label)) dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0, statusCounts: { Paid: 0, Sent: 0, Pending: 0 } };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) {
                    projInGroup.groupTotal += (m.paymentAmount || 0);
                    projInGroup.statusCounts[m.paymentStatus || 'Pending']++;
                }
            });
        });
        dateGroups.forEach(group => {
            group.projects.sort((a, b) => sortBy === 'value' ? b.groupTotal - a.groupTotal : a.name.localeCompare(b.name));
        });
        return Array.from(dateGroups.values()).sort((a, b) => a.sortKey - b.sortKey);
    }, [projectsWithMilestones, language, searchTerm, sortBy]);

    useEffect(() => {
        const currentLabel = getCurrentMonthYearLabel(language);
        if (aggregatedByDate.some(g => g.monthYear === currentLabel)) {
            setExpandedPeriods(prev => ({ ...prev, [currentLabel]: true }));
        }
    }, [aggregatedByDate, language]);

    const formatCurrency = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    const headerControls = (
        <div className="flex items-center gap-2">
             <div className="relative group">
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={e => setSearchTerm(e.target.value)} 
                    placeholder={t.quickSearch}
                    className="pl-8 pr-3 py-1.5 bg-white dark:bg-slate-800 rounded-xl text-[11px] border border-slate-200 dark:border-slate-700 focus:ring-1 focus:ring-violet-500 w-24 md:w-40 transition-all outline-none"
                />
                <svg className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
        </div>
    );

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="800px" headerExtra={headerControls}>
            <div className="space-y-4 pb-4">
                {aggregatedByDate.length > 0 ? aggregatedByDate.map((period, pIdx) => {
                    const isOpen = !!expandedPeriods[period.monthYear];
                    const periodTotal = period.projects.reduce((s, p) => s + p.groupTotal, 0);
                    return (
                        <div key={pIdx} className="space-y-3">
                            <button 
                                onClick={() => setExpandedPeriods(prev => ({ ...prev, [period.monthYear]: !isOpen }))}
                                className={`w-full flex items-center justify-between p-4 rounded-2xl transition-all duration-300 ${isOpen ? 'bg-violet-600 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-800/50 hover:bg-slate-200 text-slate-800 dark:text-white'}`}
                            >
                                <div className="flex items-center gap-3 text-start min-w-0">
                                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 ${isOpen ? 'bg-white/20' : 'bg-white dark:bg-slate-700'}`}>
                                        <svg className={`w-4 h-4 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
                                    </div>
                                    <div className="min-w-0">
                                        <h3 className="text-sm font-black truncate">{period.monthYear}</h3>
                                        <p className={`text-[9px] font-bold uppercase ${isOpen ? 'text-white/60' : 'text-slate-400'}`}>{period.projects.length} {t.projectsCountLabel}</p>
                                    </div>
                                </div>
                                <div className="text-end shrink-0">
                                    <p className="text-base font-black">{formatCurrency(periodTotal)}</p>
                                </div>
                            </button>

                            {isOpen && (
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 px-1 animate-in fade-in zoom-in-95 duration-300">
                                    {period.projects.map((proj, prIdx) => (
                                        <div key={prIdx} className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-2xl p-4 shadow-sm hover:border-violet-300 transition-all flex flex-col min-w-0">
                                            <div className="flex items-start justify-between mb-3 gap-2">
                                                <div className="flex items-center gap-2.5 min-w-0">
                                                    <img 
                                                        src={proj.projectManager?.avatarUrl || `https://ui-avatars.com/api/?name=${proj.projectManager?.name || '?'}&background=f5f3ff&color=7c3aed`} 
                                                        className="w-10 h-10 rounded-xl border border-slate-100 dark:border-slate-800 shrink-0 object-cover"
                                                        alt={proj.projectManager?.name}
                                                    />
                                                    <div className="min-w-0">
                                                        <h4 className="text-xs font-black text-slate-800 dark:text-white truncate tracking-tight">{proj.name}</h4>
                                                        <p className="text-[8px] font-bold text-slate-400 uppercase truncate">{proj.projectManager?.name || t.unassigned}</p>
                                                    </div>
                                                </div>
                                                <div className="text-end shrink-0">
                                                    <p className="text-sm font-black text-violet-600 dark:text-violet-400">{formatCurrency(proj.groupTotal)}</p>
                                                </div>
                                            </div>

                                            <div className="mt-auto space-y-2">
                                                <div className="flex gap-0.5 h-1.5 rounded-full overflow-hidden bg-slate-50 dark:bg-slate-800">
                                                    <div className="bg-emerald-500" style={{ width: `${(proj.statusCounts.Paid / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                                    <div className="bg-blue-500" style={{ width: `${(proj.statusCounts.Sent / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                                    <div className="bg-orange-500" style={{ width: `${(proj.statusCounts.Pending / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                                </div>
                                                <div className="flex justify-between text-[8px] font-black text-slate-400 uppercase">
                                                    <span className="text-emerald-600">{t.Paid} ({proj.statusCounts.Paid})</span>
                                                    <span className="text-blue-600">{t.Sent} ({proj.statusCounts.Sent})</span>
                                                    <span className="text-orange-600">{t.Pending} ({proj.statusCounts.Pending})</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                }) : (
                    <div className="py-20 text-center opacity-30">
                        <p className="text-xs font-black uppercase tracking-widest text-slate-400">{t.noData}</p>
                    </div>
                )}
            </div>
        </WidgetWrapper>
    );
};

const PaymentBreakdownChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];
    const statusCounts = useMemo(() => {
        const counts = { [PaymentStatus.Paid]: 0, [PaymentStatus.Sent]: 0, [PaymentStatus.Pending]: 0 };
        filteredMilestones.forEach(m => { if (m.hasPayment) (counts as any)[m.paymentStatus || PaymentStatus.Pending]++; });
        return Object.entries(counts);
    }, [filteredMilestones]);
    const maxCount = Math.max(...statusCounts.map(([, c]) => c), 1);
    const colorMap: any = { [PaymentStatus.Paid]: 'bg-emerald-500', [PaymentStatus.Sent]: 'bg-blue-500', [PaymentStatus.Pending]: 'bg-orange-500' };
    return (
        <WidgetWrapper title={t.paymentBreakdown} maxHeight="auto">
             <div className="space-y-4 pt-2">
                {statusCounts.map(([status, count]) => (
                    <div key={status} className="flex items-center gap-3">
                        <span className="w-16 text-[9px] font-black text-slate-500 uppercase truncate">{t[status as any]}</span>
                        <div className="flex-1 flex items-center gap-3">
                            <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-full h-2 overflow-hidden">
                                <div className={`${colorMap[status]} h-full transition-all duration-700`} style={{ width: `${(count / maxCount) * 100}%` }}></div>
                            </div>
                            <span className="font-black text-slate-800 dark:text-white text-[10px]">{count}</span>
                        </div>
                    </div>
                ))}
            </div>
        </WidgetWrapper>
    );
};

const TeamWorkloadChartWidget: React.FC<{ filteredProjects: Project[], teams: Lookup[], language: Language, onTeamClick: any }> = ({ filteredProjects, teams, language, onTeamClick }) => {
    const t = translations[language];
    const teamStats = useMemo(() => {
        return teams.map(tm => {
            const pjs = filteredProjects.filter(p => p.teamId === tm.id);
            return { team: tm, count: pjs.length, projects: pjs };
        }).filter(s => s.count > 0).sort((a,b) => b.count - a.count);
    }, [filteredProjects, teams]);
    const max = Math.max(...teamStats.map(s => s.count), 1);
    return (
         <WidgetWrapper title={t.teamWorkload} maxHeight="auto">
             <div className="space-y-4 pt-2">
                {teamStats.map(s => (
                    <div key={s.team.id} className="flex items-center gap-3 cursor-pointer group" onClick={() => onTeamClick(s.team, s.projects)}>
                        <span className="w-16 text-[9px] font-black text-slate-500 uppercase truncate group-hover:text-violet-600 transition-colors">{s.team.name}</span>
                        <div className="flex-1 flex items-center gap-3">
                            <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-full h-2 overflow-hidden">
                                <div className="bg-violet-500 h-full transition-all duration-700 group-hover:bg-violet-400" style={{ width: `${s.count / max * 100}%` }}></div>
                            </div>
                            <span className="font-black text-slate-800 dark:text-white text-[10px]">{s.count}</span>
                        </div>
                    </div>
                ))}
            </div>
        </WidgetWrapper>
    );
};

