interface AnalyticsDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    customers: Lookup[];
    projectManagers: User[];
    language: Language;
    currentUser?: User;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({ projects, milestones, teams, projectManagers, language }) => {
    const t = translations[language];
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [globalMonthYear, setGlobalMonthYear] = useState<string[]>(() => [getCurrentMonthYearLabel(language)]);
    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });
    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [viewingProject, setViewingProject] = useState<any>(null);
    const [viewingTeam, setViewingTeam] = useState<any>(null);

    const monthYearOptions = useMemo(() => {
        const unique = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                unique.set(label, { label, sortKey });
            }
        });
        const currentLabel = getCurrentMonthYearLabel(language);
        if (!unique.has(currentLabel)) {
            const now = new Date();
            unique.set(currentLabel, { label: currentLabel, sortKey: now.getFullYear() * 100 + now.getMonth() });
        }
        return Array.from(unique.values()).sort((a, b) => a.sortKey - b.sortKey).map(v => ({ value: v.label, label: v.label }));
    }, [milestones, language]);

    const { filteredProjects, filteredMilestones } = useMemo(() => {
        const fps = projects.filter(p => (globalProjectId === 'all' || p.id === globalProjectId) && (globalManagerId === 'all' || p.projectManagerId === globalManagerId));
        const projectIds = new Set(fps.map(p => p.id));
        const fms = milestones.filter(m => {
            if (!projectIds.has(m.projectId)) return false;
            if (globalMonthYear.length > 0) {
                if (!m.dueDate) return false;
                const d = new Date(m.dueDate);
                const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`;
                if (!globalMonthYear.includes(label)) return false;
            }
            return true;
        });
        return { filteredProjects: fps, filteredMilestones: fms };
    }, [projects, milestones, globalProjectId, globalManagerId, globalMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map(p => ({ ...p, milestones: filteredMilestones.filter(m => m.projectId === p.id) })).filter(p => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    return (
        <div className="space-y-8 max-w-[1600px] mx-auto">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}
            {viewingProject && <ProjectDetailModal projectWithMilestones={viewingProject} onClose={() => setViewingProject(null)} language={language} />}
            {viewingTeam && <TeamProjectsModal team={viewingTeam.team} projects={viewingTeam.projects} onClose={() => setViewingTeam(null)} language={language} onViewProject={(p) => { setViewingTeam(null); setViewingProject({ ...p, milestones: milestones.filter(m => m.projectId === p.id) }); }} />}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div>
                    <h1 className="text-3xl font-black text-slate-800 dark:text-white tracking-tight">{t.dashboard}</h1>
                    <p className="text-slate-500 font-bold text-sm mt-1">{t.overview}</p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-white dark:bg-slate-800 hover:bg-slate-50 active:scale-95 px-5 py-2.5 rounded-2xl flex items-center gap-2.5 transition-all shadow-sm font-black text-[10px] uppercase tracking-wider text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-violet-500" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 003.464V16a1 1 0 102 0V8.732a2 2 0 00-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" /></svg>
                    {t.customize}
                </button>
            </div>

            <div className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{t.project}</label>
                    <SearchableSelect options={[{value:'all', label:t.allProjects}, ...projects.map(p => ({value:p.id, label:p.name}))]} value={globalProjectId} onChange={setGlobalProjectId} placeholder={t.allProjects} language={language} />
                </div>
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{t.manager}</label>
                    <SearchableSelect options={[{value:'all', label:t.allManagers}, ...projectManagers.map(m => ({value:m.id, label:m.name}))]} value={globalManagerId} onChange={setGlobalManagerId} placeholder={t.allManagers} language={language} />
                </div>
                <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{t.monthYear}</label>
                    <SearchableSelect isMulti options={monthYearOptions} value={globalMonthYear} onChange={setGlobalMonthYear} placeholder={t.allMonths} language={language} />
                </div>
                <div className="flex items-end">
                    <button onClick={() => { setGlobalProjectId('all'); setGlobalManagerId('all'); setGlobalMonthYear([getCurrentMonthYearLabel(language)]); }} className="w-full py-2.5 bg-slate-800 dark:bg-slate-700 text-white text-[10px] font-black rounded-xl hover:bg-black transition-all uppercase tracking-widest">
                        {t.clearFilters}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 pb-10">
                {layout.map(widgetId => {
                    const config = WIDGETS_CONFIG.find(w => w.id === widgetId);
                    if (!config) return null;
                    const Component = config.component as any;
                    return (
                        <div key={config.id} className={`lg:col-span-${config.colSpan}`}>
                            <Component 
                                filteredProjects={filteredProjects} 
                                filteredMilestones={filteredMilestones}
                                projectsWithMilestones={projectsWithMilestones}
                                teams={teams}
                                language={language}
                                onTeamClick={(team: any, pjs: any) => setViewingTeam({ team, projects: pjs })}
                            />
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Project, Milestone, Lookup, Language, PaymentStatus, User } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';
import ProjectDetailModal from './ProjectDetailModal';
import TeamProjectsModal from './TeamProjectsModal';

// Helper to get current Month Year label
const getCurrentMonthYearLabel = (lang: Language) => {
    const now = new Date();
    const month = now.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
    return `${month} ${now.getFullYear()}`;
};

// --- Minimalist Widget Wrapper ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, headerExtra?: React.ReactNode }> = ({ title, children, maxHeight = 'none', headerExtra }) => (
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl flex flex-col transition-all overflow-hidden h-full shadow-sm hover:shadow-md transition-shadow duration-300">
        <div className="flex justify-between items-center py-5 px-8 border-b border-slate-100 dark:border-slate-800/50 flex-wrap gap-4">
            <h2 className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">{title}</h2>
            {headerExtra}
        </div>
        <div className="flex-grow overflow-y-auto custom-scrollbar px-6 py-5" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<{ filteredProjects: Project[], filteredMilestones: Milestone[], language: Language }> = ({ filteredProjects, filteredMilestones, language }) => {
    const t = translations[language];
    const stats = useMemo(() => {
        let pendingVal = 0; let sentVal = 0; let paidVal = 0;
        filteredMilestones.forEach(m => {
            if (!m.hasPayment) return;
            const amount = m.paymentAmount || 0;
            const status = m.paymentStatus || PaymentStatus.Pending;
            if (status === PaymentStatus.Pending) pendingVal += amount;
            else if (status === PaymentStatus.Sent) sentVal += amount;
            else if (status === PaymentStatus.Paid) paidVal += amount;
        });
        return { projectsCount: filteredProjects.length, pendingVal, sentVal, paidVal };
    }, [filteredProjects, filteredMilestones]);
    const formatVal = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <StatCard title={t.totalProjects} value={stats.projectsCount.toString()} icon="projects" />
            <StatCard title={t.filteredPending} value={formatVal(stats.pendingVal)} icon="inProgress" trendColor="text-orange-500" />
            <StatCard title={t.filteredSent} value={formatVal(stats.sentVal)} icon="completed" trendColor="text-blue-500" />
            <StatCard title={t.filteredPaid} value={formatVal(stats.paidVal)} icon="hours" trendColor="text-emerald-500" />
        </div>
    );
};

const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];
    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();
        filteredMilestones.forEach(m => {
            if (!m.dueDate || !m.hasPayment) return;
            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();
            if (!groups.has(labelKey)) groups.set(labelKey, { totalAmount: 0, sortKey });
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });
        return Array.from(groups.entries()).map(([monthYear, data]) => ({ monthYear, ...data })).sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);
    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 1000);
    return (
        <WidgetWrapper title={t.executionChartTitle}>
            <div className="h-48 flex items-end gap-2 pt-6">
                {graphData.map((d, i) => (
                    <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group">
                        <div style={{ height: `${(d.totalAmount / maxAmount) * 100}%` }} className="w-full max-w-[20px] bg-slate-200 dark:bg-slate-700 rounded-t group-hover:bg-violet-500 transition-colors" />
                        <span className="text-[8px] font-bold text-slate-400 mt-2 rotate-45 origin-left">{d.monthYear.split(' ')[0]}</span>
                    </div>
                ))}
                {graphData.length === 0 && <div className="w-full text-center text-slate-300 text-xs py-10">{t.noData}</div>}
            </div>
        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], language: Language }> = ({ projectsWithMilestones, language }) => {
    const t = translations[language];
    const [expandedPeriods, setExpandedPeriods] = useState<Record<string, boolean>>({});
    const [searchTerm, setSearchTerm] = useState('');

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();
        projectsWithMilestones.forEach(p => {
            if (searchTerm && !p.name.toLowerCase().includes(searchTerm.toLowerCase())) return;
            p.milestones.forEach((m: any) => {
                if (!m.dueDate) return;
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!dateGroups.has(label)) dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0, statusCounts: { Paid: 0, Sent: 0, Pending: 0 } };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) {
                    projInGroup.groupTotal += (m.paymentAmount || 0);
                    projInGroup.statusCounts[m.paymentStatus || 'Pending']++;
                }
            });
        });
        return Array.from(dateGroups.values()).sort((a, b) => a.sortKey - b.sortKey);
    }, [projectsWithMilestones, language, searchTerm]);

    useEffect(() => {
        const currentLabel = getCurrentMonthYearLabel(language);
        if (aggregatedByDate.some(g => g.monthYear === currentLabel)) {
            setExpandedPeriods(prev => ({ ...prev, [currentLabel]: true }));
        }
    }, [aggregatedByDate, language]);

    const formatCurrency = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="800px">
            <div className="mb-4">
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={e => setSearchTerm(e.target.value)} 
                    placeholder={t.quickSearch}
                    className="w-full px-4 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-1 focus:ring-violet-500 outline-none"
                />
            </div>
            <div className="space-y-3">
                {aggregatedByDate.length > 0 ? aggregatedByDate.map((period, pIdx) => {
                    const isOpen = !!expandedPeriods[period.monthYear];
                    const periodTotal = period.projects.reduce((s, p) => s + p.groupTotal, 0);
                    return (
                        <div key={pIdx} className="border border-slate-100 dark:border-slate-800 rounded-2xl overflow-hidden">
                            <button 
                                onClick={() => setExpandedPeriods(prev => ({ ...prev, [period.monthYear]: !isOpen }))}
                                className={`w-full flex items-center justify-between p-4 transition-colors ${isOpen ? 'bg-slate-50 dark:bg-slate-800' : 'bg-white dark:bg-slate-900 hover:bg-slate-50'}`}
                            >
                                <div className="flex items-center gap-3">
                                    <div className={`w-6 h-6 rounded flex items-center justify-center transition-transform ${isOpen ? 'rotate-180' : ''}`}>
                                        <svg className="w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
                                    </div>
                                    <h3 className="text-sm font-bold text-slate-700 dark:text-slate-200">{period.monthYear}</h3>
                                </div>
                                <div className="text-right">
                                    <p className="text-sm font-bold text-slate-900 dark:text-white">{formatCurrency(periodTotal)}</p>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase">{period.projects.length} {t.projectsCountLabel}</p>
                                </div>
                            </button>

                            {isOpen && (
                                <div className="p-4 bg-white dark:bg-slate-900 grid grid-cols-1 md:grid-cols-2 gap-3 border-t border-slate-100 dark:border-slate-800">
                                    {period.projects.map((proj, prIdx) => (
                                        <div key={prIdx} className="p-3 border border-slate-50 dark:border-slate-800 rounded-xl bg-slate-50/30">
                                            <div className="flex justify-between items-start mb-2">
                                                <div className="min-w-0">
                                                    <h4 className="text-xs font-bold text-slate-800 dark:text-white truncate">{proj.name}</h4>
                                                    <p className="text-[9px] text-slate-400 uppercase">{proj.projectManager?.name || t.unassigned}</p>
                                                </div>
                                                <span className="text-xs font-bold text-violet-600">{formatCurrency(proj.groupTotal)}</span>
                                            </div>
                                            <div className="h-1 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden flex">
                                                <div className="bg-emerald-500 h-full" style={{ width: `${(proj.statusCounts.Paid / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                                <div className="bg-blue-500 h-full" style={{ width: `${(proj.statusCounts.Sent / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                                <div className="bg-orange-500 h-full" style={{ width: `${(proj.statusCounts.Pending / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                }) : (
                    <div className="py-10 text-center text-slate-300 text-sm">{t.noData}</div>
                )}
            </div>
        </WidgetWrapper>
    );
};

