const AnalyticsDashboard: React.FC<any> = ({ projects, milestones, teams, projectManagers, language }) => {
    const t = translations[language];
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [globalMonthYear, setGlobalMonthYear] = useState<string[]>(() => [getCurrentMonthYearLabel(language)]);
    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });
    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);

    const monthYearOptions = useMemo(() => {
        const unique = new Set<string>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const d = new Date(m.dueDate);
                unique.add(`${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`);
            }
        });
        unique.add(getCurrentMonthYearLabel(language));
        return Array.from(unique).map(v => ({ value: v, label: v }));
    }, [milestones, language]);

    const { filteredProjects, filteredMilestones } = useMemo(() => {
        const fps = projects.filter((p: any) => (globalProjectId === 'all' || p.id === globalProjectId) && (globalManagerId === 'all' || p.projectManagerId === globalManagerId));
        const pIds = new Set(fps.map((p: any) => p.id));
        const fms = milestones.filter((m: any) => {
            if (!pIds.has(m.projectId)) return false;
            if (globalMonthYear.length > 0) {
                if (!m.dueDate) return false;
                const d = new Date(m.dueDate);
                const l = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`;
                if (!globalMonthYear.includes(l)) return false;
            }
            return true;
        });
        return { filteredProjects: fps, filteredMilestones: fms };
    }, [projects, milestones, globalProjectId, globalManagerId, globalMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map((p: any) => ({ ...p, milestones: filteredMilestones.filter((m: any) => m.projectId === p.id) })).filter((p: any) => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    return (
        <div className="space-y-8 max-w-[1400px] mx-auto pb-20">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight">{t.dashboard}</h1>
                    <p className="text-slate-400 font-medium text-xs mt-1 uppercase tracking-widest">{t.overview}</p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-white dark:bg-slate-800 px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest text-slate-500 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-colors">
                    {t.customize}
                </button>
            </div>

            <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-wrap gap-4">
                <div className="flex-1 min-w-[150px]">
                    <SearchableSelect options={[{value:'all', label:t.allProjects}, ...projects.map((p: any) => ({value:p.id, label:p.name}))]} value={globalProjectId} onChange={setGlobalProjectId} placeholder={t.allProjects} language={language} />
                </div>
                <div className="flex-1 min-w-[150px]">
                    <SearchableSelect options={[{value:'all', label:t.allManagers}, ...projectManagers.map((m: any) => ({value:m.id, label:m.name}))]} value={globalManagerId} onChange={setGlobalManagerId} placeholder={t.allManagers} language={language} />
                </div>
                <div className="flex-1 min-w-[150px]">
                    <SearchableSelect isMulti options={monthYearOptions} value={globalMonthYear} onChange={setGlobalMonthYear} placeholder={t.allMonths} language={language} />
                </div>
                <button onClick={() => { setGlobalProjectId('all'); setGlobalManagerId('all'); setGlobalMonthYear([getCurrentMonthYearLabel(language)]); }} className="px-4 py-2 bg-slate-100 text-slate-500 text-[10px] font-bold rounded-xl hover:bg-slate-200 transition-all uppercase tracking-widest">
                    {t.clearFilters}
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                {layout.map(widgetId => {
                    const config = WIDGETS_CONFIG.find(w => w.id === widgetId);
                    if (!config) return null;
                    const Component = config.component as any;
                    return (
                        <div key={config.id} className={`lg:col-span-${config.colSpan}`}>
                            <Component 
                                filteredProjects={filteredProjects} 
                                filteredMilestones={filteredMilestones}
                                projectsWithMilestones={projectsWithMilestones}
                                teams={teams}
                                language={language}
                            />
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

