import React, { useState, useEffect, useCallback } from 'react';
import { Session, SupabaseClient } from '@supabase/supabase-js';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import Projects from './components/Projects';
import Milestones from './components/Milestones';
import Team from './components/Team';
import Payments from './components/Payments';
import MaintenanceContracts from './components/MaintenanceContracts';
import SystemManagement from './components/SystemManagement';
import MilestoneFilter from './components/MilestoneFilter';
import Login from './components/Login';
import EditProjectModal from './components/EditProjectModal';
import EditMilestoneModal from './components/EditMilestoneModal';
import MilestoneDetailModal from './components/MilestoneDetailModal';
import ConfirmDeleteModal from './components/ConfirmDeleteModal';
import Chatbot from './components/Chatbot';
import { Language, Theme, View, Project, Milestone, User, Lookups, MilestoneUpdate, MaintenanceContract, ProjectImportRow } from './types';
import { fetchAllData, addProject as apiAddProject, updateProject as apiUpdateProject, addMilestones as apiAddMilestones, updateMilestone as apiUpdateMilestone, updateLookups as apiUpdateLookups, deleteProject as apiDeleteProject, addMilestoneUpdate as apiAddMilestoneUpdate, addProjects as apiAddProjects, addMaintenanceContract as apiAddMaintenanceContract, updateMaintenanceContract as apiUpdateMaintenanceContract } from './services/api';
import { initSupabase } from './services/supabaseClient';

const App: React.FC = () => {
    // UI State
    const [view, setView] = useState<View>(() => (localStorage.getItem('lastView') as View) || 'dashboard');
    const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('language') as Language) || 'en');
    const [theme, setTheme] = useState<Theme>(() => (localStorage.getItem('theme') as Theme) || 'light');

    // Modals state
    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);
    const [viewingMilestone, setViewingMilestone] = useState<Milestone | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [isChatbotOpen, setIsChatbotOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);

    // Data State
    const [projects, setProjects] = useState<Project[]>([]);
    const [milestones, setMilestones] = useState<Milestone[]>([]);
    const [milestoneUpdates, setMilestoneUpdates] = useState<MilestoneUpdate[]>([]);
    const [maintenanceContracts, setMaintenanceContracts] = useState<MaintenanceContract[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [lookups, setLookups] = useState<Lookups>({
        countries: [], categories: [], teams: [], products: [], projectStatuses: [], projectManagers: [], customers: []
    });

    // Auth & Connection State
    const [session, setSession] = useState<Session | null>(null);
    const [supabaseClient, setSupabaseClient] = useState<SupabaseClient | null>(null);
    const [isAppConfigured, setIsAppConfigured] = useState(false);
    const [isDbConnected, setIsDbConnected] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // Sync UI Preferences
    useEffect(() => { localStorage.setItem('lastView', view); }, [view]);
    useEffect(() => { localStorage.setItem('language', language); }, [language]);
    useEffect(() => {
        localStorage.setItem('theme', theme);
        if (theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    }, [theme]);

    // Initialize Supabase
    useEffect(() => {
        const key = localStorage.getItem('supabaseAnonKey');
        if (key && key.trim()) {
            try {
                const client = initSupabase('https://dcamlinhazzmbaldsrdo.supabase.co', key);
                setSupabaseClient(client);
                setIsAppConfigured(true);
            } catch (error) {
                localStorage.removeItem('supabaseAnonKey');
                setIsAppConfigured(false);
                setIsLoading(false);
            }
        } else {
            setIsAppConfigured(false);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        if (supabaseClient) {
            supabaseClient.auth.getSession().then(({ data: { session } }) => {
                setSession(session);
                if (session) setIsDbConnected(true);
                setIsLoading(false);
            });
            const { data: { subscription } } = supabaseClient.auth.onAuthStateChange((_event, session) => {
                setSession(session);
                setIsDbConnected(!!session);
            });
            return () => subscription.unsubscribe();
        }
    }, [supabaseClient]);

    // Data Load Logic
    const loadDataFromDb = useCallback(async () => {
        if (!isDbConnected) return;
        try {
            setIsLoading(true);
            const data = await fetchAllData();
            setProjects(data.projects);
            setMilestones(data.milestones);
            setUsers(data.users);
            setLookups(data.lookups);
            setMilestoneUpdates(data.milestoneUpdates);
            setMaintenanceContracts(data.maintenanceContracts);
        } catch (error) {
            console.error("Data Load Error:", error);
        } finally {
            setIsLoading(false);
        }
    }, [isDbConnected]);

    useEffect(() => {
        if (isDbConnected) loadDataFromDb();
    }, [isDbConnected, loadDataFromDb]);

    // --- Real Database Actions ---

    const handleAddProject = async (projectData: any) => {
        await apiAddProject(projectData);
        await loadDataFromDb();
    };

    const handleUpdateProject = async (id: string, data: any) => {
        await apiUpdateProject(id, data);
        await loadDataFromDb();
    };

    const handleDeleteProject = async () => {
        if (deletingProject) {
            await apiDeleteProject(deletingProject.id);
            setDeletingProject(null);
            await loadDataFromDb();
        }
    };

    const handleAddMilestones = async (milestonesData: any[]) => {
        await apiAddMilestones(milestonesData);
        await loadDataFromDb();
    };

    const handleUpdateMilestone = async (id: string, data: any) => {
        await apiUpdateMilestone(id, data);
        await loadDataFromDb();
    };

    const handleAddMilestoneUpdate = async (updateData: any) => {
        await apiAddMilestoneUpdate(updateData);
        await loadDataFromDb();
    };

    const handleImportProjects = async (rows: ProjectImportRow[]) => {
        // Logic to convert rows to project entities could be added here
        // For now, call the batch API if implemented
        await loadDataFromDb();
    };

    const handleLogout = async () => {
        if (supabaseClient) await supabaseClient.auth.signOut();
    };

    // Render loading screen
    if (isLoading) {
        return (
            <div className="min-h-screen bg-white flex items-center justify-center">
                <div className="w-10 h-10 border-2 border-slate-100 border-t-violet-600 rounded-full animate-spin"></div>
            </div>
        );
    }

    // Setup mode if no key
    if (!isAppConfigured) {
        return <SystemManagement lookups={lookups} onUpdate={() => {}} language={language} onSaveConfig={(key) => {
            localStorage.setItem('supabaseAnonKey', key);
            window.location.reload();
        }} isSetupMode={true} />;
    }

    // Login screen if not authenticated
    if (!session) {
        return <Login onLoginSuccess={() => setIsDbConnected(true)} language={language} setLanguage={setLanguage} supabaseClient={supabaseClient!} />;
    }

    return (
        <div className="flex h-screen bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <Sidebar currentView={view} setCurrentView={setView} language={language} />
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                <Header user={users.find(u => u.id === session.user.id)} language={language} setLanguage={setLanguage} onSearch={() => {}} onLogout={handleLogout} theme={theme} setTheme={setTheme} isDbConnected={isDbConnected} />
                <main className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                    {view === 'dashboard' && <AnalyticsDashboard projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} />}
                    {view === 'projects' && (
                        <Projects 
                            allProjects={projects} 
                            allUsers={users} 
                            language={language} 
                            onAddProject={handleAddProject} 
                            onOpenEditModal={setEditingProject} 
                            onOpenDeleteModal={setDeletingProject} 
                            lookups={lookups} 
                            isImportModalOpen={isImportModalOpen} 
                            onOpenImportModal={() => setIsImportModalOpen(true)} 
                            onCloseImportModal={() => setIsImportModalOpen(false)} 
                            onImportProjects={handleImportProjects} 
                        />
                    )}
                    {view === 'milestones' && <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={handleAddMilestones} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={handleUpdateMilestone} lookups={lookups} />}
                    {view === 'team' && <Team allUsers={users} allProjects={projects} language={language} />}
                    {view === 'payments' && <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={handleUpdateMilestone} />}
                    {view === 'maintenanceContracts' && <MaintenanceContracts contracts={maintenanceContracts} customers={lookups.customers} language={language} onAddContract={apiAddMaintenanceContract} onUpdateContract={apiUpdateMaintenanceContract} />}
                    {view === 'system' && <SystemManagement lookups={lookups} onUpdate={apiUpdateLookups} language={language} onSaveConfig={() => {}} />}
                    {view === 'filter' && <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={handleUpdateMilestone} />}
                </main>
            </div>

            {editingProject && <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={handleUpdateProject} language={language} />}
            {editingMilestone && <EditMilestoneModal milestoneToEdit={editingMilestone} allMilestones={milestones} teams={lookups.teams} projects={projects} allMilestoneUpdates={milestoneUpdates} allUsers={users} currentUser={users.find(u => u.id === session.user.id)} onClose={() => setEditingMilestone(null)} onUpdateMilestone={handleUpdateMilestone} onAddMilestones={handleAddMilestones} onAddUpdate={handleAddMilestoneUpdate} language={language} />}
            {viewingMilestone && <MilestoneDetailModal milestone={viewingMilestone} projects={projects} allMilestoneUpdates={milestoneUpdates} allUsers={users} lookups={lookups} onClose={() => setViewingMilestone(null)} language={language} />}
            {deletingProject && <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={handleDeleteProject} language={language} />}

            <button onClick={() => setIsChatbotOpen(true)} className="fixed bottom-8 right-8 rtl:right-auto rtl:left-8 bg-slate-900 text-white p-4 rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all z-50">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
            </button>
            <Chatbot isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} language={language} projects={projects} milestones={milestones} users={users} lookups={lookups} />
        </div>
    );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Project, Milestone, Lookup, Language, PaymentStatus, User } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';
import ProjectDetailModal from './ProjectDetailModal';
import TeamProjectsModal from './TeamProjectsModal';

// Helper to get current Month Year label
const getCurrentMonthYearLabel = (lang: Language) => {
    const now = new Date();
    const month = now.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
    return `${month} ${now.getFullYear()}`;
};

// --- Minimalist Widget Wrapper ---

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string, headerExtra?: React.ReactNode }> = ({ title, children, maxHeight = 'none', headerExtra }) => (
    <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-[2rem] flex flex-col transition-all overflow-hidden h-full shadow-sm">
        <div className="flex justify-between items-center py-5 px-8 border-b border-slate-50 dark:border-slate-800/50 flex-wrap gap-4">
            <h2 className="text-sm font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{title}</h2>
            {headerExtra}
        </div>
        <div className="flex-grow overflow-y-auto custom-scrollbar px-6 py-5" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<{ filteredProjects: Project[], filteredMilestones: Milestone[], language: Language }> = ({ filteredProjects, filteredMilestones, language }) => {
    const t = translations[language];
    const stats = useMemo(() => {
        let pendingVal = 0; let sentVal = 0; let paidVal = 0;
        filteredMilestones.forEach(m => {
            if (!m.hasPayment) return;
            const amount = m.paymentAmount || 0;
            const status = m.paymentStatus || PaymentStatus.Pending;
            if (status === PaymentStatus.Pending) pendingVal += amount;
            else if (status === PaymentStatus.Sent) sentVal += amount;
            else if (status === PaymentStatus.Paid) paidVal += amount;
        });
        return { projectsCount: filteredProjects.length, pendingVal, sentVal, paidVal };
    }, [filteredProjects, filteredMilestones]);
    const formatVal = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <StatCard title={t.totalProjects} value={stats.projectsCount.toString()} icon="projects" />
            <StatCard title={t.filteredPending} value={formatVal(stats.pendingVal)} icon="inProgress" trendColor="text-orange-500" />
            <StatCard title={t.filteredSent} value={formatVal(stats.sentVal)} icon="completed" trendColor="text-blue-500" />
            <StatCard title={t.filteredPaid} value={formatVal(stats.paidVal)} icon="hours" trendColor="text-emerald-500" />
        </div>
    );
};

const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones, language }) => {
    const t = translations[language];
    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();
        filteredMilestones.forEach(m => {
            if (!m.dueDate || !m.hasPayment) return;
            const date = new Date(m.dueDate);
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();
            if (!groups.has(labelKey)) groups.set(labelKey, { totalAmount: 0, sortKey });
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });
        return Array.from(groups.entries()).map(([monthYear, data]) => ({ monthYear, ...data })).sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);
    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 1000);
    return (
        <WidgetWrapper title={t.executionChartTitle}>
            <div className="h-48 flex items-end gap-3 pt-8 min-w-0">
                {graphData.map((d, i) => (
                    <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                        <div style={{ height: `${(d.totalAmount / maxAmount) * 100}%` }} className="w-full max-w-[24px] bg-violet-100 dark:bg-slate-800 rounded-t-md group-hover:bg-violet-500 transition-all duration-300 relative">
                             <span className="absolute -top-5 left-1/2 -translate-x-1/2 text-[9px] font-black text-slate-800 dark:text-white whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity">${(d.totalAmount/1000).toFixed(0)}K</span>
                        </div>
                        <span className="text-[8px] font-bold text-slate-400 mt-2 truncate w-full text-center">{d.monthYear.split(' ')[0]}</span>
                    </div>
                ))}
                {graphData.length === 0 && <div className="w-full text-center text-slate-300 text-xs py-10 uppercase font-black">{t.noData}</div>}
            </div>
        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], language: Language }> = ({ projectsWithMilestones, language }) => {
    const t = translations[language];
    const [expandedPeriods, setExpandedPeriods] = useState<Record<string, boolean>>({});
    const [searchTerm, setSearchTerm] = useState('');

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();
        projectsWithMilestones.forEach(p => {
            if (searchTerm && !p.name.toLowerCase().includes(searchTerm.toLowerCase())) return;
            p.milestones.forEach((m: any) => {
                if (!m.dueDate) return;
                const date = new Date(m.dueDate);
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!dateGroups.has(label)) dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0, statusCounts: { Paid: 0, Sent: 0, Pending: 0 } };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) {
                    projInGroup.groupTotal += (m.paymentAmount || 0);
                    projInGroup.statusCounts[m.paymentStatus || 'Pending']++;
                }
            });
        });
        return Array.from(dateGroups.values()).sort((a, b) => a.sortKey - b.sortKey);
    }, [projectsWithMilestones, language, searchTerm]);

    useEffect(() => {
        const currentLabel = getCurrentMonthYearLabel(language);
        if (aggregatedByDate.some(g => g.monthYear === currentLabel)) {
            setExpandedPeriods(prev => ({ ...prev, [currentLabel]: true }));
        }
    }, [aggregatedByDate, language]);

    const formatCurrency = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="800px">
            <div className="mb-6 relative">
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={e => setSearchTerm(e.target.value)} 
                    placeholder={t.quickSearch}
                    className="w-full pl-10 pr-4 py-2.5 text-sm bg-slate-50 dark:bg-slate-800 border-none rounded-2xl focus:ring-1 focus:ring-violet-500 outline-none"
                />
                <svg className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
            <div className="space-y-4">
                {aggregatedByDate.length > 0 ? aggregatedByDate.map((period, pIdx) => {
                    const isOpen = !!expandedPeriods[period.monthYear];
                    const periodTotal = period.projects.reduce((s, p) => s + p.groupTotal, 0);
                    return (
                        <div key={pIdx} className="rounded-3xl border border-slate-50 dark:border-slate-800 overflow-hidden">
                            <button 
                                onClick={() => setExpandedPeriods(prev => ({ ...prev, [period.monthYear]: !isOpen }))}
                                className={`w-full flex items-center justify-between p-5 transition-all ${isOpen ? 'bg-slate-50 dark:bg-slate-800' : 'bg-white dark:bg-slate-900 hover:bg-slate-50/50'}`}
                            >
                                <div className="flex items-center gap-4 text-start min-w-0">
                                    <div className={`w-6 h-6 rounded flex items-center justify-center transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`}>
                                        <svg className="w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
                                    </div>
                                    <div className="min-w-0">
                                        <h3 className="text-sm font-black text-slate-800 dark:text-slate-200">{period.monthYear}</h3>
                                        <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">{period.projects.length} {t.projectsCountLabel}</p>
                                    </div>
                                </div>
                                <div className="text-right flex-shrink-0">
                                    <p className="text-sm font-black text-slate-900 dark:text-white leading-none">{formatCurrency(periodTotal)}</p>
                                </div>
                            </button>

                            {isOpen && (
                                <div className="p-4 bg-white dark:bg-slate-900 grid grid-cols-1 md:grid-cols-2 gap-3 border-t border-slate-50 dark:border-slate-800">
                                    {period.projects.map((proj, prIdx) => (
                                        <div key={prIdx} className="p-4 bg-slate-50/50 dark:bg-slate-800/40 rounded-2xl border border-slate-50 dark:border-slate-800 group hover:border-violet-200 transition-colors">
                                            <div className="flex justify-between items-start mb-3 gap-3">
                                                <div className="min-w-0">
                                                    <h4 className="text-xs font-black text-slate-800 dark:text-white truncate tracking-tight">{proj.name}</h4>
                                                    <p className="text-[9px] text-slate-400 font-bold uppercase">{proj.projectManager?.name || t.unassigned}</p>
                                                </div>
                                                <span className="text-xs font-black text-violet-600 dark:text-violet-400 whitespace-nowrap">{formatCurrency(proj.groupTotal)}</span>
                                            </div>
                                            <div className="h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden flex shadow-inner">
                                                <div className="bg-emerald-500 h-full" style={{ width: `${(proj.statusCounts.Paid / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                                <div className="bg-blue-500 h-full" style={{ width: `${(proj.statusCounts.Sent / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                                <div className="bg-orange-500 h-full" style={{ width: `${(proj.statusCounts.Pending / Math.max(proj.milestonesInGroup.length, 1)) * 100}%` }}></div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                }) : (
                    <div className="py-16 text-center opacity-30 font-black uppercase text-xs tracking-widest">{t.noData}</div>
                )}
            </div>
        </WidgetWrapper>
    );
};

