import React, { useState, useMemo } from 'react';
import { Milestone, Project, Lookup, MilestoneStatus, Language, PaymentStatus } from '../types';
import SearchableSelect from './SearchableSelect';

interface AddMilestoneModalProps {
  teams: Lookup[];
  projects: Project[];
  onClose: () => void;
  onAddMilestone: (newMilestones: Omit<Milestone, 'id'>[]) => Promise<void>;
  language: Language;
}

const AddMilestoneModal: React.FC<AddMilestoneModalProps> = ({ teams, projects, onClose, onAddMilestone, language }) => {
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');
  const [isSaving, setIsSaving] = useState(false);
  const [milestonesList, setMilestonesList] = useState<Omit<Milestone, 'id'>[]>([]);
  const [error, setError] = useState<string | null>(null);

  const [currentMilestone, setCurrentMilestone] = useState({
      title: '', description: '', teamId: '', dueDate: '',
      status: MilestoneStatus.Pending, hasPayment: true, paymentAmount: 0, paymentStatus: PaymentStatus.Pending,
  });

  const t = translations[language];
  const projectOptions = useMemo(() => projects.map(p => ({ value: p.id, label: p.name })), [projects]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
      setCurrentMilestone(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
      setCurrentMilestone(prev => ({ ...prev, [name]: value }));
    }
  };

  const addMilestoneToList = () => {
    if (!selectedProjectId) { setError(t.noProjectSelected); return; }
    if (!currentMilestone.title || !currentMilestone.teamId) { setError(t.validationErrorFields); return; }
    const newItem: Omit<Milestone, 'id'> = {
      ...currentMilestone,
      projectId: selectedProjectId,
      dueDate: currentMilestone.dueDate ? new Date(currentMilestone.dueDate).toISOString() : null,
      paymentAmount: Number(currentMilestone.paymentAmount),
    };
    setMilestonesList(prev => [...prev, newItem]);
    setCurrentMilestone({ title: '', description: '', teamId: '', dueDate: '', status: MilestoneStatus.Pending, hasPayment: true, paymentAmount: 0, paymentStatus: PaymentStatus.Pending });
    setError(null);
  };

  const handleFinalSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (milestonesList.length === 0) { setError(t.noItems); return; }
    try {
        setIsSaving(true);
        setError(null);
        await onAddMilestone(milestonesList);
        setIsSaving(false);
        onClose(); // Only close on successful save
    } catch (err: any) {
        console.error("Save failed:", err);
        setError(err?.message || "Critical: Save failed. Database connection error.");
        setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4">
      <div className="bg-white dark:bg-slate-900 border border-slate-200 rounded-3xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh]">
        <div className="p-6 border-b flex justify-between items-center">
            <h2 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h2>
            <button onClick={onClose} disabled={isSaving} className="text-slate-400 hover:text-slate-600 text-2xl font-bold">&times;</button>
        </div>
        <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
            {error && <div className="p-4 text-xs font-bold text-red-600 bg-red-50 border border-red-100 rounded-xl">{error}</div>}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="space-y-4">
                    <div className="bg-slate-50 dark:bg-slate-800/40 p-4 rounded-2xl border border-slate-100">
                         <label className="block text-[10px] font-black text-violet-600 uppercase mb-2">{t.project}</label>
                         <SearchableSelect options={projectOptions} value={selectedProjectId} onChange={setSelectedProjectId} placeholder={t.selectHere} language={language} />
                    </div>
                    <div className="space-y-4 pt-2">
                        <input type="text" name="title" value={currentMilestone.title} onChange={handleInputChange} placeholder={t.milestoneTitle} className="w-full p-3 bg-white dark:bg-slate-800 border rounded-xl text-sm outline-none focus:ring-1 focus:ring-violet-500" />
                        <div className="grid grid-cols-2 gap-4">
                            <select name="teamId" value={currentMilestone.teamId} onChange={handleInputChange} className="p-3 bg-white dark:bg-slate-800 border rounded-xl text-sm outline-none">
                                <option value="">{t.selectTeam}</option>
                                {teams.map(tm => <option key={tm.id} value={tm.id}>{tm.name}</option>)}
                            </select>
                            <input type="date" name="dueDate" value={currentMilestone.dueDate} onChange={handleInputChange} className="p-3 bg-white dark:bg-slate-800 border rounded-xl text-sm outline-none" />
                        </div>
                        <button type="button" onClick={addMilestoneToList} className="w-full py-3 bg-slate-800 text-white rounded-xl text-xs font-black uppercase hover:bg-black transition-all">+ {t.addToList}</button>
                    </div>
                </div>
                <div className="bg-slate-50 dark:bg-slate-800/20 rounded-2xl p-4 border border-slate-100">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase mb-4 tracking-widest">{t.listTitle}</h3>
                    <div className="space-y-2">
                        {milestonesList.length === 0 ? <p className="text-center py-10 text-xs text-slate-400 font-bold italic">{t.noItems}</p> : milestonesList.map((m, i) => (
                            <div key={i} className="flex justify-between items-center bg-white dark:bg-slate-800 p-3 rounded-xl border text-sm">
                                <span className="font-bold text-slate-800 dark:text-white truncate">{m.title}</span>
                                <button onClick={() => setMilestonesList(prev => prev.filter((_, idx) => idx !== i))} className="text-red-500 text-lg">&times;</button>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
        <div className="p-6 border-t flex justify-end gap-3">
            <button onClick={onClose} disabled={isSaving} className="px-6 py-2.5 text-xs font-black text-slate-500 uppercase">{t.cancel}</button>
            <button onClick={handleFinalSubmit} disabled={isSaving || milestonesList.length === 0} className="px-10 py-2.5 bg-violet-600 text-white rounded-xl text-xs font-black uppercase hover:bg-violet-700 disabled:opacity-50 flex items-center gap-2">
                {isSaving && <span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>}
                {isSaving ? t.submitting : t.saveAll}
            </button>
        </div>
      </div>
    </div>
  );
};

const translations = {
    ar: { title: "إضافة معالم", project: "المشروع", selectHere: "اختر المشروع...", milestoneTitle: "عنوان المعلم", selectTeam: "اختر الفريق...", addToList: "إضافة مؤقتة", listTitle: "بانتظار الحفظ النهائي", noItems: "القائمة فارغة.", saveAll: "حفظ نهائي لقاعدة البيانات", cancel: "إلغاء", noProjectSelected: "يرجى اختيار مشروع.", validationErrorFields: "يرجى تعبئة العنوان والفريق.", submitting: "جاري الحفظ..." },
    en: { title: "Add Milestones", project: "Project", selectHere: "Select project...", milestoneTitle: "Milestone Title", selectTeam: "Select team...", addToList: "Add to Queue", listTitle: "Ready for Save", noItems: "Queue is empty.", saveAll: "Save to Database", cancel: "Cancel", noProjectSelected: "Select a project.", validationErrorFields: "Title and Team are required.", submitting: "Saving..." }
};

