import { fetchAllData, addProject as apiAddProject, updateProject as apiUpdateProject, addMilestones as apiAddMilestones, updateMilestone as apiUpdateMilestone, updateLookups as apiUpdateLookups, deleteProject as apiDeleteProject, addMilestoneUpdate as apiAddMilestoneUpdate } from './services/api';
import { initSupabase } from './services/supabaseClient';

const App: React.FC = () => {
    // UI & Config State
