                {errorMsg && (
                    <div className="mx-8 mt-4 p-4 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800 rounded-2xl flex justify-between items-center">
                        <p className="text-xs font-bold text-red-600 dark:text-red-400">{errorMsg}</p>
                        <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="px-4 py-1.5 bg-red-600 text-white text-[10px] font-black rounded-lg uppercase">Reset Keys</button>
                    </div>
