import { initSupabase } from './services/supabaseClient';

const App: React.FC = () => {
    const [view, setView] = useState<View>(() => (localStorage.getItem('lastView') as View) || 'dashboard');
    const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('language') as Language) || 'en');
    const [theme, setTheme] = useState<Theme>(() => (localStorage.getItem('theme') as Theme) || 'light');
    const [isLoading, setIsLoading] = useState(true);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);

    const [projects, setProjects] = useState<Project[]>([]);
    const [milestones, setMilestones] = useState<Milestone[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [lookups, setLookups] = useState<Lookups>({ countries: [], categories: [], teams: [], products: [], projectStatuses: [], projectManagers: [], customers: [] });

    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);
    const [viewingMilestone, setViewingMilestone] = useState<Milestone | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [isChatbotOpen, setIsChatbotOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);

    const [session, setSession] = useState<Session | null>(null);
    const [supabaseClient, setSupabaseClient] = useState<SupabaseClient | null>(null);
    const [isAppConfigured, setIsAppConfigured] = useState(false);

    const isFetching = useRef(false);

    useEffect(() => { localStorage.setItem('lastView', view); }, [view]);
    useEffect(() => { localStorage.setItem('language', language); }, [language]);
    useEffect(() => {
        localStorage.setItem('theme', theme);
        document.documentElement.classList.toggle('dark', theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches));
    }, [theme]);

    const setupClient = useCallback((key: string, url: string) => {
        try {
            const client = initSupabase(url, key);
            setSupabaseClient(client);
            setIsAppConfigured(true);
            setErrorMsg(null);
            return true;
        } catch (e: any) {
            setErrorMsg(e.message || "Invalid Supabase Configuration");
            setIsAppConfigured(false);
            return false;
        }
    }, []);

    useEffect(() => {
        const key = localStorage.getItem('supabaseAnonKey');
        const url = localStorage.getItem('supabaseUrl') || 'https://dcamlinhazzmbaldsrdo.supabase.co';
        if (key?.trim()) {
            setupClient(key, url);
        } else {
            setIsAppConfigured(false);
            setIsLoading(false);
        }
    }, [setupClient]);

    useEffect(() => {
        if (!supabaseClient) return;
        supabaseClient.auth.getSession().then(({ data: { session } }) => {
            setSession(session);
            setIsLoading(false);
        });
        const { data: { subscription } } = supabaseClient.auth.onAuthStateChange((_event, session) => {
            setSession(session);
        });
        return () => subscription.unsubscribe();
    }, [supabaseClient]);

    const loadData = useCallback(async () => {
        if (!session || isFetching.current) return;
        try {
            isFetching.current = true;
            const data = await fetchAllData();
            setProjects(data.projects || []);
            setMilestones(data.milestones || []);
            setUsers(data.users || []);
            if (data.lookups) setLookups(data.lookups);
            setErrorMsg(null);
        } catch (e: any) {
            setErrorMsg("Connection error: Make sure your tables exist in Supabase.");
        } finally {
            isFetching.current = false;
        }
    }, [session]);

    useEffect(() => {
        if (session) loadData();
    }, [session, loadData]);

    const handleSaveConfig = (key: string, url: string) => {
        localStorage.setItem('supabaseAnonKey', key);
        localStorage.setItem('supabaseUrl', url);
        if (setupClient(key, url)) {
            // Success
        }
    };

    if (isLoading) return <div className="min-h-screen bg-white dark:bg-slate-950 flex items-center justify-center flex-col gap-4"><div className="w-10 h-10 border-4 border-slate-200 border-t-violet-600 rounded-full animate-spin"></div></div>;
    if (!isAppConfigured) return <SystemManagement lookups={lookups} onUpdate={() => {}} language={language} onSaveConfig={handleSaveConfig} isSetupMode={true} />;
    if (!session) return <Login onLoginSuccess={() => loadData()} language={language} setLanguage={setLanguage} supabaseClient={supabaseClient!} />;

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <Sidebar currentView={view} setCurrentView={setView} language={language} />
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                <Header user={users.find(u => u.id === session.user.id)} language={language} setLanguage={setLanguage} onSearch={() => {}} onLogout={() => supabaseClient?.auth.signOut()} theme={theme} setTheme={setTheme} isDbConnected={!!session} />
                {errorMsg && (
                    <div className="mx-8 mt-4 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 rounded-xl flex justify-between items-center animate-in slide-in-from-top-1">
                        <p className="text-[10px] font-black uppercase text-red-600">{errorMsg}</p>
                        <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="text-[9px] font-black bg-red-600 text-white px-3 py-1 rounded-lg">RESET</button>
                    </div>
                )}
                <main className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                    {view === 'dashboard' && <AnalyticsDashboard projects={projects} milestones={milestones} projectManagers={lookups.projectManagers} language={language} />}
                    {view === 'projects' && <Projects allProjects={projects} allUsers={users} language={language} onAddProject={async (d) => { await apiAddProject(d); loadData(); }} onOpenEditModal={setEditingProject} onOpenDeleteModal={setDeletingProject} lookups={lookups} isImportModalOpen={isImportModalOpen} onOpenImportModal={() => setIsImportModalOpen(true)} onCloseImportModal={() => setIsImportModalOpen(false)} onImportProjects={async () => {}} />}
                    {view === 'milestones' && <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} lookups={lookups} />}
                    {view === 'team' && <Team allUsers={users} allProjects={projects} language={language} />}
                    {view === 'payments' && <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'system' && <SystemManagement lookups={lookups} onUpdate={apiUpdateLookups} language={language} onSaveConfig={handleSaveConfig} />}
                    {view === 'filter' && <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                </main>
            </div>
            {editingProject && <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={async (id, d) => { await apiUpdateProject(id, d); loadData(); }} language={language} />}
            {editingMilestone && <EditMilestoneModal milestoneToEdit={editingMilestone} allMilestones={milestones} teams={lookups.teams} projects={projects} allMilestoneUpdates={[]} allUsers={users} currentUser={users.find(u => u.id === session.user.id)} onClose={() => setEditingMilestone(null)} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onAddUpdate={async () => {}} language={language} />}
            {viewingMilestone && <MilestoneDetailModal milestone={viewingMilestone} projects={projects} allMilestoneUpdates={[]} allUsers={users} lookups={lookups} onClose={() => setViewingMilestone(null)} language={language} />}
            {deletingProject && <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={async () => { await apiDeleteProject(deletingProject.id); setDeletingProject(null); loadData(); }} language={language} />}
            <button onClick={() => setIsChatbotOpen(true)} className="fixed bottom-8 right-8 rtl:left-8 rtl:right-auto bg-slate-900 text-white p-4 rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all z-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg></button>
            <Chatbot isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} language={language} projects={projects} milestones={milestones} users={users} lookups={lookups} />
        </div>
    );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Project, Milestone, Language, PaymentStatus } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';

const getCurrentMonthYearLabel = (lang: Language) => {
    const now = new Date();
    const month = now.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
    return `${month} ${now.getFullYear()}`;
};

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string }> = ({ title, children, maxHeight = 'none' }) => (
    <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl flex flex-col overflow-hidden h-full shadow-sm">
        <div className="flex justify-between items-center py-4 px-6 border-b border-slate-50 dark:border-slate-800/50">
            <h2 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">{title}</h2>
        </div>
        <div className="flex-grow overflow-y-auto custom-scrollbar px-6 py-5" style={{ maxHeight }}>{children}</div>
    </div>
);

const StatsOverviewWidget: React.FC<{ filteredProjects: Project[], filteredMilestones: Milestone[], language: Language }> = ({ filteredProjects = [], filteredMilestones = [], language }) => {
    const t = translations[language];
    const stats = useMemo(() => {
        let pendingVal = 0; let sentVal = 0; let paidVal = 0;
        filteredMilestones.forEach(m => {
            if (!m || !m.hasPayment) return;
            const amount = m.paymentAmount || 0;
            const status = m.paymentStatus || PaymentStatus.Pending;
            if (status === PaymentStatus.Pending) pendingVal += amount;
            else if (status === PaymentStatus.Sent) sentVal += amount;
            else if (status === PaymentStatus.Paid) paidVal += amount;
        });
        return { projectsCount: filteredProjects.length, pendingVal, sentVal, paidVal };
    }, [filteredProjects, filteredMilestones]);
    const formatVal = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <StatCard title={t.totalProjects} value={stats.projectsCount.toString()} icon="projects" />
            <StatCard title={t.filteredPending} value={formatVal(stats.pendingVal)} icon="inProgress" trendColor="text-orange-500" />
            <StatCard title={t.filteredSent} value={formatVal(stats.sentVal)} icon="completed" trendColor="text-blue-500" />
            <StatCard title={t.filteredPaid} value={formatVal(stats.paidVal)} icon="hours" trendColor="text-emerald-500" />
        </div>
    );
};

const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones = [], language }) => {
    const t = translations[language];
    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();
        filteredMilestones.forEach(m => {
            if (!m || !m.dueDate || !m.hasPayment) return;
            const date = new Date(m.dueDate);
            if (isNaN(date.getTime())) return;
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();
            if (!groups.has(labelKey)) groups.set(labelKey, { totalAmount: 0, sortKey });
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });
        return Array.from(groups.entries()).map(([monthYear, data]) => ({ monthYear, ...data })).sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);
    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 1);
    return (
        <WidgetWrapper title={t.executionChartTitle}>
            <div className="h-40 flex items-end gap-2 pt-6 min-w-0">
                {graphData.map((d, i) => (
                    <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                        <div style={{ height: `${(d.totalAmount / maxAmount) * 100}%` }} className="w-full max-w-[20px] bg-slate-100 dark:bg-slate-800 rounded-t group-hover:bg-violet-500 transition-all duration-300" />
                        <span className="text-[7px] font-bold text-slate-400 mt-2 truncate w-full text-center">{d.monthYear.split(' ')[0]}</span>
                    </div>
                ))}
                {graphData.length === 0 && <div className="w-full text-center text-slate-300 text-[10px] py-10 uppercase font-black">{t.noData}</div>}
            </div>
        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], language: Language }> = ({ projectsWithMilestones = [], language }) => {
    const t = translations[language];
    const [expandedPeriods, setExpandedPeriods] = useState<Record<string, boolean>>({});
    const [searchTerm, setSearchTerm] = useState('');

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();
        projectsWithMilestones.forEach(p => {
            if (!p) return;
            if (searchTerm && !p.name.toLowerCase().includes(searchTerm.toLowerCase())) return;
            (p.milestones || []).forEach((m: any) => {
                if (!m || !m.dueDate) return;
                const date = new Date(m.dueDate);
                if (isNaN(date.getTime())) return;
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!dateGroups.has(label)) dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0, statusCounts: { Paid: 0, Sent: 0, Pending: 0 } };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) {
                    projInGroup.groupTotal += (m.paymentAmount || 0);
                    projInGroup.statusCounts[m.paymentStatus || 'Pending']++;
                }
            });
        });
        return Array.from(dateGroups.values()).sort((a, b) => a.sortKey - b.sortKey);
    }, [projectsWithMilestones, language, searchTerm]);

    const formatCurrency = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="600px">
            <div className="mb-4 relative">
                <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder={t.quickSearch} className="w-full pl-9 pr-4 py-2.5 text-[10px] font-black uppercase bg-slate-50 dark:bg-slate-800 border-none rounded-xl outline-none focus:ring-1 focus:ring-violet-500" />
                <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
            <div className="space-y-3">
                {aggregatedByDate.length > 0 ? aggregatedByDate.map((period, pIdx) => {
                    const isOpen = !!expandedPeriods[period.monthYear];
                    return (
                        <div key={pIdx} className="rounded-2xl border border-slate-50 dark:border-slate-800 overflow-hidden">
                            <button onClick={() => setExpandedPeriods(prev => ({ ...prev, [period.monthYear]: !isOpen }))} className={`w-full flex items-center justify-between p-4 transition-all ${isOpen ? 'bg-slate-50 dark:bg-slate-800' : 'bg-white dark:bg-slate-900 hover:bg-slate-50/50'}`}>
                                <div className="flex items-center gap-3">
                                    <div className={`w-5 h-5 rounded flex items-center justify-center transition-transform ${isOpen ? 'rotate-180' : ''}`}><svg className="w-3.5 h-3.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg></div>
                                    <h3 className="text-xs font-black text-slate-700 dark:text-slate-200">{period.monthYear}</h3>
                                </div>
                                <p className="text-xs font-black text-slate-900 dark:text-white">{formatCurrency(period.projects.reduce((s, p) => s + p.groupTotal, 0))}</p>
                            </button>
                            {isOpen && (
                                <div className="p-3 bg-white dark:bg-slate-900 grid grid-cols-1 md:grid-cols-2 gap-2 border-t border-slate-50 dark:border-slate-800">
                                    {period.projects.map((proj, prIdx) => {
                                        const totalM = proj.milestonesInGroup.length || 1;
                                        return (
                                            <div key={prIdx} className="p-3 bg-slate-50/30 dark:bg-slate-800/30 border border-slate-50 dark:border-slate-800 rounded-xl">
                                                <div className="flex justify-between items-start mb-2">
                                                    <h4 className="text-[10px] font-black text-slate-800 dark:text-white truncate max-w-[120px]">{proj.name}</h4>
                                                    <span className="text-[10px] font-black text-violet-600">{formatCurrency(proj.groupTotal)}</span>
                                                </div>
                                                <div className="h-1 bg-slate-200 dark:bg-slate-700 rounded-full flex overflow-hidden">
                                                    <div className="bg-emerald-500 h-full" style={{ width: `${(proj.statusCounts.Paid / totalM) * 100}%` }}></div>
                                                    <div className="bg-blue-500 h-full" style={{ width: `${(proj.statusCounts.Sent / totalM) * 100}%` }}></div>
                                                    <div className="bg-orange-500 h-full" style={{ width: `${(proj.statusCounts.Pending / totalM) * 100}%` }}></div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    );
                }) : <div className="py-10 text-center opacity-30 text-[10px] font-black uppercase tracking-widest">{t.noData}</div>}
            </div>
        </WidgetWrapper>
    );
};

const translations = {
    ar: { dashboard: "لوحة التحكم", overview: "نظرة عامة على التدفقات المالية.", totalProjects: "المشاريع", filteredPending: "معلقة", filteredSent: "مرسلة", filteredPaid: "مدفوعة", executionChartTitle: "النمو الشهري", executionAggregation: "تجميع التدفقات", noData: "لا توجد بيانات.", quickSearch: "بحث...", customize: "تخصيص", allProjects: "كل المشاريع", allMonths: "كل الشهور", allManagers: "كل المدراء", clearFilters: "مسح" },
    en: { dashboard: "Dashboard", overview: "Financial cashflow overview.", totalProjects: "Projects", filteredPending: "Pending", filteredSent: "Invoiced", filteredPaid: "Collected", executionChartTitle: "Monthly Growth", executionAggregation: "Flow Aggregation", noData: "No data found.", quickSearch: "Search...", customize: "Customize", allProjects: "All Projects", allMonths: "All Months", allManagers: "All Managers", clearFilters: "Clear" }
};

export const WIDGETS_CONFIG = [
    { id: 'stats', name: 'KPIs', component: StatsOverviewWidget, default: true, colSpan: 4 },
    { id: 'aggregated_execution', name: 'Aggregation', component: AggregatedSummaryWidget, default: true, colSpan: 4 },
    { id: 'execution_chart', name: 'Growth', component: ExecutionPerformanceChartWidget, default: true, colSpan: 4 },
];

const AnalyticsDashboard: React.FC<any> = ({ projects = [], milestones = [], projectManagers = [], language }) => {
    const t = translations[language];
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [globalMonthYear, setGlobalMonthYear] = useState<string[]>([]);
    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });
    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);

    useEffect(() => {
        setGlobalMonthYear([getCurrentMonthYearLabel(language)]);
    }, [language]);

    const monthYearOptions = useMemo(() => {
        const unique = new Set<string>();
        milestones.forEach(m => { if (m && m.dueDate) { const d = new Date(m.dueDate); if(!isNaN(d.getTime())) unique.add(`${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`); } });
        unique.add(getCurrentMonthYearLabel(language));
        return Array.from(unique).map(v => ({ value: v, label: v }));
    }, [milestones, language]);

    const { filteredProjects, filteredMilestones } = useMemo(() => {
        const fps = projects.filter((p: any) => p && (globalProjectId === 'all' || p.id === globalProjectId) && (globalManagerId === 'all' || p.projectManagerId === globalManagerId));
        const pIds = new Set(fps.map((p: any) => p.id));
        const fms = milestones.filter((m: any) => {
            if (!m || !pIds.has(m.projectId)) return false;
            if (globalMonthYear.length > 0) {
                if (!m.dueDate) return false;
                const d = new Date(m.dueDate);
                if (isNaN(d.getTime())) return false;
                const l = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${d.getFullYear()}`;
                if (!globalMonthYear.includes(l)) return false;
            }
            return true;
        });
        return { filteredProjects: fps, filteredMilestones: fms };
    }, [projects, milestones, globalProjectId, globalManagerId, globalMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map((p: any) => ({ ...p, milestones: filteredMilestones.filter((m: any) => m.projectId === p.id) })).filter((p: any) => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    return (
        <div className="space-y-8 max-w-[1400px] mx-auto pb-20">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}
            <div className="flex justify-between items-center">
                <div><h1 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight uppercase">{t.dashboard}</h1><p className="text-slate-400 font-bold text-[10px] mt-1 uppercase tracking-widest">{t.overview}</p></div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-white dark:bg-slate-800 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-500 border border-slate-100 dark:border-slate-800 shadow-sm">{t.customize}</button>
            </div>
            <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-[2rem] border border-slate-100 dark:border-slate-800 flex flex-wrap gap-4">
                <div className="flex-1 min-w-[180px]"><SearchableSelect options={[{value:'all', label:t.allProjects}, ...projects.map((p: any) => ({value:p.id, label:p.name}))]} value={globalProjectId} onChange={setGlobalProjectId} placeholder={t.allProjects} language={language} /></div>
                <div className="flex-1 min-w-[180px]"><SearchableSelect options={[{value:'all', label:t.allManagers}, ...projectManagers.map((m: any) => ({value:m.id, label:m.name}))]} value={globalManagerId} onChange={setGlobalManagerId} placeholder={t.allManagers} language={language} /></div>
                <div className="flex-1 min-w-[180px]"><SearchableSelect isMulti options={monthYearOptions} value={globalMonthYear} onChange={setGlobalMonthYear} placeholder={t.allMonths} language={language} /></div>
                <button onClick={() => { setGlobalProjectId('all'); setGlobalManagerId('all'); setGlobalMonthYear([getCurrentMonthYearLabel(language)]); }} className="px-5 py-2 bg-slate-800 text-white text-[10px] font-black rounded-xl hover:bg-black transition-all uppercase tracking-widest">{t.clearFilters}</button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                {layout.map(id => { const c = WIDGETS_CONFIG.find(w => w.id === id); if(!c) return null; const Comp = c.component as any; return <div key={id} className={`lg:col-span-${c.colSpan}`}><Comp filteredProjects={filteredProjects} filteredMilestones={filteredMilestones} projectsWithMilestones={projectsWithMilestones} language={language} /></div>; })}
            </div>
        </div>
    );
};

